--
-- cấu trúc bảng `eb_agent_level`
--

CREATE TABLE IF NOT EXISTS `eb_agent_level` (
  `id` int(10) NOT NULL AUTO_INCREMENT COMMENT 'tự tăngID',
  `name` varchar(50) NOT NULL DEFAULT '' COMMENT 'Tên cấp độ',
  `image` varchar(255) NOT NULL DEFAULT '' COMMENT 'Hình nền',
  `one_brokerage` smallint(5) NOT NULL DEFAULT '0' COMMENT 'Điểm cấp 1 hỗ trợ tỷ lệ thả nổi',
  `one_brokerage_percent` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT 'Tỷ lệ hoa hồng cấp đầu tiên',
  `two_brokerage` smallint(5) NOT NULL DEFAULT '0' COMMENT 'Hỗ trợ tỷ lệ thả nổi cấp 2',
  `two_brokerage_percent` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT 'Tỷ lệ hoa hồng cấp hai',
  `grade` smallint(5) NOT NULL DEFAULT '0' COMMENT 'cấp',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT 'tình trạng',
  `is_del` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Có nên xóa không',
  `add_time` int(10) NOT NULL DEFAULT '0' COMMENT 'Thêm thời gian',
  `task_total_num` int(11) NOT NULL DEFAULT '0' COMMENT 'Tổng số nhiệm vụ',
  `task_num` int(11) NOT NULL DEFAULT '0' COMMENT 'Số lượng nhiệm vụ đã hoàn thành',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8 COMMENT='Bảng cấp độ nhà phân phối';

