--
-- cấu trúc bảng `eb_agent_level_task`
--

CREATE TABLE IF NOT EXISTS `eb_agent_level_task` (
  `id` int(10) NOT NULL AUTO_INCREMENT COMMENT 'tự tăngID',
  `level_id` int(10) NOT NULL DEFAULT '0' COMMENT 'Cấp độ phân phốiid',
  `name` varchar(50) NOT NULL DEFAULT '' COMMENT 'Tên nhiệm vụ',
  `type` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Loại nhiệm vụ',
  `number` int(10) NOT NULL DEFAULT '0' COMMENT 'Số giới hạn nhiệm vụ',
  `desc` varchar(255) NOT NULL DEFAULT '' COMMENT 'Mô tả nhiệm vụ',
  `is_must` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Có cần thiết phải đạt được0:một1:tất cả',
  `sort` smallint(5) NOT NULL DEFAULT '0' COMMENT 'loại',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT 'tình trạng',
  `is_del` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Có nên xóa không',
  `add_time` int(10) NOT NULL DEFAULT '0' COMMENT 'Thêm thời gian',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='Danh sách nhiệm vụ cấp nhà phân phối';

