-- cấu trúc bảng `eb_agent_level_task_record`
--

CREATE TABLE IF NOT EXISTS `eb_agent_level_task_record` (
  `id` int(10) NOT NULL AUTO_INCREMENT COMMENT 'tự tăngID',
  `uid` int(10) NOT NULL DEFAULT '0' COMMENT 'người dùnguid',
  `level_id` int(10) NOT NULL DEFAULT '0' COMMENT 'cấpid',
  `task_id` int(10) NOT NULL DEFAULT '0' COMMENT 'Nhiệm vụid',
  `status` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'tình trạng',
  `add_time` int(10) NOT NULL DEFAULT '0' COMMENT 'Thêm thời gian',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='Ghi lại biểu mẫu để nhà phân phối hoàn thành nhiệm vụ cấp độ';

