--
-- cấu trúc bảng `eb_agreement`
--

CREATE TABLE IF NOT EXISTS `eb_agreement` (
  `id` int(11) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'tự tăngID',
  `type` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Thỏa thuận loại 1: Thỏa thuận thành viên,2:Thỏa thuận đại lý',
  `title` varchar(200) NOT NULL DEFAULT '' COMMENT 'Tên giao thức',
  `content` longtext COMMENT 'Nội dung thỏa thuận',
  `sort` int(10) NOT NULL DEFAULT '0' COMMENT 'Sắp xếp theo thứ tự ngược lại',
  `status` tinyint(1) UNSIGNED NOT NULL DEFAULT '1' COMMENT '1：Hiển thị: 0: Không hiển thị',
  `add_time` int(50) NOT NULL DEFAULT '0' COMMENT 'Thêm thời gian',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `type` (`type`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=7 DEFAULT CHARSET=utf8 COMMENT='Thỏa thuận thành viên' ROW_FORMAT=DYNAMIC;

