  `id` int(10) NOT NULL AUTO_INCREMENT COMMENT 'tự tăngID',
  `version` varchar(20) CHARACTER SET utf8mb4 NOT NULL DEFAULT '' COMMENT 'số phiên bản',
  `platform` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'loại nền tảng:1.Android 2.IOS',
  `info` text COMMENT 'Thông tin nâng cấp',
  `url` varchar(1000) CHARACTER SET utf8mb4 NOT NULL DEFAULT '' COMMENT 'Liên kết tải xuống',
  `is_force` tinyint(1) NOT NULL DEFAULT '1' COMMENT 'Có buộc phải nâng cấp không',
  `is_new` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Đây có phải là cái mới nhất không',
  `is_del` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Có nên xóa không',
  `add_time` int(10) NOT NULL DEFAULT '0' COMMENT 'Thêm thời gian',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='APPbảng phiên bản';

