--
-- cấu trúc bảng `eb_article`
--

CREATE TABLE IF NOT EXISTS `eb_article` (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'Quản lý bài viếtID',
  `cid` varchar(255) NOT NULL DEFAULT '0' COMMENT 'Phân loạiid',
  `title` varchar(255) NOT NULL DEFAULT '' COMMENT 'Tiêu đề bài viết',
  `author` varchar(255) NOT NULL DEFAULT '' COMMENT 'tác giả bài viết',
  `image_input` varchar(255) NOT NULL DEFAULT '' COMMENT 'bài viết hình ảnh',
  `synopsis` varchar(255) NOT NULL DEFAULT '' COMMENT 'Giới thiệu bài viết',
  `share_title` varchar(255) NOT NULL DEFAULT '' COMMENT 'Tiêu đề bài viết chia sẻ',
  `share_synopsis` varchar(255) NOT NULL DEFAULT '' COMMENT 'Giới thiệu bài viết chia sẻ',
  `visit` varchar(255) NOT NULL DEFAULT '0' COMMENT 'Lượt xem',
  `sort` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'loại',
  `url` varchar(255) NOT NULL DEFAULT '' COMMENT 'Liên kết gốc',
  `status` tinyint(1) UNSIGNED NOT NULL DEFAULT '1' COMMENT 'tình trạng',
  `add_time` varchar(255) NOT NULL DEFAULT '' COMMENT 'Thêm thời gian',
  `hide` tinyint(1) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Có nên giấu không',
  `admin_id` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'quản trị viênid',
  `mer_id` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Thương giaid',
  `product_id` int(10) NOT NULL DEFAULT '0' COMMENT 'Hiệp hội sản phẩmid',
  `is_hot` tinyint(1) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Nó có phổ biến không?(Chương trình nhỏ)',
  `is_banner` tinyint(1) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Có quay vòng hình ảnh hay không(Chương trình nhỏ)',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='Bảng quản lý bài viết';

