--
-- cấu trúc bảng `eb_article_category`
--

CREATE TABLE IF NOT EXISTS `eb_article_category` (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'Phân loại bài viếtid',
  `pid` int(11) NOT NULL DEFAULT '0' COMMENT 'cha mẹID',
  `title` varchar(255) NOT NULL DEFAULT '' COMMENT 'Tiêu đề danh mục bài viết',
