  `add_time` varchar(255) NOT NULL DEFAULT '' COMMENT 'Thêm thời gian',
  `hidden` tinyint(1) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Có nên giấu không',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='Bảng phân loại bài viết';

