  `binding_id` int(10) NOT NULL DEFAULT '0' COMMENT 'ràng buộcid',
  `relation_id` int(10) NOT NULL DEFAULT '0' COMMENT 'sự kết hợpid',
  `type` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'kiểu0=Hỗ trợ chuyển dịch vụ khách hàng，1=Hỗ trợ sản phẩm và danh mục，2=Phiếu giảm giá và hỗ trợ sản phẩm',
  `other` varchar(500) NOT NULL DEFAULT '' COMMENT 'Các dữ liệu khác đượcjson',
  `update_time` int(10) NOT NULL DEFAULT '0' COMMENT 'Thời gian cập nhật',
  `add_time` int(10) NOT NULL DEFAULT '0' COMMENT 'Thêm thời gian',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='Bàn phụ';

