  `expire_time` int(11) NOT NULL DEFAULT '0' COMMENT 'Thời gian hết hạn0=Vĩnh viễn',
  `add_time` int(10) NOT NULL DEFAULT '0' COMMENT 'Thời gian lưu trữ',
  PRIMARY KEY (`key`) USING BTREE
