  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT 'số seri',
  `flow_id` varchar(32) NOT NULL DEFAULT '' COMMENT 'nước chảyid',
  `order_id` varchar(50) NOT NULL DEFAULT '' COMMENT 'sự kết hợpid',
  `uid` int(11) NOT NULL DEFAULT '0' COMMENT 'người dùngid',
  `nickname` varchar(255) NOT NULL DEFAULT '' COMMENT 'biệt danh',
  `phone` varchar(20) NOT NULL DEFAULT '' COMMENT 'Điện thoại',
  `price` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT 'Số tiền giao dịch',
  `trading_type` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'loại giao dịch',
  `pay_type` varchar(32) NOT NULL DEFAULT '' COMMENT 'Hình thức thanh toán',
  `mark` varchar(500) NOT NULL DEFAULT '' COMMENT 'Nhận xét',
  `add_time` int(11) NOT NULL DEFAULT '0' COMMENT 'giờ giao dịch',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='Báo cáo lưu chuyển vốn';

