  `id` int(10) NOT NULL AUTO_INCREMENT COMMENT 'tự tăngID',
  `pid` int(10) NOT NULL DEFAULT '0' COMMENT 'Thượng đẳngid',
  `owner_id` int(10) NOT NULL DEFAULT '0' COMMENT 'Thuộc về con người, cho tất cả',
  `name` varchar(255) COLLATE utf8_unicode_ci NOT NULL DEFAULT '' COMMENT 'Tên danh mục',
  `sort` int(10) NOT NULL DEFAULT '0' COMMENT 'loại',
  `type` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Kiểu phân loại0=Phân loại thẻ，1=Phân loại cụm từ viết tắt',
  `other` text COLLATE utf8_unicode_ci COMMENT 'Các thông số khác',
  `add_time` int(10) NOT NULL DEFAULT '0' COMMENT 'Thêm thời gian',
  PRIMARY KEY (`id`),
  KEY `pid` (`pid`),
  KEY `name` (`name`),
  KEY `is_be` (`owner_id`,`type`,`id`)
) ENGINE=InnoDB AUTO_INCREMENT=7 DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci COMMENT='Phân loại thẻ';

