-- cấu trúc bảng `eb_division_agent_apply`
--

CREATE TABLE IF NOT EXISTS `eb_division_agent_apply` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT 'tự tăngid',
  `uid` int(11) NOT NULL DEFAULT '0' COMMENT 'người dùnguid',
  `agent_name` varchar(255) NOT NULL DEFAULT '' COMMENT 'Tên đại lý',
  `name` varchar(255) NOT NULL DEFAULT '' COMMENT 'Tên người dùng',
  `phone` varchar(32) NOT NULL DEFAULT '0' COMMENT 'Số điện thoại đại lý',
  `division_id` int(11) NOT NULL DEFAULT '0' COMMENT 'Đơn vị kinh doanhid',
  `division_invite` int(11) NOT NULL DEFAULT '0' COMMENT 'Mã mời',
  `images` varchar(2000) NOT NULL DEFAULT '' COMMENT 'Áp dụng cho hình ảnh',
  `add_time` int(11) NOT NULL DEFAULT '0' COMMENT 'Thời gian nộp đơn',
  `status` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Trạng thái đơn đăng ký: 0 đơn đăng ký, 1 đơn được chấp thuận, 2 bị từ chối',
  `refusal_reason` varchar(1000) NOT NULL DEFAULT '' COMMENT 'Lý do từ chối',
  `is_del` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Có nên xóa không',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='Mẫu đơn xin đại lý';

