--
-- cấu trúc bảng `eb_diy`
--

CREATE TABLE IF NOT EXISTS `eb_diy` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT 'tự tăngID',
  `version` varchar(255) NOT NULL DEFAULT '' COMMENT 'số phiên bản',
  `name` varchar(255) NOT NULL DEFAULT '' COMMENT 'Tên trang',
  `template_name` varchar(255) NOT NULL DEFAULT '' COMMENT 'Tên mẫu',
  `value` longtext COMMENT 'Dữ liệu trang',
  `default_value` longtext COMMENT 'Dữ liệu trang mặc định',
  `add_time` int(11) NOT NULL DEFAULT '0' COMMENT 'Thêm thời gian',
  `update_time` int(11) NOT NULL DEFAULT '0' COMMENT 'Thời gian cập nhật',
  `status` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Có nên sử dụng không',
  `type` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Loại trang',
  `is_show` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Hiển thị trang chủ',
  `is_bg_color` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Màu sắc có được chọn không?',
  `is_bg_pic` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Hình nền có được chọn không?',
  `color_picker` varchar(50) NOT NULL DEFAULT '' COMMENT 'màu nền',
  `bg_pic` varchar(256) NOT NULL DEFAULT '' COMMENT 'Hình nền',
  `bg_tab_val` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Phong cách ảnh nền',
  `is_del` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Có nên xóa không',
  `order_status` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Phong cách đặt hàng trung tâm cá nhân',
  `my_banner_status` tinyint(1) NOT NULL DEFAULT '1' COMMENT 'Biểu ngữ trung tâm cá nhân có được hiển thị hay không',
  `my_menus_status` tinyint(1) NOT NULL DEFAULT '1' COMMENT 'Trung tâm cá nhân phong cách phục vụ của tôi',
  `business_status` tinyint(1) NOT NULL DEFAULT '1' COMMENT 'Phong cách quản lý thương gia của trung tâm cá nhân',
  `is_diy` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'liệudiy',
  `title` varchar(255) NOT NULL DEFAULT '' COMMENT 'diyđứng đầutitle',
  `is_pro` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Đây có phải là phiên bản mới không?',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8 COMMENT='DIYbảng dữ liệu';

