--
-- cấu trúc bảng `eb_express`
--

CREATE TABLE IF NOT EXISTS `eb_express` (
  `id` int(11) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'công ty chuyển phát nhanhid',
  `code` varchar(50) NOT NULL DEFAULT '' COMMENT 'Tên viết tắt của công ty chuyển phát nhanh',
  `name` varchar(50) NOT NULL DEFAULT '' COMMENT 'Tên đầy đủ của công ty chuyển phát nhanh',
  `partner_id` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Bạn có cần một tài khoản thanh toán hàng tháng?',
  `partner_key` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Bạn có cần mật khẩu thanh toán hàng tháng không?',
  `net` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Bạn có cần lấy hàng từ cửa hàng trực tuyến không?',
  `check_man` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Có nên điền vào biểu mẫu điện tử để mang tên người chuyển phát nhanh hay không',
  `partner_name` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Có nên điền tên tài khoản khách hàng vào biểu mẫu điện tử hay không',
  `is_code` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Có nên điền vào mẫu điện tử mang số',
  `courier_name` varchar(100) NOT NULL DEFAULT '' COMMENT 'Tên hãng vận chuyển chuyển phát nhanh',
  `customer_name` varchar(100) NOT NULL DEFAULT '' COMMENT 'Tên tài khoản khách hàng',
  `code_name` varchar(100) NOT NULL DEFAULT '' COMMENT 'Số mang biểu mẫu điện tử',
  `account` varchar(100) NOT NULL DEFAULT '' COMMENT 'tài khoản',
  `key` varchar(100) NOT NULL DEFAULT '' COMMENT 'mật khẩu',
  `net_name` varchar(100) NOT NULL DEFAULT '' COMMENT 'Tên cửa hàng',
  `sort` int(11) NOT NULL DEFAULT '0' COMMENT 'loại',
  `is_show` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Có hiển thị hay không',
  `status` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Nó có sẵn không',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `code` (`code`) USING BTREE,
  KEY `is_show` (`is_show`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=1102 DEFAULT CHARSET=utf8 COMMENT='Bảng công ty chuyển phát nhanh';

