CREATE TABLE IF NOT EXISTS `eb_lang_type` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT 'tự tăngID',
  `language_name` varchar(50) NOT NULL DEFAULT '' COMMENT 'Tên ngôn ngữ',
  `file_name` varchar(20) DEFAULT '' COMMENT 'Tên hồ sơ',
  `status` tinyint(1) NOT NULL DEFAULT '0' COMMENT '1Bật 0 Tắt',
  `is_default` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Cho dù ngôn ngữ mặc định',
  `is_del` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Có nên xóa không',
  PRIMARY KEY (`id`),
  UNIQUE KEY `id` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=11 DEFAULT CHARSET=utf8 COMMENT='loại ngôn ngữ';

