--
-- cấu trúc bảng `eb_live_anchor`
--

CREATE TABLE IF NOT EXISTS `eb_live_anchor` (
  `id` int(10) NOT NULL AUTO_INCREMENT COMMENT 'tự tăngID',
  `name` varchar(50) NOT NULL DEFAULT '' COMMENT 'Tên neo',
  `cover_img` varchar(255) NOT NULL DEFAULT '' COMMENT 'Hình ảnh neo',
  `wechat` varchar(50) NOT NULL DEFAULT '' COMMENT 'ID WeChat cố định',
  `phone` varchar(32) NOT NULL DEFAULT '' COMMENT 'Số điện thoại',
  `is_show` tinyint(1) NOT NULL DEFAULT '1' COMMENT 'Có hiển thị hay không',
  `is_del` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Có nên xóa không',
  `add_time` int(10) NOT NULL DEFAULT '0' COMMENT 'Thêm thời gian',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='Bảng neo phát sóng trực tiếp';

-- --------------------------------------------------------

--
-- cấu trúc bảng `eb_live_goods`
--

CREATE TABLE IF NOT EXISTS `eb_live_goods` (
  `id` int(10) NOT NULL AUTO_INCREMENT COMMENT 'tự tăngID',
  `goods_id` int(10) NOT NULL DEFAULT '0' COMMENT 'sản phẩm WeChatID',
  `audit_id` int(10) NOT NULL DEFAULT '0' COMMENT 'Ôn tậpID',
  `product_id` int(10) NOT NULL DEFAULT '0' COMMENT 'hàng hóaid',
  `name` varchar(30) NOT NULL DEFAULT '' COMMENT 'Tên sản phẩm',
  `cover_img` varchar(255) NOT NULL DEFAULT '' COMMENT 'Liên kết hình ảnh sản phẩm',
  `url` varchar(255) NOT NULL DEFAULT '' COMMENT 'Link chương trình mini sản phẩm',
  `price_type` tinyint(1) NOT NULL DEFAULT '1' COMMENT 'loại giá（1:Giá cố định, đọc trường giá tại thời điểm này; 2:Phạm vi giá. Lúc này, trường giá là ranh giới bên trái và trường price2 là ranh giới bên phải.; 3:Giá ưu đãi. Tại thời điểm này, trường giá là giá gốc và trường price2 là giá hiện tại.；）',
  `cost_price` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT 'giá thành',
  `price` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT 'Giá cố định/giá thấp nhất',
  `price2` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT 'giá cao nhất',
  `audit_status` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Trạng thái xem xét (0: chưa được xem xét, 1: đang được xem xét，2:Đã vượt qua đánh giá, không đạt 3 đánh giá）',
  `third_part_tag` tinyint(1) NOT NULL DEFAULT '1' COMMENT '1、2：Điều đó có nghĩa là sản phẩm được thêm vào cho API, nếu không thì đó là sản phẩm được bảng điều khiển phát sóng trực tiếp thêm vào.',
  `sort` smallint(5) NOT NULL DEFAULT '0' COMMENT 'loại',
  `is_show` tinyint(1) NOT NULL DEFAULT '1' COMMENT 'Có hiển thị hay không',
  `is_del` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Có nên xóa không',
  `add_time` int(10) NOT NULL DEFAULT '0' COMMENT 'Thêm thời gian',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='Danh sách sản phẩm trực tiếp';

-- --------------------------------------------------------

--
-- cấu trúc bảng `eb_live_room`
--

CREATE TABLE IF NOT EXISTS `eb_live_room` (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'tự tăngID',
  `room_id` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Phòng phát sóng trực tiếp id',
  `name` varchar(32) NOT NULL DEFAULT '' COMMENT 'Tên phòng phát sóng trực tiếp',
  `cover_img` varchar(255) NOT NULL DEFAULT '' COMMENT 'Hình nền',
  `share_img` varchar(255) NOT NULL DEFAULT '' COMMENT 'Chia sẻ hình ảnh',
  `start_time` int(10) NOT NULL DEFAULT '0' COMMENT 'Thời gian bắt đầu kế hoạch phát sóng trực tiếp',
  `end_time` int(10) NOT NULL DEFAULT '0' COMMENT 'Thời gian kết thúc kế hoạch phát sóng trực tiếp',
  `anchor_name` varchar(50) NOT NULL DEFAULT '' COMMENT 'Biệt hiệu neo',
  `anchor_wechat` varchar(50) NOT NULL DEFAULT '' COMMENT 'ID WeChat cố định',
  `phone` varchar(32) NOT NULL DEFAULT '' COMMENT 'Neo số điện thoại di động',
  `type` tinyint(1) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Loại phòng phát sóng trực tiếp 【1: Phát trực tuyến đẩy, 0: Phát sóng trực tiếp trên thiết bị di động】',
  `screen_type` tinyint(1) UNSIGNED NOT NULL DEFAULT '1' COMMENT 'Màn hình ngang, màn hình dọc [1: màn hình ngang, 0: màn hình dọc】',
  `close_like` tinyint(1) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Có nên tắt thích không',
  `close_goods` tinyint(1) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Có nên đóng kệ không',
  `close_comment` tinyint(1) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Có đóng bình luận hay không',
  `error_msg` varchar(255) NOT NULL DEFAULT '' COMMENT 'Lý do thất bại',
  `status` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Xem lại trạng thái0=Chưa được xem xét1=Đánh giá WeChat2=Tán thành-1=Đánh giá không thành công',
  `live_status` smallint(5) UNSIGNED NOT NULL DEFAULT '102' COMMENT 'Trạng thái phát sóng trực tiếp 101: phát sóng trực tiếp, 102: chưa bắt đầu, 103 đã kết thúc, 104 bị cấm, 105: đã tạm dừng, 106: bất thường, 107: đã hết hạn',
  `mark` varchar(512) NOT NULL DEFAULT '' COMMENT 'Nhận xét',
  `replay_status` tinyint(1) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'trạng thái phát lại',
  `sort` smallint(5) NOT NULL DEFAULT '0' COMMENT 'loại',
  `is_show` tinyint(1) UNSIGNED NOT NULL DEFAULT '1' COMMENT 'Có hiển thị hay không',
  `is_del` tinyint(1) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Có nên xóa không',
  `add_time` int(10) NOT NULL DEFAULT '0' COMMENT 'Thêm thời gian',
  PRIMARY KEY (`id`,`phone`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='Lịch phòng phát sóng trực tiếp' ROW_FORMAT=DYNAMIC;

-- --------------------------------------------------------

--
-- cấu trúc bảng `eb_live_room_goods`
--

CREATE TABLE IF NOT EXISTS `eb_live_room_goods` (
  `live_room_id` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Phòng phát sóng trực tiếpid',
  `live_goods_id` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'hàng hóaid',
  KEY `broadcast_room_id` (`live_room_id`,`live_goods_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='Nhập bảng sản phẩm vào phòng phát sóng trực tiếp' ROW_FORMAT=DYNAMIC;

-- --------------------------------------------------------

--
-- cấu trúc bảng `eb_luck_lottery`
--

CREATE TABLE IF NOT EXISTS `eb_luck_lottery` (
  `id` int(10) NOT NULL AUTO_INCREMENT COMMENT 'tự tăngID',
  `type` tinyint(1) NOT NULL DEFAULT '1' COMMENT 'Loại xổ số1:Jiugongge 2: Big Roulette 3: Jiugongge phiên bản nâng cấp 4: Lucky Flop',
  `name` varchar(255) NOT NULL DEFAULT '' COMMENT 'Tên rút thăm may mắn',
  `desc` varchar(255) NOT NULL DEFAULT '' COMMENT 'Mô tả hoạt động',
  `image` varchar(255) NOT NULL DEFAULT '' COMMENT 'Hình nền sự kiện',
  `factor` tinyint(1) NOT NULL DEFAULT '1' COMMENT 'Tiêu thụ xổ số：1:Điểm 2: Số dư 3: Thanh toán đơn hàng thành công 4: Thực hiện theo 5: Đánh giá đơn hàng',
  `factor_num` smallint(5) NOT NULL DEFAULT '10' COMMENT 'Lấy số điều kiện để quay số',
  `attends_user` tinyint(1) NOT NULL DEFAULT '1' COMMENT 'Người dùng tham gia 1: tất cả 2: một số',
  `user_level` text COMMENT 'Cấp độ người dùng tham gia',
  `user_label` text COMMENT 'Thẻ người dùng tham gia',
  `is_svip` tinyint(1) NOT NULL DEFAULT '1' COMMENT 'Liệu người dùng tham gia có phải là thành viên trả phí hay không',
  `prize_num` smallint(5) NOT NULL DEFAULT '0' COMMENT 'Số lượng giải thưởng',
  `start_time` int(11) NOT NULL DEFAULT '0' COMMENT 'thời gian bắt đầu',
  `end_time` int(11) NOT NULL DEFAULT '0' COMMENT 'thời gian kết thúc',
  `lottery_num_term` tinyint(1) NOT NULL DEFAULT '1' COMMENT 'Giới hạn số lần rút thăm: 1: mỗi ngày 2: mỗi người',
  `lottery_num` smallint(5) NOT NULL DEFAULT '1' COMMENT 'Số lần rút thăm',
  `spread_num` smallint(5) NOT NULL DEFAULT '1' COMMENT 'Theo dõi khuyến mãi để nhận số lần rút thăm',
  `is_all_record` tinyint(1) NOT NULL DEFAULT '1' COMMENT 'Hiển thị kỷ lục chiến thắng',
  `is_personal_record` tinyint(1) NOT NULL DEFAULT '1' COMMENT 'Hiển thị kỷ lục chiến thắng cá nhân',
  `is_content` tinyint(1) NOT NULL DEFAULT '1' COMMENT 'Liệu thông số sự kiện có được hiển thị hay không',
  `content` longtext COMMENT 'Viết quảng cáo sự kiện, thỏa thuận xổ số, v.v.',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT 'tình trạng',
  `is_use` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Có nên sử dụng không',
  `sort` smallint(5) NOT NULL DEFAULT '0' COMMENT 'loại',
  `is_del` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Có nên xóa không',
  `add_time` int(11) NOT NULL DEFAULT '0' COMMENT 'Thêm thời gian',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8 COMMENT='Danh sách xổ số';

--
-- Truyền dữ liệu trong bảng `eb_luck_lottery`
--


-- --------------------------------------------------------

--
-- cấu trúc bảng `eb_luck_lottery_record`
--

CREATE TABLE IF NOT EXISTS `eb_luck_lottery_record` (
  `id` int(10) NOT NULL AUTO_INCREMENT COMMENT 'tự tăngID',
  `wechat_order_id` VARCHAR(255) NOT NULL DEFAULT '' COMMENT 'Đặt hàngid',
  `uid` int(10) NOT NULL DEFAULT '0' COMMENT 'người dùnguid',
  `lottery_id` int(10) NOT NULL DEFAULT '0' COMMENT 'Hoạt độngid',
  `prize_id` int(10) NOT NULL DEFAULT '0' COMMENT 'phần thưởngid',
  `type` tinyint(1) NOT NULL DEFAULT '1' COMMENT 'Loại giải thưởng 1: Không trúng giải 2: Điểm3:Số dư 4: phong bì màu đỏ5:Phiếu giảm giá 6: Sản phẩm trang web 7: Kinh nghiệm cấp độ 8: Cấp độ người dùng 9: Số ngày svip',
  `num` DECIMAL(10,2) NOT NULL DEFAULT '0.00' COMMENT 'Điểm, số dư, ngày svip, phong bì đỏ',
  `is_receive` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Có nhận được không',
  `receive_time` int(11) NOT NULL DEFAULT '0' COMMENT 'Thời gian thu thập',
  `receive_info` text COMMENT 'Địa chỉ thu hoạch, nhận xét, v.v.',
  `is_deliver` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Có gửi hàng không',
  `deliver_time` int(11) NOT NULL DEFAULT '0' COMMENT 'Thời gian xử lý vận chuyển',
  `deliver_info` text COMMENT 'Số hóa đơn, nhận xét, v.v.',
  `add_time` int(11) NOT NULL DEFAULT '0' COMMENT 'Thêm thời gian',
  `channel_type` VARCHAR(32) NOT NULL DEFAULT '' COMMENT 'Nguồn xổ số',
  `out_bill_no` varchar(255) NOT NULL DEFAULT '' COMMENT 'Số đơn đặt hàng của người bán',
  `transfer_bill_no` varchar(255) NOT NULL DEFAULT '' COMMENT 'tài khoản chuyển WeChat',
  `state` varchar(32) NOT NULL DEFAULT '' COMMENT 'Trạng thái tài liệu',
  `package_info` varchar(2000) NOT NULL DEFAULT '' COMMENT 'Chuyển đến thông tin gói của trang bộ sưu tập',
  `fail_reason` varchar(255) NOT NULL DEFAULT '' COMMENT 'Lý do thất bại',
  PRIMARY KEY (`id`),
  KEY `uid` (`uid`),
  KEY `prize_id` (`prize_id`),
  KEY `lottery_id` (`lottery_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='Biên bản xổ số';

-- --------------------------------------------------------

--
-- cấu trúc bảng `eb_luck_prize`
--

CREATE TABLE IF NOT EXISTS `eb_luck_prize` (
  `id` int(10) NOT NULL AUTO_INCREMENT COMMENT 'Khóa chính giải thưởngid',
  `type` tinyint(1) NOT NULL DEFAULT '1' COMMENT 'Loại giải thưởng 1: Không trúng giải 2: Điểm3:Số dư 4: phong bì màu đỏ5:Phiếu giảm giá 6: Sản phẩm trang web 7: Kinh nghiệm cấp độ 8: Cấp độ người dùng 9: Số ngày svip',
  `lottery_id` int(10) NOT NULL DEFAULT '0' COMMENT 'rút thăm trúng thưởngid',
  `name` varchar(255) NOT NULL DEFAULT '' COMMENT 'Tên giải thưởng',
  `prompt` varchar(255) NOT NULL DEFAULT '' COMMENT 'Mẹo chiến thắng',
  `image` varchar(255) NOT NULL DEFAULT '' COMMENT 'Hình ảnh giải thưởng',
  `chance` smallint(5) NOT NULL DEFAULT '10' COMMENT 'Cơ sở chiến thắng',
  `percent` DECIMAL(10,2) NOT NULL DEFAULT '0.00' COMMENT 'Xác suất chiến thắng',
  `total` smallint(5) NOT NULL DEFAULT '1' COMMENT 'Số lượng giải thưởng',
  `coupon_id` int(10) NOT NULL DEFAULT '0' COMMENT 'Phiếu giảm giá liên quanid',
  `product_id` int(10) NOT NULL DEFAULT '0' COMMENT 'Sản phẩm liên quanid',
  `unique` varchar(20) NOT NULL DEFAULT '' COMMENT 'Giá trị duy nhất của thông số kỹ thuật sản phẩm liên quan',
  `num` DECIMAL(10,2) NOT NULL DEFAULT '0' COMMENT 'Điểm kinh nghiệm Ngày thành viên',
  `sort` smallint(5) NOT NULL DEFAULT '0' COMMENT 'loại',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT 'tình trạng',
  `is_del` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Có nên xóa không',
  `add_time` int(11) NOT NULL DEFAULT '0' COMMENT 'Thêm thời gian',
  PRIMARY KEY (`id`),
  KEY `lottery_id` (`lottery_id`)
) ENGINE=InnoDB AUTO_INCREMENT=17 DEFAULT CHARSET=utf8 COMMENT='Danh mục sản phẩm xổ số';

--
-- Truyền dữ liệu trong bảng `eb_luck_prize`
--


-- --------------------------------------------------------

--
-- cấu trúc bảng `eb_member_card`
--

CREATE TABLE IF NOT EXISTS `eb_member_card` (
  `id` int(11) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'tự tăngID',
  `card_batch_id` int(11) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'lô thẻid',
  `card_number` varchar(20) CHARACTER SET utf8mb4 NOT NULL DEFAULT '' COMMENT 'số thẻ',
  `card_password` char(12) CHARACTER SET utf8mb4 NOT NULL DEFAULT '' COMMENT 'mật khẩu',
  `use_uid` int(11) NOT NULL DEFAULT '0' COMMENT 'người dùng',
  `use_time` int(10) NOT NULL DEFAULT '0' COMMENT 'thời gian sử dụng',
  `status` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Trạng thái thẻ: 0: bị đóng băng; 1: kích hoạt',
  `add_time` int(10) NOT NULL DEFAULT '0' COMMENT 'Thêm thời gian',
  `update_time` int(10) NOT NULL DEFAULT '0' COMMENT 'Thời gian cập nhật',
  PRIMARY KEY (`id`,`card_batch_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='Mẫu thẻ thành viên' ROW_FORMAT=DYNAMIC;

-- --------------------------------------------------------

--
-- cấu trúc bảng `eb_member_card_batch`
--

CREATE TABLE IF NOT EXISTS `eb_member_card_batch` (
  `id` int(11) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'tự tăngID',
  `title` varchar(100) NOT NULL DEFAULT '0' COMMENT 'Tên lô',
  `total_num` int(11) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Số lượng thẻ được tạo',
  `use_start_time` int(10) UNSIGNED NOT NULL DEFAULT '7' COMMENT 'Trải nghiệm thời gian bắt đầu',
  `use_end_time` int(10) NOT NULL DEFAULT '0' COMMENT 'Trải nghiệm thời gian kết thúc',
  `use_day` int(10) NOT NULL DEFAULT '0' COMMENT 'Ngày trải nghiệm',
  `use_num` int(11) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'sử dụng',
  `status` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Nó có hiệu quả không?,Kiểm soát tất cả các thẻ trong đợt này 0: Không hợp lệ; 1: Hợp lệ',
  `sort` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'loại',
  `qrcode` varchar(255) NOT NULL DEFAULT '' COMMENT 'Đường dẫn bản đồ mã QR',
  `remark` varchar(512) CHARACTER SET utf8mb4 NOT NULL DEFAULT '' COMMENT 'Nhận xét',
  `add_time` int(10) NOT NULL DEFAULT '0' COMMENT 'Thêm thời gian',
  `update_time` int(10) NOT NULL DEFAULT '0' COMMENT 'Thời gian cập nhật',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='Bảng lô thẻ thành viên' ROW_FORMAT=DYNAMIC;

-- --------------------------------------------------------

--
-- cấu trúc bảng `eb_member_right`
--

CREATE TABLE IF NOT EXISTS `eb_member_right` (
  `id` int(11) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'tự tăngID',
  `right_type` varchar(100) NOT NULL DEFAULT '' COMMENT 'Danh mục vốn sở hữu',
  `title` varchar(200) NOT NULL DEFAULT '' COMMENT ' Tên sở thích',
  `show_title` varchar(255) NOT NULL DEFAULT '' COMMENT 'Hiển thị tên sở thích',
  `image` varchar(200) CHARACTER SET utf8mb4 NOT NULL DEFAULT '' COMMENT 'biểu tượng vốn chủ sở hữu',
  `explain` varchar(1024) CHARACTER SET utf8mb4 NOT NULL DEFAULT '' COMMENT 'Giới thiệu về quyền và lợi ích',
  `number` int(2) NOT NULL DEFAULT '1' COMMENT 'số thường xuyên',
  `sort` int(10) NOT NULL DEFAULT '0' COMMENT 'Sắp xếp theo thứ tự ngược lại',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '0:Đã tắt, 1: đã bật',
  `add_time` int(10) NOT NULL DEFAULT '0' COMMENT 'Thêm thời gian',
  PRIMARY KEY (`id`,`right_type`) USING BTREE,
  KEY `type` (`right_type`)
) ENGINE=InnoDB AUTO_INCREMENT=7 DEFAULT CHARSET=utf8 COMMENT='Quyền thành viên' ROW_FORMAT=DYNAMIC;

--
-- Truyền dữ liệu trong bảng `eb_member_right`
--


-- --------------------------------------------------------

--
-- cấu trúc bảng `eb_member_ship`
--

CREATE TABLE IF NOT EXISTS `eb_member_ship` (
  `id` int(11) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'tự tăngID',
  `type` varchar(20) NOT NULL DEFAULT 'month' COMMENT 'Hạng mục thành viênmonth:Thành viên hàng tháng；quarter:thẻ mùa giải；year:Vé hàng năm；ever:Vĩnh viễn；free:miễn phí',
  `title` varchar(200) NOT NULL DEFAULT '' COMMENT 'Tên thành viên',
  `vip_day` int(10) NOT NULL DEFAULT '0' COMMENT 'thời gian thành viên(bầu trời)',
  `price` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT 'giá gốc',
  `pre_price` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT 'Giá sau giảm giá',
  `sort` int(10) NOT NULL DEFAULT '0' COMMENT 'Sắp xếp theo thứ tự ngược lại',
  `is_del` int(2) NOT NULL DEFAULT '0' COMMENT 'xóa bỏ',
  `add_time` int(10) NOT NULL DEFAULT '0' COMMENT 'Thêm thời gian',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `type` (`type`)
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8 COMMENT='Loại thành viên' ROW_FORMAT=DYNAMIC;

