-- Truyền dữ liệu trong bảng `eb_member_ship`
--


-- --------------------------------------------------------

--
-- cấu trúc bảng `eb_message_system`
--

CREATE TABLE IF NOT EXISTS `eb_message_system` (
  `id` int(10) NOT NULL AUTO_INCREMENT COMMENT 'tự tăngID',
  `mark` varchar(50) NOT NULL DEFAULT '' COMMENT 'biểu tượng',
  `uid` int(11) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'người dùngID',
  `title` varchar(256) NOT NULL DEFAULT '' COMMENT 'Tiêu đề thông báo',
  `content` varchar(512) NOT NULL DEFAULT '' COMMENT 'Nội dung thông báo',
  `data` varchar(5000) NOT NULL DEFAULT '' COMMENT 'Thông số tin nhắn trang web',
  `look` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Xem hay không',
  `type` tinyint(1) NOT NULL DEFAULT '0' COMMENT '1:Người dùng thông thường, 2: Quản trị viên',
  `add_time` int(11) NOT NULL DEFAULT '0' COMMENT 'Thời gian thông báo',
  `is_del` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Có nên xóa không',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='Thông báo hệ thống';

-- --------------------------------------------------------

--
-- cấu trúc bảng `eb_other_order`
--

CREATE TABLE IF NOT EXISTS `eb_other_order` (
  `id` int(11) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'tự tăngID',
  `uid` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'người dùnguid',
  `type` tinyint(1) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'sự khác biệt \r\n0：Nhận nó miễn phí\r\n1：Mua thẻ thành viên \r\n2：Bí mật thẻ nhận thẻ thành viên',
  `order_id` varchar(32) CHARACTER SET utf8mb4 NOT NULL DEFAULT '' COMMENT 'Số đơn hàng',
  `member_type` varchar(10) CHARACTER SET utf8mb4 NOT NULL DEFAULT '' COMMENT 'Loại thành viên \r\nthẻ hàng tháng：month\r\nthẻ mùa giải：quarter\r\nVé hàng năm：year\r\nVĩnh viễn：ever\r\nmiễn phí：free',
  `code` varchar(20) NOT NULL DEFAULT '' COMMENT 'số thẻ',
  `pay_type` varchar(32) CHARACTER SET utf8mb4 NOT NULL DEFAULT '' COMMENT 'Phương thức thanh toán',
  `paid` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Trạng thái thanh toán 0:  Chưa thanh toán 1: Đã thanh toán',
  `pay_price` decimal(12,2) UNSIGNED NOT NULL DEFAULT '0.00' COMMENT 'Số tiền thanh toán',
  `member_price` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT 'Giá thẻ thành viên',
  `pay_time` int(50) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Thời gian mua hàng của thành viên',
  `trade_no` varchar(50) CHARACTER SET utf8mb4 NOT NULL DEFAULT '' COMMENT 'thanh toán Alipay,Số thứ tự giao dịch Alipay',
  `channel_type` varchar(10) NOT NULL DEFAULT '' COMMENT 'kênh thanh toán(Applet tài khoản công khai WeChat h5)',
  `is_free` tinyint(1) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Nó có miễn phí không?',
  `is_permanent` tinyint(1) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Nó có vĩnh viễn không?',
  `overdue_time` bigint(20) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Thời gian hết hạn của thành viên',
  `is_del` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'xóa bỏ',
  `vip_day` int(10) NOT NULL DEFAULT '0' COMMENT 'Ngày hiệu lực của thành viên',
  `add_time` int(50) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Thêm thời gian',
  `money` decimal(12,2) UNSIGNED NOT NULL DEFAULT '0.00' COMMENT 'giá gốc',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='Mẫu hồ sơ mua hàng của thành viên' ROW_FORMAT=DYNAMIC;

-- --------------------------------------------------------

--
-- cấu trúc bảng `eb_other_order_status`
--

CREATE TABLE IF NOT EXISTS `eb_other_order_status` (
  `oid` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Đặt hàngid',
  `change_type` varchar(32) NOT NULL DEFAULT '' COMMENT 'Loại hoạt động',
  `change_message` varchar(256) NOT NULL DEFAULT '' COMMENT 'Ghi chú hoạt động',
  `shop_type` tinyint(1) NOT NULL DEFAULT '1' COMMENT 'Loại đơn hàng 1: Thẻ thành viên',
  `change_time` int(10) NOT NULL DEFAULT '0' COMMENT 'Thời gian sửa đổi đơn hàng',
  KEY `oid` (`oid`) USING BTREE,
  KEY `change_type` (`change_type`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='Mẫu hồ sơ hoạt động đặt hàng' ROW_FORMAT=DYNAMIC;

-- --------------------------------------------------------

--
-- cấu trúc bảng `eb_out_account`
--

CREATE TABLE IF NOT EXISTS `eb_out_account` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT 'tự tăngID',
  `appid` varchar(50) NOT NULL DEFAULT '' COMMENT 'tài khoản',
  `appsecret` varchar(100) NOT NULL DEFAULT '' COMMENT 'chìa khóa',
  `apppwd` varchar(255) NOT NULL DEFAULT '' COMMENT 'Văn bản thuần tuý chính',
  `title` varchar(200) NOT NULL DEFAULT '' COMMENT 'mô tả',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT 'tình trạng',
  `rules` text COMMENT 'Quyền',
  `add_time` int(11) NOT NULL DEFAULT '0' COMMENT 'Thêm thời gian',
  `last_time` int(11) NOT NULL DEFAULT '0' COMMENT 'Lần đăng nhập cuối cùng',
  `ip` varchar(30) NOT NULL DEFAULT '' COMMENT 'IP',
  `is_del` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Có nên xóa không',
  `push_open` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Có nên đẩy không',
  `push_account` varchar(255) NOT NULL COMMENT 'đẩy tài khoản',
  `push_password` varchar(255) NOT NULL COMMENT 'đẩy mật khẩu',
  `push_token_url` varchar(255) NOT NULL COMMENT 'Nhận giao diện mã thông báo đẩy',
  `user_update_push` varchar(255) NOT NULL COMMENT 'Giao diện đẩy người dùng',
  `order_create_push` varchar(255) NOT NULL DEFAULT '' COMMENT 'Giao diện đẩy tạo đơn hàng',
  `order_pay_push` varchar(255) NOT NULL DEFAULT '' COMMENT 'Giao diện đẩy thanh toán đơn hàng',
  `refund_create_push` varchar(255) NOT NULL DEFAULT '' COMMENT 'Giao diện đẩy tạo đơn hàng sau bán hàng',
  `refund_cancel_push` varchar(255) NOT NULL DEFAULT '' COMMENT 'Giao diện đẩy hủy đơn hàng sau bán hàng',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='Tài khoản giao diện bên ngoài' ROW_FORMAT=DYNAMIC;

-- --------------------------------------------------------

--
-- cấu trúc bảng `eb_out_interface`
--

CREATE TABLE IF NOT EXISTS `eb_out_interface` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT 'tự tăngid',
  `pid` int(11) NOT NULL DEFAULT '0' COMMENT 'cha mẹpid',
  `type` tinyint(1) NOT NULL DEFAULT '0' COMMENT '0Menu, 1 giao diện',
  `name` varchar(255) NOT NULL DEFAULT '' COMMENT 'Tên giao diện',
  `describe` text COMMENT 'Mô tả chức năng',
  `method` varchar(255) NOT NULL DEFAULT '' COMMENT 'Loại giao diện',
  `url` varchar(255) NOT NULL DEFAULT '' COMMENT 'địa chỉ giao diện',
  `request_params` text COMMENT 'Thông số yêu cầu',
  `return_params` text COMMENT 'Trả về tham số',
  `request_example` text COMMENT 'Yêu cầu ví dụ',
  `return_example` text COMMENT 'Trả về ví dụ',
  `error_code` text COMMENT 'trả lại lỗi',
  `is_del` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Có nên xóa không',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=52 DEFAULT CHARSET=utf8mb4 COMMENT='Giao diện bên ngoài';

