  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'Mã QR WeChatID',
  `third_type` varchar(32) NOT NULL DEFAULT '' COMMENT 'loại mã QR',
  `third_id` int(11) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'người dùngid',
  `ticket` varchar(255) NOT NULL DEFAULT '' COMMENT 'Thông số mã QR',
  `expire_seconds` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Thời gian hiệu lực của mã QR',
  `status` tinyint(1) UNSIGNED NOT NULL DEFAULT '1' COMMENT 'tình trạng',
  `add_time` varchar(255) NOT NULL DEFAULT '0' COMMENT 'Thêm thời gian',
  `url` varchar(255) NOT NULL DEFAULT '' COMMENT 'Truy cập WeChaturl',
  `qrcode_url` varchar(255) NOT NULL DEFAULT '' COMMENT 'Mã QR WeChaturl',
  `scan` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Số lần quét',
  `type` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Nền tảng mà mã QR thuộc về1=Chương trình nhỏ，2=Tài khoản chính thức，3=H5',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `third_type` (`third_type`,`third_id`) USING BTREE,
  KEY `ticket` (`ticket`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='Biểu mẫu quản lý mã QR WeChat' ROW_FORMAT=COMPACT;

