-- cấu trúc bảng `eb_sms_record`
--

CREATE TABLE IF NOT EXISTS `eb_sms_record` (
  `id` int(11) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'Số bản ghi gửi SMS',
  `uid` varchar(255) NOT NULL DEFAULT '' COMMENT 'Tài khoản nền tảng SMS',
  `phone` char(11) NOT NULL DEFAULT '' COMMENT 'Số điện thoại di động để nhận tin nhắn',
  `content` text COMMENT 'nội dung tin nhắn SMS',
  `add_time` int(11) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Gửi tin nhắn SMS thời gian',
  `add_ip` varchar(16) NOT NULL DEFAULT '' COMMENT 'Thêm bản ghiip',
  `template` varchar(255) NOT NULL DEFAULT '' COMMENT 'mẫu tin nhắnID',
  `resultcode` int(6) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'mã trạng thái 100=thành công,130=thất bại,131=Số trống,132=tắt máy,133=Tắt máy,134=không quốc tịch',
  `record_id` int(11) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Gửi bản ghiid',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='Bảng ghi gửi tin nhắn SMS';

