--
-- cấu trúc bảng `eb_store_advance`
--

CREATE TABLE IF NOT EXISTS `eb_store_activity` (
  `id` int(10) NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `type` tinyint(1) NOT NULL DEFAULT '1' COMMENT '1:bán chớp nhoáng',
  `title` varchar(255) NOT NULL DEFAULT '' COMMENT 'Tên hoạt động',
  `start_day` int(10) NOT NULL DEFAULT '0' COMMENT 'ngày bắt đầu',
  `end_day` int(10) NOT NULL DEFAULT '0' COMMENT 'ngày kết thúc',
  `time_ids` varchar(255) NOT NULL DEFAULT '' COMMENT 'Nhiều ID khoảng thời gian',
  `once_num` int(10) unsigned NOT NULL DEFAULT '0' COMMENT 'Số lượng mua hàng ngày của mỗi người trong sự kiện là 0, không giới hạn',
  `num` int(10) unsigned NOT NULL DEFAULT '0' COMMENT 'Trong mọi hoạt động, tổng số lần mua hàng của người dùng bị giới hạn, 0 không giới hạn',
  `is_commission` int(11) NOT NULL DEFAULT '0' COMMENT 'Có nên tham gia chia sẻ hoa hồng hay không',
  `status` tinyint(1) unsigned NOT NULL DEFAULT '0' COMMENT 'Có hiển thị hay không',
  `link_id` int(4) unsigned NOT NULL DEFAULT '0' COMMENT 'sự kết hợpID',
  `is_del` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Có nên xóa không',
  `add_time` int(10) NOT NULL DEFAULT '0' COMMENT 'Thêm thời gian',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `start_day` (`start_day`,`end_day`) USING BTREE,
  KEY `type` (`type`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='bảng hoạt động';

-- --------------------------------------------------------

--
-- cấu trúc bảng `eb_store_advance`
--

CREATE TABLE IF NOT EXISTS `eb_store_advance` (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'Các mặt hàng bán trướcid',
  `product_id` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'hàng hóaid',
  `image` varchar(255) NOT NULL DEFAULT '' COMMENT 'Hình ảnh chính của sản phẩm',
  `images` varchar(2000) NOT NULL DEFAULT '' COMMENT 'băng chuyền',
  `title` varchar(255) NOT NULL DEFAULT '' COMMENT 'Tiêu đề sự kiện',
  `info` varchar(255) NOT NULL DEFAULT '' COMMENT 'Giới thiệu',
  `price` decimal(12,2) UNSIGNED NOT NULL DEFAULT '0.00' COMMENT 'giá',
  `ot_price` decimal(12,2) UNSIGNED NOT NULL DEFAULT '0.00' COMMENT 'giá gốc',
  `sort` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'loại',
  `stock` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'trong kho',
  `sales` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Doanh số bán hàng',
  `unit_name` varchar(16) NOT NULL DEFAULT '' COMMENT 'Tên đơn vị',
  `start_time` varchar(128) NOT NULL DEFAULT '' COMMENT 'thời gian bắt đầu',
  `stop_time` varchar(128) NOT NULL DEFAULT '' COMMENT 'thời gian kết thúc',
  `add_time` varchar(128) NOT NULL DEFAULT '' COMMENT 'Thêm thời gian',
  `status` tinyint(1) UNSIGNED NOT NULL DEFAULT '1' COMMENT 'Tình trạng sản phẩm',
  `is_del` tinyint(1) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Xóa 0 Chưa xóa 1 Đã xóa',
  `type` tinyint(1) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Loại 0 thanh toán đầy đủ 1 đặt cọc',
  `deposit` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT 'Số tiền gửi',
  `pay_start_time` varchar(128) NOT NULL DEFAULT '' COMMENT 'Thời gian bắt đầu thanh toán cuối cùng',
  `pay_stop_time` varchar(128) NOT NULL DEFAULT '' COMMENT 'Thời gian kết thúc thanh toán cuối cùng',
  `deliver_time` int(10) NOT NULL DEFAULT '0' COMMENT 'Vận chuyển một vài ngày sau khi thanh toán',
  `num` int(11) UNSIGNED NOT NULL DEFAULT '1' COMMENT 'Mua tối đa bao nhiêu',
  `temp_id` int(11) NOT NULL DEFAULT '0' COMMENT 'Mẫu vận chuyển hàng hóaID',
  `quota` int(10) NOT NULL DEFAULT '0' COMMENT 'Tổng giới hạn mua hàng',
  `quota_show` int(10) NOT NULL DEFAULT '0' COMMENT 'Hiển thị tổng giới hạn mua',
  `once_num` int(11) NOT NULL DEFAULT '0' COMMENT 'Số lượng mua một lần',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='Danh sách sản phẩm trước khi bán';

-- --------------------------------------------------------

--
-- cấu trúc bảng `eb_store_bargain`
--

CREATE TABLE IF NOT EXISTS `eb_store_bargain` (
  `id` int(11) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'mặt hàng giá hờiID',
  `product_id` int(11) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Sản phẩm liên quanID',
  `title` varchar(255) NOT NULL DEFAULT '' COMMENT 'Tên hoạt động mặc cả',
  `image` varchar(150) NOT NULL DEFAULT '' COMMENT 'Hình ảnh hoạt động giao lưu',
  `unit_name` varchar(16) NOT NULL DEFAULT '' COMMENT 'Tên đơn vị',
  `stock` int(11) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'trong kho',
  `sales` int(11) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Doanh số bán hàng',
  `images` varchar(2000) NOT NULL DEFAULT '' COMMENT 'Biểu đồ băng chuyền sản phẩm giảm giá',
  `start_time` int(11) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Thời gian mở cửa giao dịch',
  `stop_time` int(11) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Thời gian kết thúc thương lượng',
  `store_name` varchar(255) NOT NULL DEFAULT '' COMMENT 'Tên sản phẩm khuyến mãi',
  `price` decimal(12,2) UNSIGNED NOT NULL DEFAULT '0.00' COMMENT 'Số tiền mặc cả',
  `min_price` decimal(12,2) UNSIGNED NOT NULL DEFAULT '0.00' COMMENT 'Mua bán sản phẩm với giá thấp nhất',
  `num` int(11) UNSIGNED NOT NULL DEFAULT '1' COMMENT 'Số lượng mặt hàng giá hời có sẵn để mua',
  `bargain_max_price` decimal(12,2) UNSIGNED NOT NULL DEFAULT '0.00' COMMENT 'Số tiền tối đa người dùng có thể mặc cả cho mỗi lần',
  `bargain_min_price` decimal(12,2) UNSIGNED NOT NULL DEFAULT '0.00' COMMENT 'Số tiền tối thiểu cho mỗi lần thương lượng của người dùng',
  `bargain_num` int(11) UNSIGNED NOT NULL DEFAULT '1' COMMENT 'Số lần người dùng giúp cắt',
  `status` tinyint(1) UNSIGNED NOT NULL DEFAULT '1' COMMENT 'Tình trạng thương lượng 0(Nó sẽ không tự động bật khi đến lúc phải mặc cả.)  1(Tự động bật thời gian khi đến thời điểm thương lượng)',
  `give_integral` decimal(12,2) UNSIGNED NOT NULL DEFAULT '0.00' COMMENT 'Có bao nhiêu điểm nghịch đảo',
  `info` varchar(255) NOT NULL DEFAULT '' COMMENT 'Giới thiệu về hoạt động thương lượng',
  `cost` decimal(12,2) UNSIGNED NOT NULL DEFAULT '0.00' COMMENT 'giá thành',
  `sort` int(11) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'loại',
  `is_hot` tinyint(1) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Khuyến nghị hay không 0 Không khuyến nghị 1 Khuyến nghị',
  `is_del` tinyint(1) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Có nên xóa 0 không xóa 1 xóa',
  `add_time` int(11) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Thêm thời gian',
  `is_postage` tinyint(1) UNSIGNED NOT NULL DEFAULT '1' COMMENT 'Có miễn phí vận chuyển hay không 0 Không vận chuyển 1 Miễn phí vận chuyển',
  `postage` decimal(12,2) UNSIGNED NOT NULL DEFAULT '0.00' COMMENT 'Bưu phí',
  `rule` longtext COMMENT 'quy tắc thương lượng',
  `look` int(11) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Lượt xem sản phẩm mặc cả',
  `share` int(11) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Số lượng mặt hàng mặc cả được chia sẻ',
  `temp_id` int(11) NOT NULL DEFAULT '0' COMMENT 'Mẫu vận chuyển hàng hóaID',
  `weight` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT 'cân nặng',
  `volume` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT 'âm lượng',
  `quota` int(10) NOT NULL DEFAULT '0' COMMENT 'Tổng giới hạn mua hàng',
  `quota_show` int(10) NOT NULL DEFAULT '0' COMMENT 'Tổng số hiển thị hạn chế',
  `people_num` int(11) NOT NULL DEFAULT '1' COMMENT 'Số lần người dùng giúp cắt',
  `logistics` varchar(11) NOT NULL DEFAULT '1,2' COMMENT 'Phương pháp hậu cần',
  `freight` tinyint(1) NOT NULL DEFAULT '2' COMMENT 'Cài đặt phí vận chuyển',
  `custom_form` varchar(2000) NOT NULL DEFAULT '' COMMENT 'Biểu mẫu tùy chỉnh',
  `virtual_type` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Loại sản phẩm',
  `is_commission` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Có nên giảm giá hoa hồng hay không',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='danh sách thương lượng';

-- --------------------------------------------------------

--
-- cấu trúc bảng `eb_store_bargain_user`
--

CREATE TABLE IF NOT EXISTS `eb_store_bargain_user` (
  `id` int(11) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'Bảng thương lượng sự tham gia của người dùngID',
  `uid` int(11) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'người dùngID',
  `bargain_id` int(11) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'mặt hàng giá hờiid',
  `bargain_price_min` decimal(12,2) UNSIGNED NOT NULL DEFAULT '0.00' COMMENT 'Mặc cả giá thấp nhất',
  `bargain_price` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT 'Số tiền mặc cả',
  `price` decimal(12,2) UNSIGNED NOT NULL DEFAULT '0.00' COMMENT 'giảm giá',
  `status` tinyint(1) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Trạng thái 1 Tham gia 2 Tham gia không thành công sau khi sự kiện kết thúc 3 Tham gia thành công sau khi sự kiện kết thúc',
  `add_time` int(11) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'thời gian tham gia',
  `is_del` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Hủy hay không',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='Bảng thương lượng sự tham gia của người dùng';

-- --------------------------------------------------------

--
-- cấu trúc bảng `eb_store_bargain_user_help`
--

CREATE TABLE IF NOT EXISTS `eb_store_bargain_user_help` (
  `id` int(11) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'Bảng trợ giúp người dùng thương lượngID',
  `uid` int(11) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Giúp đỡ người dùngid',
  `bargain_id` int(11) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'mặt hàng giá hờiID',
  `bargain_user_id` int(11) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Bảng thương lượng sự tham gia của người dùngid',
  `price` decimal(12,2) UNSIGNED NOT NULL DEFAULT '0.00' COMMENT 'Bạn có thể giúp tôi thương lượng bao nhiêu?',
  `add_time` int(11) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Thêm thời gian',
  `type` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Có nên mặc cả với chính mình không',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='Bảng trợ giúp người dùng thương lượng';

-- --------------------------------------------------------

--
-- cấu trúc bảng `eb_store_cart`
--

CREATE TABLE IF NOT EXISTS `eb_store_cart` (
  `id` bigint(8) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'bàn giỏ hàngID',
  `uid` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'người dùngID',
  `type` varchar(32) NOT NULL DEFAULT '' COMMENT 'kiểu',
  `product_id` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'hàng hóaID',
  `product_attr_unique` varchar(16) NOT NULL DEFAULT '' COMMENT 'Thuộc tính sản phẩm',
  `cart_num` smallint(5) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'số lượng sản phẩm',
  `add_time` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Thêm thời gian',
  `is_pay` tinyint(1) NOT NULL DEFAULT '0' COMMENT '0 = Chưa mua 1 = Đã mua',
  `is_del` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Có nên xóa không',
  `is_new` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Có nên mua bây giờ không',
  `combination_id` int(11) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Chia sẻ nhómid',
  `seckill_id` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'mặt hàng flash saleID',
  `bargain_id` int(11) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Mặc cảid',
  `advance_id` int(10) NOT NULL DEFAULT '0' COMMENT 'Các mặt hàng bán trướcid',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT 'Trạng thái mặt hàng trong giỏ hàng',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `goods_id` (`product_id`) USING BTREE,
  KEY `uid` (`uid`,`is_pay`) USING BTREE,
  KEY `uid_2` (`uid`,`is_del`) USING BTREE,
  KEY `uid_3` (`uid`,`is_new`) USING BTREE,
  KEY `type` (`type`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='bàn giỏ hàng' ROW_FORMAT=COMPACT;

-- --------------------------------------------------------

--
-- cấu trúc bảng `eb_store_category`
--

CREATE TABLE IF NOT EXISTS `eb_store_category` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT 'Bảng phân loại sản phẩmID',
  `pid` int(11) NOT NULL DEFAULT '0' COMMENT 'bốid',
  `cate_name` varchar(100) NOT NULL DEFAULT '' COMMENT 'Tên danh mục',
  `sort` int(11) NOT NULL DEFAULT '0' COMMENT 'loại',
  `pic` varchar(128) NOT NULL DEFAULT '' COMMENT 'biểu tượng',
  `is_show` tinyint(1) NOT NULL DEFAULT '1' COMMENT 'Nó có được khuyến khích không?',
  `add_time` int(11) NOT NULL DEFAULT '0' COMMENT 'Thêm thời gian',
  `big_pic` varchar(255) NOT NULL DEFAULT '' COMMENT 'Phân loại hình ảnh lớn',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `pid` (`pid`) USING BTREE,
  KEY `is_base` (`is_show`) USING BTREE,
  KEY `sort` (`sort`) USING BTREE,
  KEY `add_time` (`add_time`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=41 DEFAULT CHARSET=utf8 COMMENT='Bảng phân loại sản phẩm';

