--
-- cấu trúc bảng `eb_store_combination`
--

CREATE TABLE IF NOT EXISTS `eb_store_combination` (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'tự tăngID',
  `product_id` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'hàng hóaid',
  `mer_id` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Thương giaid',
  `image` varchar(255) NOT NULL DEFAULT '' COMMENT 'Hình ảnh được đề xuất',
  `images` varchar(2000) NOT NULL DEFAULT '' COMMENT 'băng chuyền',
  `title` varchar(255) NOT NULL DEFAULT '' COMMENT 'Tiêu đề sự kiện',
  `attr` varchar(255) NOT NULL DEFAULT '' COMMENT 'Thuộc tính hoạt động',
  `people` int(2) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Số lượng người tham gia',
  `info` varchar(255) NOT NULL DEFAULT '' COMMENT 'Giới thiệu',
  `price` decimal(12,2) UNSIGNED NOT NULL DEFAULT '0.00' COMMENT 'giá',
  `sort` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'loại',
  `sales` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Doanh số bán hàng',
  `stock` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'trong kho',
  `add_time` varchar(128) NOT NULL DEFAULT '0' COMMENT 'Thêm thời gian',
  `is_host` tinyint(1) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'gợi ý',
  `is_show` tinyint(1) UNSIGNED NOT NULL DEFAULT '1' COMMENT 'Tình trạng sản phẩm',
  `is_del` tinyint(1) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Có nên xóa không',
  `combination` tinyint(1) UNSIGNED NOT NULL DEFAULT '1' COMMENT 'Chia sẻ nhóm',
  `mer_use` tinyint(1) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Người bán có sẵn sàng hay không 1 có sẵn 0 không có sẵn',
  `is_postage` tinyint(1) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Miễn phí vận chuyển 1 có 0 không',
  `postage` decimal(12,2) UNSIGNED NOT NULL DEFAULT '0.00' COMMENT 'Bưu phí',
  `start_time` int(11) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Thời gian bắt đầu của nhóm',
  `stop_time` int(11) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Thời gian kết thúc chia sẻ nhóm',
  `effective_time` int(11) NOT NULL DEFAULT '0' COMMENT 'Thời gian hợp lệ cho đơn hàng nhóm',
  `cost` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Giá thành sản phẩm câu đố',
  `browse` int(11) NOT NULL DEFAULT '0' COMMENT 'Lượt xem',
  `unit_name` varchar(32) NOT NULL DEFAULT '' COMMENT 'Tên đơn vị',
  `temp_id` int(11) NOT NULL DEFAULT '0' COMMENT 'Mẫu vận chuyển hàng hóaID',
  `weight` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT 'cân nặng',
  `volume` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT 'âm lượng',
  `num` int(11) NOT NULL DEFAULT '0' COMMENT 'Số lượng mua một lần',
  `once_num` int(11) NOT NULL DEFAULT '0' COMMENT 'Số lượng có sẵn cho mỗi đơn hàng',
  `quota` int(10) NOT NULL DEFAULT '0' COMMENT 'Tổng giới hạn mua hàng',
  `quota_show` int(10) NOT NULL DEFAULT '0' COMMENT 'Tổng số hiển thị hạn chế',
  `virtual` int(11) NOT NULL DEFAULT '100' COMMENT 'Tỷ lệ nhóm ảo',
  `logistics` varchar(11) NOT NULL DEFAULT '1,2' COMMENT 'Phương pháp hậu cần',
  `freight` tinyint(1) NOT NULL DEFAULT '2' COMMENT 'Cài đặt phí vận chuyển',
  `custom_form` varchar(2000) NOT NULL DEFAULT '' COMMENT 'Biểu mẫu tùy chỉnh',
  `virtual_type` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Loại sản phẩm',
  `is_commission` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Có giảm giá hoa hồng khi đặt phòng theo nhóm không?',
  `head_commission` int(11) NOT NULL DEFAULT '0' COMMENT 'Tỷ lệ hoa hồng trưởng nhóm',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='Danh sách sản phẩm nhóm';

