--
-- cấu trúc bảng `eb_store_coupon_issue`
--

CREATE TABLE IF NOT EXISTS `eb_store_coupon_issue` (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'tự tăngID',
  `cid` int(10) NOT NULL DEFAULT '0' COMMENT 'Phiếu giảm giáID',
  `coupon_title` varchar(255) NOT NULL DEFAULT '' COMMENT 'Tên phiếu giảm giá',
  `start_time` int(10) NOT NULL DEFAULT '0' COMMENT 'Thời gian mở cửa thu phiếu giảm giá',
  `end_time` int(10) NOT NULL DEFAULT '0' COMMENT 'Thời gian kết thúc thu thập phiếu giảm giá',
  `total_count` int(10) NOT NULL DEFAULT '0' COMMENT 'Số lượng phiếu giảm giá nhận được',
  `remain_count` int(10) NOT NULL DEFAULT '0' COMMENT 'Số lượng phiếu giảm giá còn lại để nhận',
  `receive_limit` int(10) NOT NULL DEFAULT '0' COMMENT 'Số lượng phiếu giảm giá mà mỗi người nhận được',
  `is_permanent` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Số lượng tờ có bị giới hạn hay không',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '1 Bình thường 0 Không kích hoạt -1 Không hợp lệ',
  `is_give_subscribe` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Đây có phải là lần đầu tiên để ý đến món quà? 0-Không(mặc định) 1-Đúng',
  `is_full_give` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Có nên tặng quà đầy đủ 0-không(mặc định) 1-Đúng',
  `full_reduction` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT 'Nhận phiếu giảm giá khi bạn chi tiêu bất kỳ số tiền nào',
  `is_del` tinyint(1) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Có nên xóa không',
  `add_time` int(10) NOT NULL DEFAULT '0' COMMENT 'Thời gian thêm phiếu giảm giá',
  `title` varchar(64) NOT NULL DEFAULT '' COMMENT 'Tên phiếu giảm giá',
  `integral` int(11) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Đổi điểm đã tiêu thụ',
  `coupon_price` decimal(12,2) UNSIGNED NOT NULL DEFAULT '0.00' COMMENT 'Mệnh giá của phiếu giảm giá được sử dụng',
  `use_min_price` decimal(12,2) UNSIGNED NOT NULL DEFAULT '0.00' COMMENT 'Số tiền chi tiêu tối thiểu để sử dụng phiếu giảm giá',
  `coupon_time` int(11) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Thời hạn hiệu lực của phiếu (đơn vị: ngày）',
  `product_id` varchar(2000) NOT NULL DEFAULT '' COMMENT 'Sản phẩmid',
  `category_id` varchar(2000) NOT NULL DEFAULT '' COMMENT 'Phân loạiid',
  `type` tinyint(2) NOT NULL DEFAULT '0' COMMENT 'Loại phiếu giảm giá 0-chung phiếu giảm giá 1 danh mục phiếu giảm giá 2 hàng hóa',
  `receive_type` tinyint(1) NOT NULL DEFAULT '0' COMMENT '1 Thu thập thủ công, 2 phiếu người mới, 3 phiếu quà tặng, 4 phiếu thành viên',
  `start_use_time` int(11) NOT NULL DEFAULT '0' COMMENT 'Thời gian bắt đầu sử dụng phiếu giảm giá',
  `end_use_time` int(11) NOT NULL DEFAULT '0' COMMENT 'Thời gian kết thúc sử dụng phiếu giảm giá',
  `sort` int(11) NOT NULL DEFAULT '0' COMMENT 'loại',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `cid` (`cid`) USING BTREE,
  KEY `start_time` (`start_time`,`end_time`) USING BTREE,
  KEY `remain_count` (`remain_count`) USING BTREE,
  KEY `status` (`status`) USING BTREE,
  KEY `coupon_time` (`coupon_time`) USING BTREE,
  KEY `is_del` (`is_del`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8 COMMENT='Phiếu thu phiếu tại quầy lễ tân' ROW_FORMAT=COMPACT;

