--
-- cấu trúc bảng `eb_store_integral`
--

CREATE TABLE IF NOT EXISTS `eb_store_integral` (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'Sản phẩm tích điểmID',
  `image` varchar(256) NOT NULL DEFAULT '' COMMENT 'Hình ảnh sản phẩm',
  `product_id` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'hàng hóaid',
  `images` varchar(2000) NOT NULL DEFAULT '' COMMENT 'băng chuyền',
  `title` varchar(255) NOT NULL DEFAULT '' COMMENT 'Tiêu đề sự kiện',
  `price` int(10) NOT NULL DEFAULT '0' COMMENT 'Đổi điểm',
  `sort` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'loại',
  `sales` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Doanh số bán hàng',
  `unit_name` varchar(16) NOT NULL DEFAULT '' COMMENT 'Tên đơn vị',
  `stock` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'trong kho',
  `add_time` varchar(128) NOT NULL DEFAULT '0' COMMENT 'Thêm thời gian',
  `is_host` tinyint(1) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'gợi ý',
  `is_show` tinyint(1) UNSIGNED NOT NULL DEFAULT '1' COMMENT 'Tình trạng sản phẩm',
  `is_del` tinyint(1) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'xóa bỏ',
  `num` int(11) NOT NULL DEFAULT '0' COMMENT 'Nhiều nhất bao nhiêu điểm',
  `quota` int(10) NOT NULL DEFAULT '0' COMMENT 'Tổng giới hạn mua hàng',
  `once_num` int(11) NOT NULL DEFAULT '0' COMMENT 'Số lượng mua một lần',
  `quota_show` int(11) NOT NULL DEFAULT '0' COMMENT 'Hiển thị giới hạn mua hàng',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8 COMMENT='Bảng sản phẩm điểm';

-- --------------------------------------------------------

--
-- cấu trúc bảng `eb_store_integral_order`
--

CREATE TABLE IF NOT EXISTS `eb_store_integral_order` (
  `id` int(11) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'Đặt hàngID',
  `order_id` varchar(32) NOT NULL DEFAULT '0' COMMENT 'Số đơn hàng',
  `uid` int(11) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'người dùngid',
  `real_name` varchar(32) NOT NULL DEFAULT '' COMMENT 'Tên người dùng',
  `user_phone` varchar(18) NOT NULL DEFAULT '' COMMENT 'Số điện thoại của người dùng',
  `user_address` varchar(100) NOT NULL DEFAULT '' COMMENT 'Địa chỉ chi tiết',
  `product_id` int(11) NOT NULL DEFAULT '0' COMMENT 'hàng hóaid',
  `image` varchar(256) NOT NULL DEFAULT '' COMMENT 'Hình ảnh sản phẩm',
  `store_name` varchar(128) NOT NULL DEFAULT '' COMMENT 'Tên sản phẩm',
  `suk` varchar(128) NOT NULL DEFAULT '' COMMENT 'Đặc điểm kỹ thuật',
  `total_num` int(11) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Tổng số mặt hàng đã đặt hàng',
  `price` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT 'đơn giá',
  `total_price` decimal(12,2) UNSIGNED NOT NULL DEFAULT '0.00' COMMENT 'tổng điểm',
  `add_time` int(11) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'thời gian sáng tạo',
  `status` tinyint(1) NOT NULL DEFAULT '0' COMMENT '1：Đang chờ vận chuyển; 2: Đang chờ nhận; 3: Đã hoàn thành；',
  `delivery_name` varchar(64) NOT NULL DEFAULT '' COMMENT 'Tên người chuyển phát nhanh/tên người giao hàng',
  `delivery_code` varchar(50) NOT NULL DEFAULT '' COMMENT 'Mã công ty chuyển phát nhanh',
  `delivery_type` varchar(32) NOT NULL DEFAULT '' COMMENT 'Loại vận chuyển',
  `delivery_id` varchar(64) NOT NULL DEFAULT '' COMMENT 'Số đơn đặt hàng nhanh/số điện thoại di động',
  `fictitious_content` varchar(500) NOT NULL DEFAULT '' COMMENT 'Nội dung phân phối ảo',
  `delivery_uid` int(11) NOT NULL DEFAULT '0' COMMENT 'người giao hàngid',
  `mark` varchar(512) NOT NULL DEFAULT '' COMMENT 'Nhận xét',
  `is_del` tinyint(1) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Có nên xóa không',
  `remark` varchar(512) NOT NULL DEFAULT '' COMMENT 'Ghi chú của quản trị viên',
  `mer_id` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Thương giaID',
  `is_mer_check` tinyint(3) UNSIGNED NOT NULL DEFAULT '0',
  `is_remind` tinyint(1) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Lời nhắc tin nhắn',
  `is_system_del` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Có nên xóa nền không',
  `channel_type` varchar(255) NOT NULL DEFAULT '' COMMENT 'ID thiết bị đầu cuối truy cập của người dùng',
  `province` varchar(255) NOT NULL DEFAULT '' COMMENT 'Tỉnh người dùng',
  `express_dump` varchar(502) NOT NULL DEFAULT '' COMMENT 'Thông tin in phiếu đặt hàng',
  `verify_code` varchar(125) NOT NULL DEFAULT '' COMMENT 'Mã xóa sổ',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `order_id_2` (`order_id`,`uid`) USING BTREE,
  KEY `uid` (`uid`) USING BTREE,
  KEY `add_time` (`add_time`) USING BTREE,
  KEY `status` (`status`) USING BTREE,
  KEY `is_del` (`is_del`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='Mẫu đơn đặt hàng điểm';

