--
-- cấu trúc bảng `eb_store_order`
--

CREATE TABLE IF NOT EXISTS `eb_store_order` (
  `id` int(11) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'Đặt hàngID',
  `pid` int(10) NOT NULL DEFAULT '0' COMMENT 'Lệnh của phụ huynhid',
  `order_id` varchar(32) NOT NULL DEFAULT '0' COMMENT 'Số đơn hàng',
  `trade_no` varchar(100) NOT NULL DEFAULT '' COMMENT 'Số lệnh thanh toán',
  `uid` int(11) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'người dùngid',
  `real_name` varchar(32) NOT NULL DEFAULT '' COMMENT 'Tên người dùng',
  `user_phone` varchar(18) NOT NULL DEFAULT '' COMMENT 'Số điện thoại của người dùng',
  `user_address` varchar(100) NOT NULL DEFAULT '' COMMENT 'Địa chỉ chi tiết',
  `cart_id` text COMMENT 'giỏ hàngid',
  `freight_price` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT 'số tiền vận chuyển',
  `total_num` int(11) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Tổng số mặt hàng đã đặt hàng',
  `total_price` decimal(12,2) UNSIGNED NOT NULL DEFAULT '0.00' COMMENT 'Tổng giá đặt hàng',
  `total_postage` decimal(12,2) UNSIGNED NOT NULL DEFAULT '0.00' COMMENT 'Bưu phí',
  `pay_price` decimal(12,2) UNSIGNED NOT NULL DEFAULT '0.00' COMMENT 'số tiền thanh toán thực tế',
  `pay_postage` decimal(12,2) UNSIGNED NOT NULL DEFAULT '0.00' COMMENT 'Trả bưu phí',
  `deduction_price` decimal(12,2) UNSIGNED NOT NULL DEFAULT '0.00' COMMENT 'Số tiền khấu trừ',
  `coupon_id` int(11) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Phiếu giảm giáid',
  `coupon_price` decimal(12,2) UNSIGNED NOT NULL DEFAULT '0.00' COMMENT 'Số tiền phiếu giảm giá',
  `paid` tinyint(1) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Trạng thái thanh toán',
  `pay_time` int(11) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'thời gian thanh toán',
  `pay_type` varchar(32) NOT NULL DEFAULT '' COMMENT 'Phương thức thanh toán',
  `add_time` int(11) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'thời gian sáng tạo',
  `status` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Trạng thái đơn hàng（-1 : Yêu cầu hoàn lại tiền -2 : Trả hàng thành công 0: Đang chờ giao hàng; 1: Đang chờ nhận; 2: Đã nhận; 3: Đang chờ đánh giá; -1: Đã hoàn tiền）',
  `is_stock_up` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Nó có trong kho không?',
  `refund_status` tinyint(1) UNSIGNED NOT NULL DEFAULT '0' COMMENT '0 Không hoàn tiền 1 Đăng ký 2 Hoàn tiền',
  `refund_type` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Loại yêu cầu hoàn tiền',
  `refund_express` varchar(255) NOT NULL DEFAULT '' COMMENT 'Trả lại số theo dõi nhanh',
  `refund_express_name` varchar(255) NOT NULL DEFAULT '' COMMENT 'Trả lại tên chuyển phát nhanh',
  `refund_reason_wap_img` varchar(2000) NOT NULL DEFAULT '' COMMENT 'Hình ảnh hoàn tiền',
  `refund_reason_wap_explain` varchar(255) NOT NULL DEFAULT '' COMMENT 'Hướng dẫn sử dụng hoàn tiền',
  `refund_reason_time` int(11) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Thời gian hoàn tiền',
  `refund_reason_wap` varchar(255) NOT NULL DEFAULT '' COMMENT 'Lý do hoàn tiền tại quầy lễ tân',
  `refund_reason` varchar(255) NOT NULL DEFAULT '' COMMENT 'Lý do không hoàn tiền',
  `refund_price` decimal(12,2) UNSIGNED NOT NULL DEFAULT '0.00' COMMENT 'Số tiền hoàn lại',
  `delivery_name` varchar(64) NOT NULL DEFAULT '' COMMENT 'Tên người chuyển phát nhanh/tên người giao hàng',
  `delivery_code` varchar(50) NOT NULL DEFAULT '' COMMENT 'Mã công ty chuyển phát nhanh',
  `delivery_type` varchar(32) NOT NULL DEFAULT '' COMMENT 'Loại vận chuyển',
  `delivery_id` varchar(64) NOT NULL DEFAULT '' COMMENT 'Số đơn đặt hàng nhanh/số điện thoại di động',
  `kuaidi_label` varchar(255) NOT NULL DEFAULT '' COMMENT 'Hình ảnh số theo dõi nhanh',
  `kuaidi_task_id` varchar(64) NOT NULL DEFAULT '' COMMENT 'Nhiệm vụ chuyển phát nhanhid',
  `kuaidi_order_id` varchar(64) NOT NULL DEFAULT '' COMMENT 'Số đơn hàng nhanh',
  `fictitious_content` varchar(500) NOT NULL DEFAULT '' COMMENT 'Nội dung phân phối ảo',
  `delivery_uid` int(11) NOT NULL DEFAULT '0' COMMENT 'người giao hàngid',
  `gain_integral` decimal(12,2) UNSIGNED NOT NULL DEFAULT '0.00' COMMENT 'Chi tiêu và kiếm điểm',
  `use_integral` decimal(12,2) UNSIGNED NOT NULL DEFAULT '0.00' COMMENT 'Sử dụng điểm',
  `back_integral` decimal(12,2) UNSIGNED NOT NULL DEFAULT '0.00' COMMENT 'Có bao nhiêu điểm đã được hoàn trả cho người dùng?',
  `spread_uid` int(10) NOT NULL DEFAULT '0' COMMENT 'người quảng báuid',
  `spread_two_uid` int(10) NOT NULL DEFAULT '0' COMMENT 'Nhà quảng bá vượt trộiuid',
  `one_brokerage` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT 'Số tiền hoàn trả cấp 1',
  `two_brokerage` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT 'Số tiền hoàn trả cấp 2',
  `mark` varchar(512) NOT NULL DEFAULT '' COMMENT 'Nhận xét',
  `is_del` tinyint(1) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Có nên xóa không',
  `is_cancel` tinyint(1) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Hủy hay không',
  `unique` char(32) NOT NULL DEFAULT '' COMMENT 'chỉ mộtid(md5mã hóa)tương tựid',
  `remark` varchar(512) NOT NULL DEFAULT '' COMMENT 'Ghi chú của quản trị viên',
  `mer_id` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Thương giaID',
  `is_mer_check` tinyint(3) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Tải lên người bán',
  `combination_id` int(11) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Nhóm sản phẩm id0 sản phẩm chung',
  `pink_id` int(11) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Id nhóm nhóm 0 không có nhóm nhóm',
  `cost` decimal(12,2) UNSIGNED NOT NULL DEFAULT '0.00' COMMENT 'giá thành',
  `seckill_id` int(11) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'mặt hàng flash saleID',
  `bargain_id` int(11) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Mặc cảid',
  `advance_id` int(10) NOT NULL DEFAULT '0' COMMENT 'Các mặt hàng bán trướcid',
  `verify_code` varchar(12) NOT NULL DEFAULT '' COMMENT 'Mã xóa sổ',
  `store_id` int(11) NOT NULL DEFAULT '0' COMMENT 'cửa hàngid',
  `shipping_type` tinyint(1) NOT NULL DEFAULT '1' COMMENT 'Phương thức giao hàng 1=chuyển phát nhanh ，2=Nhận tại cửa hàng',
  `clerk_id` int(11) NOT NULL DEFAULT '0' COMMENT 'nhân viên văn phòngid',
  `is_channel` tinyint(1) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'kênh thanh toán(0Tài khoản công khai WeChat 1 ứng dụng WeChat)',
  `is_remind` tinyint(1) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Lời nhắc tin nhắn',
  `is_system_del` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Có nên xóa nền không',
  `channel_type` varchar(255) NOT NULL DEFAULT '' COMMENT 'ID thiết bị đầu cuối truy cập của người dùng',
  `province` varchar(255) NOT NULL DEFAULT '' COMMENT 'Tỉnh người dùng',
  `express_dump` varchar(502) NOT NULL DEFAULT '' COMMENT 'Thông tin in phiếu đặt hàng',
  `virtual_type` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Loại hàng hóa ảo',
  `virtual_info` varchar(255) NOT NULL DEFAULT '' COMMENT 'Thông tin sản phẩm ảo',
  `pay_uid` int(11) NOT NULL DEFAULT '0' COMMENT 'người dùng trả tiềnuid',
  `custom_form` text COMMENT 'Biểu mẫu tùy chỉnh',
  `staff_id` int(11) NOT NULL DEFAULT '0' COMMENT 'nhân viênid',
  `agent_id` int(11) NOT NULL DEFAULT '0' COMMENT 'diễn xuấtid',
  `division_id` int(11) NOT NULL DEFAULT '0' COMMENT 'Đơn vị kinh doanhid',
  `staff_brokerage` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT 'Giảm giá nhân viên',
  `agent_brokerage` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT 'Giảm giá hoa hồng đại lý',
  `division_brokerage` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT 'Chiết khấu hoa hồng đơn vị kinh doanh',
  `is_gift` int(1) NOT NULL DEFAULT '0' COMMENT 'Đây có phải là một đơn đặt hàng quà tặng?',
  `gift_price` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT 'phụ phí quà tặng',
  `gift_uid` int(11) NOT NULL DEFAULT '0' COMMENT 'Người dùng nhận quàuid',
  `gift_mark` varchar(255) NOT NULL DEFAULT '' COMMENT 'tin nhắn quà tặng',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `order_id_2` (`order_id`,`uid`) USING BTREE,
  UNIQUE KEY `unique` (`unique`) USING BTREE,
  KEY `uid` (`uid`) USING BTREE,
  KEY `add_time` (`add_time`) USING BTREE,
  KEY `pay_price` (`pay_price`) USING BTREE,
  KEY `paid` (`paid`) USING BTREE,
  KEY `pay_time` (`pay_time`) USING BTREE,
  KEY `pay_type` (`pay_type`) USING BTREE,
  KEY `status` (`status`) USING BTREE,
  KEY `is_del` (`is_del`) USING BTREE,
  KEY `coupon_id` (`coupon_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='mẫu đơn đặt hàng';

-- --------------------------------------------------------

--
-- cấu trúc bảng `eb_store_order_cart_info`
--

CREATE TABLE IF NOT EXISTS `eb_store_order_cart_info` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT 'tự tăngID',
  `oid` int(11) NOT NULL DEFAULT '0' COMMENT 'Đặt hàngid',
  `uid` int(11) NOT NULL DEFAULT '0' COMMENT 'người dùnguid',
  `cart_id` varchar(50) NOT NULL DEFAULT '0' COMMENT 'giỏ hàngid',
  `product_id` int(10) NOT NULL DEFAULT '0' COMMENT 'hàng hóaID',
  `old_cart_id` varchar(50) NOT NULL DEFAULT '' COMMENT 'Trước khi chia đơn hàngcart_id',
  `cart_num` int(10) NOT NULL DEFAULT '0' COMMENT 'Số lượng',
  `refund_num` int(11) NOT NULL DEFAULT '0' COMMENT 'Số lần hoàn tiền',
  `surplus_num` int(10) NOT NULL DEFAULT '0' COMMENT 'Số lượng còn lại sau khi tách',
  `split_status` int(1) NOT NULL DEFAULT '0' COMMENT '0:không chia1:Cũng có thể chia 2: Chia xong',
  `cart_info` text COMMENT 'Chi tiết về những gì cần mua',
  `unique` char(32) NOT NULL DEFAULT '' COMMENT 'chỉ mộtid',
  PRIMARY KEY (`id`),
  UNIQUE KEY `oid` (`oid`,`unique`) USING BTREE,
  KEY `cart_id` (`cart_id`) USING BTREE,
  KEY `product_id` (`product_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='Mẫu chi tiết mua sắm đặt hàng';

-- --------------------------------------------------------

--
-- cấu trúc bảng `eb_store_order_economize`
--

CREATE TABLE IF NOT EXISTS `eb_store_order_economize` (
  `id` int(11) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'Đặt hàngID',
  `order_id` varchar(32) NOT NULL DEFAULT '' COMMENT 'Số đơn hàng',
  `uid` int(11) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'người dùngid',
  `order_type` tinyint(1) UNSIGNED ZEROFILL NOT NULL DEFAULT '1' COMMENT 'Phương thức giao hàng 1=Đặt hàng sản phẩm ，2=Đặt hàng ngoại tuyến',
  `pay_price` decimal(12,2) UNSIGNED NOT NULL DEFAULT '0.00' COMMENT 'số tiền thanh toán thực tế',
  `postage_price` decimal(12,2) UNSIGNED NOT NULL DEFAULT '0.00' COMMENT 'Số tiền giảm giá bưu chính',
  `member_price` decimal(12,2) UNSIGNED NOT NULL DEFAULT '0.00' COMMENT 'Số tiền giảm giá thành viên',
  `offline_price` decimal(12,2) UNSIGNED NOT NULL DEFAULT '0.00' COMMENT 'Số tiền chiết khấu ngoại tuyến',
  `coupon_price` decimal(12,2) UNSIGNED NOT NULL DEFAULT '0.00' COMMENT 'Số tiền chiết khấu phiếu giảm giá',
  `add_time` int(11) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'thời gian sáng tạo',
  `status` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'tình trạng',
  PRIMARY KEY (`id`,`order_id`,`uid`) USING BTREE,
  UNIQUE KEY `order_id_2` (`order_id`,`uid`) USING BTREE,
  KEY `uid` (`uid`) USING BTREE,
  KEY `add_time` (`add_time`) USING BTREE,
  KEY `pay_price` (`pay_price`) USING BTREE,
  KEY `status` (`status`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='Bảng tiết kiệm quỹ của người dùng';

-- --------------------------------------------------------

--
-- cấu trúc bảng `eb_store_order_invoice`
--

CREATE TABLE IF NOT EXISTS `eb_store_order_invoice` (
  `id` int(10) NOT NULL AUTO_INCREMENT COMMENT 'tự tăngID',
  `uid` int(10) NOT NULL DEFAULT '0' COMMENT 'người dùnguid',
  `category` varchar(10) NOT NULL DEFAULT 'order' COMMENT 'Phân loại hóa đơn order:Đặt hàng',
  `order_id` int(10) NOT NULL DEFAULT '0' COMMENT 'Đặt hàngid',
  `invoice_id` int(10) NOT NULL DEFAULT '0' COMMENT 'hóa đơnid',
  `header_type` tinyint(1) NOT NULL DEFAULT '1' COMMENT 'loại tiêu đề',
  `type` tinyint(1) NOT NULL DEFAULT '1' COMMENT 'Loại hóa đơn',
  `name` varchar(100) NOT NULL DEFAULT '' COMMENT 'Tên (tiêu đề hóa đơn）',
  `duty_number` varchar(50) NOT NULL DEFAULT '' COMMENT 'Mã số thuế',
  `drawer_phone` varchar(30) NOT NULL DEFAULT '' COMMENT 'Số điện thoại di động của Biller',
  `email` varchar(100) NOT NULL DEFAULT '' COMMENT 'Địa chỉ email của người lập hoá đơn',
  `tell` varchar(30) NOT NULL DEFAULT '' COMMENT 'Đăng ký số điện thoại',
  `address` varchar(255) NOT NULL DEFAULT '' COMMENT 'Địa chỉ đã đăng ký',
  `bank` varchar(50) NOT NULL DEFAULT '' COMMENT 'Ngân hàng mở tài khoản',
  `card_number` varchar(50) NOT NULL DEFAULT '' COMMENT 'Số thẻ ngân hàng',
  `is_pay` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Có nên trả tiền không',
  `is_refund` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Đơn đặt hàng có được hoàn lại không?',
  `is_invoice` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Có nên xuất hóa đơn không',
  `invoice_number` varchar(50) NOT NULL DEFAULT '' COMMENT 'Số phiếu thanh toán',
  `remark` varchar(255) NOT NULL DEFAULT '' COMMENT 'Nhận xét',
  `invoice_time` int(10) NOT NULL DEFAULT '0' COMMENT 'Thời điểm lập hóa đơn',
  `add_time` int(10) NOT NULL DEFAULT '0' COMMENT 'Thêm thời gian',
  `unique_num` varchar(255) NOT NULL DEFAULT '' COMMENT 'giá trị duy nhất',
  `invoice_num` varchar(255) NOT NULL DEFAULT '' COMMENT 'Số hóa đơn',
  `invoice_type` varchar(255) NOT NULL DEFAULT '' COMMENT 'Loại hóa đơn',
  `invoice_serial_number` varchar(255) NOT NULL DEFAULT '' COMMENT 'Số seri hóa đơn',
  `red_invoice_num` varchar(255) NOT NULL DEFAULT '' COMMENT 'Hóa đơn mã chữ đỏ',
  `is_del` tinyint(1) DEFAULT '0' COMMENT 'Có nên xóa không',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='Mẫu hóa đơn đặt hàng';

-- --------------------------------------------------------

--
-- cấu trúc bảng `eb_store_order_refund`
--

CREATE TABLE IF NOT EXISTS `eb_store_order_refund` (
  `id` int(10) NOT NULL AUTO_INCREMENT COMMENT 'tự tăngID',
  `store_order_id` int(10) NOT NULL DEFAULT '0' COMMENT 'mẫu đơn đặt hàngID',
  `store_id` int(10) NOT NULL DEFAULT '0' COMMENT 'cửa hàngID',
  `order_id` varchar(50) NOT NULL DEFAULT '' COMMENT 'Số đơn hàng',
  `uid` int(10) NOT NULL DEFAULT '0' COMMENT 'người dùngUID',
  `refund_type` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Loại yêu cầu hoàn tiền',
  `refund_num` int(5) NOT NULL DEFAULT '0' COMMENT 'Số lần hoàn tiền',
  `refund_price` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT 'Số tiền hoàn lại',
  `refunded_price` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT 'Số tiền được hoàn lại',
  `refund_phone` varchar(32) NOT NULL DEFAULT '' COMMENT 'Số điện thoại hoàn tiền',
  `refund_express` varchar(100) NOT NULL DEFAULT '' COMMENT 'Trả lại số theo dõi nhanh',
  `refund_express_name` varchar(255) NOT NULL DEFAULT '' COMMENT 'Trả lại tên chuyển phát nhanh',
  `refund_explain` varchar(255) NOT NULL DEFAULT '' COMMENT 'Hướng dẫn sử dụng hoàn tiền',
  `refund_img` text COMMENT 'Hình ảnh hoàn tiền',
  `refund_reason` varchar(255) NOT NULL DEFAULT '' COMMENT 'Lý do không hoàn tiền',
  `refuse_reason` varchar(255) NOT NULL DEFAULT '' COMMENT 'Lý do từ chối',
  `remark` varchar(255) NOT NULL DEFAULT '' COMMENT 'Nhận xét',
  `refunded_time` int(10) NOT NULL DEFAULT '0' COMMENT 'thời gian xử lý',
  `cart_info` longtext COMMENT 'Thông tin sản phẩm hoàn tiền',
  `is_cancel` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Liệu người dùng có hủy hay không',
  `is_pink_cancel` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Việc đặt phòng theo nhóm có bị tự động hủy hay không',
  `is_del` tinyint(1) DEFAULT '0' COMMENT 'Hủy đơn đăng ký',
  `add_time` int(10) NOT NULL DEFAULT '0' COMMENT 'Thời gian nộp đơn xin hoàn tiền',
  `is_system_del` tinyint(1) DEFAULT '0' COMMENT 'Xóa hệ thống',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='Mẫu đơn đặt hàng hoàn lại tiền';

-- --------------------------------------------------------

--
-- cấu trúc bảng `eb_store_order_status`
--

CREATE TABLE IF NOT EXISTS `eb_store_order_status` (
  `oid` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Đặt hàngid',
  `change_type` varchar(32) NOT NULL DEFAULT '' COMMENT 'Loại hoạt động',
  `change_message` varchar(256) NOT NULL DEFAULT '' COMMENT 'Ghi chú hoạt động',
  `change_time` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Thời gian hoạt động',
  KEY `oid` (`oid`) USING BTREE,
  KEY `change_type` (`change_type`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='Mẫu hồ sơ hoạt động đặt hàng';

-- --------------------------------------------------------

--
-- cấu trúc bảng `eb_store_pink`
--

CREATE TABLE IF NOT EXISTS `eb_store_pink` (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'tự tăngID',
  `uid` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'người dùngid',
  `nickname` varchar(64) NOT NULL DEFAULT '' COMMENT 'Biệt hiệu của người dùng',
  `avatar` varchar(256) NOT NULL DEFAULT '' COMMENT 'Hình đại diện của người dùng',
  `order_id` varchar(32) NOT NULL DEFAULT '' COMMENT 'Tạo id đơn hàng',
  `order_id_key` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Cơ sở dữ liệu id đơn hàng',
  `total_num` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Số lượng mặt hàng đã mua',
  `total_price` decimal(12,2) UNSIGNED NOT NULL DEFAULT '0.00' COMMENT 'tổng số tiền mua',
  `cid` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Nhóm sản phẩmid',
  `pid` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'hàng hóaid',
  `people` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Tổng số câu đố',
  `price` decimal(12,2) UNSIGNED NOT NULL DEFAULT '0.00' COMMENT 'Đơn giá nhóm sản phẩm',
  `add_time` varchar(24) NOT NULL DEFAULT '0' COMMENT 'thời gian bắt đầu',
  `stop_time` varchar(24) NOT NULL DEFAULT '0' COMMENT 'thời gian kết thúc',
  `k_id` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Id lãnh đạo 0 là lãnh đạo',
  `is_tpl` tinyint(1) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Có gửi tin nhắn mẫu hay không 0 chưa gửi 1 đã gửi',
  `is_refund` tinyint(1) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Có hoàn tiền hay không 0 Không hoàn tiền 1 Đã hoàn tiền',
  `status` tinyint(1) UNSIGNED NOT NULL DEFAULT '1' COMMENT 'Trạng thái 1 Đang tiến hành 2 Đã hoàn thành 3 Chưa hoàn thành',
  `is_virtual` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Có nên tham gia một nhóm ảo không',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='Bảng chia sẻ nhóm';

