--
-- cấu trúc bảng `eb_store_product`
--

CREATE TABLE IF NOT EXISTS `eb_store_product` (
  `id` mediumint(11) NOT NULL AUTO_INCREMENT COMMENT 'hàng hóaid',
  `mer_id` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Thương giaId(0Được tạo cho quản trị viên phụ trợ chung,Khi nó khác 0, nó được tạo bởi chương trình phụ trợ của người bán.)',
  `image` varchar(256) NOT NULL DEFAULT '' COMMENT 'Hình ảnh sản phẩm',
  `recommend_image` varchar(256) NOT NULL DEFAULT '' COMMENT 'Hình ảnh được đề xuất',
  `slider_image` varchar(2000) NOT NULL DEFAULT '' COMMENT 'băng chuyền',
  `store_name` varchar(128) NOT NULL DEFAULT '' COMMENT 'Tên sản phẩm',
  `store_info` varchar(256) NOT NULL DEFAULT '' COMMENT 'Giới thiệu sản phẩm',
  `keyword` varchar(256) NOT NULL DEFAULT '' COMMENT 'Từ khóa',
  `bar_code` varchar(15) NOT NULL DEFAULT '' COMMENT 'Mã vạch sản phẩm (mã một chiều）',
  `cate_id` varchar(64) NOT NULL DEFAULT '' COMMENT 'Phân loạiid',
  `price` decimal(12,2) UNSIGNED NOT NULL DEFAULT '0.00' COMMENT 'Giá sản phẩm',
  `vip_price` decimal(12,2) UNSIGNED NOT NULL DEFAULT '0.00' COMMENT 'Giá thành viên',
  `ot_price` decimal(12,2) UNSIGNED NOT NULL DEFAULT '0.00' COMMENT 'giá thị trường',
  `postage` decimal(12,2) UNSIGNED NOT NULL DEFAULT '0.00' COMMENT 'Bưu phí',
  `unit_name` varchar(32) NOT NULL DEFAULT '' COMMENT 'Tên đơn vị',
  `sort` smallint(11) NOT NULL DEFAULT '0' COMMENT 'loại',
  `sales` mediumint(11) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Doanh số bán hàng',
  `stock` mediumint(11) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'trong kho',
  `is_show` tinyint(1) NOT NULL DEFAULT '1' COMMENT 'Trạng thái (0: Không có trên kệ, 1: Trên kệ）',
  `is_hot` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Nó có phải là sản phẩm bán chạy không?',
  `is_benefit` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Đây có phải là giảm giá không?',
  `is_best` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Nó có chất lượng cao không?',
  `is_new` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Nó có mới không?',
  `is_virtual` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Sản phẩm có phải là sản phẩm ảo không',
  `virtual_type` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Loại hàng hóa ảo',
  `add_time` int(11) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Thêm thời gian',
  `is_postage` tinyint(1) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Có miễn phí vận chuyển không?',
  `is_del` tinyint(1) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Có nên xóa không',
  `mer_use` tinyint(1) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Người bán có phải là đại lý không 0 không thể là đại lý 1 có thể là đại lý',
  `give_integral` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'nhận được điểm',
  `cost` decimal(12,2) UNSIGNED NOT NULL DEFAULT '0.00' COMMENT 'giá thành',
  `is_seckill` tinyint(1) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Trạng thái flash sale 0 chưa bật 1 đã bật',
  `is_bargain` tinyint(1) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Trạng thái mặc cả: 0 chưa bật 1 đã bật',
  `is_good` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Đây có phải là một đề xuất sản phẩm chất lượng cao?',
  `is_sub` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Có nên chia hoa hồng riêng không',
  `is_vip` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Có bật tính năng định giá thành viên hay không',
  `ficti` mediumint(11) NOT NULL DEFAULT '0' COMMENT 'bán hàng ảo',
  `browse` int(11) NOT NULL DEFAULT '0' COMMENT 'Lượt xem',
  `code_path` varchar(64) NOT NULL DEFAULT '' COMMENT 'Địa chỉ mã QR sản phẩm(Áp phích ứng dụng người dùng)',
  `soure_link` varchar(255) NOT NULL DEFAULT '' COMMENT 'Loại taobao Jingdong 1688',
  `video_link` varchar(500) NOT NULL DEFAULT '' COMMENT 'Liên kết video hình ảnh chính',
  `temp_id` int(11) NOT NULL DEFAULT '1' COMMENT 'Mẫu vận chuyển hàng hóaID',
  `spec_type` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Thông số kỹ thuật 0 đơn 1 thêm',
  `activity` varchar(255) NOT NULL DEFAULT '' COMMENT 'Sắp xếp hiển thị hoạt động1=bán chớp nhoáng，2=Mặc cả，3=Chia sẻ nhóm',
  `spu` char(13) NOT NULL DEFAULT '' COMMENT 'hàng hóaSPU',
  `label_id` varchar(64) NOT NULL DEFAULT '' COMMENT 'NhãnID',
  `command_word` varchar(255) NOT NULL DEFAULT '' COMMENT 'Sao chép mật khẩu',
  `recommend_list` varchar(255) NOT NULL DEFAULT '' COMMENT 'Sản phẩm được đề xuấtid',
  `vip_product` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Đây có phải là sản phẩm dành riêng cho thành viên không?',
  `vip_product_type` tinyint(1) NOT NULL DEFAULT '0' COMMENT '0Chỉ hiển thị với thành viên trả phí,1Chỉ dành cho thành viên trả phí',
  `presale` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Có nên bán trước sản phẩm hay không',
  `presale_start_time` int(11) NOT NULL DEFAULT '0' COMMENT 'Thời gian bắt đầu bán trước',
  `presale_end_time` int(11) NOT NULL DEFAULT '0' COMMENT 'Thời gian kết thúc bán hàng trước',
  `presale_day` int(11) NOT NULL DEFAULT '0' COMMENT 'Giao hàng trong vòng vài ngày sau khi đợt bán trước kết thúc',
  `logistics` varchar(10) NOT NULL DEFAULT '1,2' COMMENT 'Phương pháp hậu cần',
  `freight` tinyint(1) NOT NULL DEFAULT '2' COMMENT 'Cài đặt phí vận chuyển',
  `custom_form` varchar(2000) NOT NULL DEFAULT '' COMMENT 'Biểu mẫu tùy chỉnh',
  `is_limit` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Có bật hạn chế mua hàng hay không',
  `limit_type` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Loại hạn chế mua hàng 1 Hạn chế mua hàng một lần 2 Hạn chế mua hàng vĩnh viễn',
  `limit_num` int(11) NOT NULL DEFAULT '0' COMMENT 'Giới hạn mua hàng',
  `min_qty` int(11) NOT NULL DEFAULT '1' COMMENT 'Số lượng mua tối thiểu',
  `default_sku` varchar(255) NOT NULL DEFAULT '' COMMENT 'Thông số kỹ thuật mặc định',
  `params_list` varchar(2000) NOT NULL DEFAULT '' COMMENT 'Thông số sản phẩm',
  `label_list` varchar(255) NOT NULL DEFAULT '' COMMENT 'Thẻ sản phẩm',
  `protection_list` varchar(255) NOT NULL DEFAULT '' COMMENT 'Bảo vệ sản phẩm',
  `is_gift` int(1) NOT NULL DEFAULT '0' COMMENT 'Nó có phải là một món quà?',
  `gift_price` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT 'phụ phí quà tặng',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `cate_id` (`cate_id`) USING BTREE,
  KEY `is_hot` (`is_hot`) USING BTREE,
  KEY `is_benefit` (`is_benefit`) USING BTREE,
  KEY `is_best` (`is_best`) USING BTREE,
  KEY `is_new` (`is_new`) USING BTREE,
  KEY `toggle_on_sale, is_del` (`is_del`) USING BTREE,
  KEY `price` (`price`) USING BTREE,
  KEY `is_show` (`is_show`) USING BTREE,
  KEY `sort` (`sort`) USING BTREE,
  KEY `sales` (`sales`) USING BTREE,
  KEY `add_time` (`add_time`) USING BTREE,
  KEY `is_postage` (`is_postage`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8 COMMENT='Danh sách sản phẩm';

