  `id` int(10) NOT NULL AUTO_INCREMENT COMMENT 'tự tăngID',
  `product_id` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'hàng hóaID',
  `attr_name` varchar(32) NOT NULL DEFAULT '' COMMENT 'tên thuộc tính',
  `attr_values` longtext COMMENT 'giá trị thuộc tính',
  `type` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Loại hoạt động 0=hàng hóa，1=bán chớp nhoáng，2=Mặc cả，3=Chia sẻ nhóm',
  PRIMARY KEY (`id`),
  KEY `store_id` (`product_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=65 DEFAULT CHARSET=utf8 COMMENT='Bảng thuộc tính sản phẩm';

