  `result` longtext COMMENT 'Thông số thuộc tính sản phẩm',
  `change_time` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Lần sửa đổi cuối cùng',
  `type` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Loại hoạt động 0=hàng hóa，1=bán chớp nhoáng，2=Mặc cả，3=Chia sẻ nhóm',
  PRIMARY KEY (`id`),
  KEY `product_id` (`product_id`) USING BTREE
