--
-- cấu trúc bảng `eb_store_product_attr_value`
--

CREATE TABLE IF NOT EXISTS `eb_store_product_attr_value` (
  `id` int(10) NOT NULL AUTO_INCREMENT COMMENT 'khóa chínhid',
  `product_id` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'hàng hóaID',
  `suk` varchar(128) NOT NULL DEFAULT '' COMMENT 'Giá trị chỉ mục thuộc tính sản phẩm (attr_value|attr_value[|....])',
  `stock` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Khoảng không quảng cáo tương ứng với thuộc tính',
  `sales` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Doanh số bán hàng',
  `price` decimal(12,2) UNSIGNED NOT NULL DEFAULT '0.00' COMMENT 'Số tài sản',
  `image` varchar(128) NOT NULL DEFAULT '' COMMENT 'hình ảnh',
  `unique` char(8) NOT NULL DEFAULT '' COMMENT 'giá trị duy nhất',
  `cost` decimal(12,2) UNSIGNED NOT NULL DEFAULT '0.00' COMMENT 'giá thành',
  `bar_code` varchar(50) NOT NULL DEFAULT '' COMMENT 'Mã vạch sản phẩm',
  `bar_code_number` varchar(50) NOT NULL DEFAULT '' COMMENT 'mã vạch',
  `ot_price` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT 'giá gốc',
  `vip_price` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT 'Giá chỉ dành cho thành viên',
  `weight` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT 'cân nặng',
  `volume` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT 'âm lượng',
  `brokerage` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT 'Giảm giá cấp độ đầu tiên',
  `brokerage_two` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT 'Giảm giá cấp hai',
  `type` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Loại hoạt động 0=hàng hóa，1=bán chớp nhoáng，2=Mặc cả，3=Chia sẻ nhóm',
  `quota` int(11) NOT NULL DEFAULT '0' COMMENT 'Giới hạn mua sự kiện',
  `quota_show` int(11) NOT NULL DEFAULT '0' COMMENT 'Hiển thị giới hạn mua hoạt động',
  `is_virtual` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Nó có phải là một sản phẩm ảo?',
  `coupon_id` int(11) NOT NULL DEFAULT '0' COMMENT 'Phiếu giảm giáid',
  `disk_info` text COMMENT 'nội dung thông tin ảo',
  `is_show` int(1) NOT NULL DEFAULT '1' COMMENT 'Có hiển thị hay không',
  `is_default_select` int(1) NOT NULL DEFAULT '0' COMMENT 'Có nên sử dụng thông số kỹ thuật mặc định hay không',
  PRIMARY KEY (`id`),
  KEY `unique` (`unique`,`suk`) USING BTREE,
  KEY `store_id` (`product_id`,`suk`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=104 DEFAULT CHARSET=utf8 COMMENT='Bảng giá trị thuộc tính sản phẩm';

