--

CREATE TABLE IF NOT EXISTS `eb_store_product_label_cate` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT 'số seri',
  `name` varchar(255) NOT NULL DEFAULT '' COMMENT 'tên',
  `sort` int(11) NOT NULL DEFAULT '0' COMMENT 'loại',
  `add_time` int(11) NOT NULL DEFAULT '0' COMMENT 'Thêm thời gian',
  `is_del` int(11) NOT NULL DEFAULT '0' COMMENT 'Có nên xóa không',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='Phân loại nhãn sản phẩm';

-- --------------------------------------------------------

--
-- cấu trúc bảng `eb_store_product_log`
--

CREATE TABLE IF NOT EXISTS `eb_store_product_log` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT 'tự tăngID',
  `type` enum('visit','cart','order','pay','collect','refund') NOT NULL COMMENT 'kiểu',
  `product_id` int(11) NOT NULL DEFAULT '0' COMMENT 'hàng hóaID',
  `uid` int(11) NOT NULL DEFAULT '0' COMMENT 'người dùngID',
  `visit_num` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Có nên duyệt không',
  `cart_num` int(11) NOT NULL DEFAULT '0' COMMENT 'Thêm vào giỏ hàng số lượng',
  `order_num` int(11) NOT NULL DEFAULT '0' COMMENT 'Số lượng đặt hàng',
  `pay_num` int(11) NOT NULL DEFAULT '0' COMMENT 'số lượng thanh toán',
  `pay_price` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT 'Số tiền thanh toán',
  `cost_price` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT 'Giá thành hàng hóa',
  `pay_uid` int(11) NOT NULL DEFAULT '0' COMMENT 'người dùng trả tiềnID',
  `refund_num` int(11) NOT NULL DEFAULT '0' COMMENT 'Số tiền hoàn lại',
  `refund_price` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT 'Số tiền hoàn lại',
  `collect_num` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'sưu tầm',
  `add_time` int(11) NOT NULL DEFAULT '0' COMMENT 'Thêm thời gian',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='Thống kê sản phẩm';

-- --------------------------------------------------------

--
-- cấu trúc bảng `eb_store_product_param`
--

CREATE TABLE IF NOT EXISTS `eb_store_product_param` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT 'số seri',
  `name` varchar(255) NOT NULL DEFAULT '' COMMENT 'Tên tham số',
  `value` text COMMENT 'Nội dung tham số',
  `sort` int(11) NOT NULL DEFAULT '0' COMMENT 'loại',
  `add_time` int(11) NOT NULL DEFAULT '0' COMMENT 'Thêm thời gian',
  `is_del` int(1) NOT NULL DEFAULT '0' COMMENT 'Có nên xóa không',
  `status` int(11) NOT NULL DEFAULT '1' COMMENT 'Trạng thái tham số',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='Bảng thông số sản phẩm';

-- --------------------------------------------------------

--
-- cấu trúc bảng `eb_store_product_protection`
--

CREATE TABLE IF NOT EXISTS `eb_store_product_protection` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT 'số seri',
  `title` varchar(255) NOT NULL DEFAULT '' COMMENT 'tiêu đề',
  `content` varchar(2000) NOT NULL DEFAULT '' COMMENT 'nội dung',
  `image` varchar(255) NOT NULL DEFAULT '' COMMENT 'biểu tượng',
  `num` int(11) NOT NULL DEFAULT '0' COMMENT 'Số lượng sử dụng',
  `status` int(1) NOT NULL DEFAULT '1' COMMENT 'tình trạng',
  `sort` int(11) NOT NULL DEFAULT '0' COMMENT 'loại',
  `add_time` int(11) NOT NULL DEFAULT '0' COMMENT 'Thêm thời gian',
  `is_del` int(1) NOT NULL DEFAULT '0' COMMENT 'Có nên xóa không',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='Mẫu bảo vệ sản phẩm';

-- --------------------------------------------------------

--
-- cấu trúc bảng `eb_store_product_relation`
--

CREATE TABLE IF NOT EXISTS `eb_store_product_relation` (
  `uid` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'người dùngID',
  `product_id` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'hàng hóaID',
  `type` varchar(32) NOT NULL DEFAULT '' COMMENT 'kiểu(sưu tầm(collect）、Giống(like))',
  `category` varchar(32) NOT NULL DEFAULT '' COMMENT 'một loại sản phẩm nhất định(Sản phẩm thông thường, sản phẩm flash sale)',
  `add_time` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Thêm thời gian',
  UNIQUE KEY `uid` (`uid`,`product_id`,`type`,`category`) USING BTREE,
  KEY `type` (`type`) USING BTREE,
  KEY `category` (`category`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='Biểu mẫu thích và sưu tập sản phẩm';

-- --------------------------------------------------------

--
-- cấu trúc bảng `eb_store_product_reply`
--

CREATE TABLE IF NOT EXISTS `eb_store_product_reply` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT 'Bình luậnID',
  `uid` int(11) NOT NULL DEFAULT '0' COMMENT 'người dùngID',
  `oid` int(11) NOT NULL DEFAULT '0' COMMENT 'Đặt hàngID',
  `unique` char(32) NOT NULL DEFAULT '' COMMENT 'chỉ mộtid',
  `product_id` int(11) NOT NULL DEFAULT '0' COMMENT 'hàng hóaid',
  `reply_type` varchar(32) NOT NULL DEFAULT 'product' COMMENT 'một loại sản phẩm nhất định(Sản phẩm thông thường, sản phẩm flash sale）',
  `product_score` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Điểm sản phẩm',
  `service_score` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'điểm dịch vụ',
  `comment` varchar(512) NOT NULL DEFAULT '' COMMENT 'Nội dung bình luận',
  `pics` text COMMENT 'Bình luận về hình ảnh',
  `add_time` int(11) NOT NULL DEFAULT '0' COMMENT 'thời gian bình luận',
  `merchant_reply_content` varchar(300) NOT NULL DEFAULT '' COMMENT 'Trả lời của quản trị viên',
  `merchant_reply_time` int(11) NOT NULL DEFAULT '0' COMMENT 'Thời gian phản hồi của quản trị viên',
  `is_del` tinyint(1) UNSIGNED NOT NULL DEFAULT '0' COMMENT '0Chưa xóa 1 Đã xóa',
  `is_reply` tinyint(1) NOT NULL DEFAULT '0' COMMENT '0Không trả lời1Đã trả lời',
  `nickname` varchar(64) NOT NULL DEFAULT '' COMMENT 'Tên người dùng',
  `avatar` varchar(255) NOT NULL DEFAULT '' COMMENT 'Hình đại diện của người dùng',
  `suk` varchar(255) NOT NULL DEFAULT '' COMMENT 'Tên đặc điểm kỹ thuật',
  `status` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Trạng thái bình luận',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `order_id_2` (`oid`,`unique`) USING BTREE,
  KEY `add_time` (`add_time`) USING BTREE,
  KEY `parent_id` (`reply_type`) USING BTREE,
  KEY `is_del` (`is_del`) USING BTREE,
  KEY `product_score` (`product_score`) USING BTREE,
  KEY `service_score` (`service_score`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='Mẫu bình luận';

-- --------------------------------------------------------

--
-- cấu trúc bảng `eb_store_product_rule`
--

CREATE TABLE IF NOT EXISTS `eb_store_product_rule` (
  `id` int(10) NOT NULL AUTO_INCREMENT COMMENT 'tự tăngID',
  `rule_name` varchar(32) NOT NULL DEFAULT '' COMMENT 'Tên đặc điểm kỹ thuật',
  `rule_value` text COMMENT 'Giá trị đặc điểm kỹ thuật',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8 COMMENT='Giá trị quy tắc sản phẩm(Đặc điểm kỹ thuật)bề mặt';

