--
-- cấu trúc bảng `eb_store_product_virtual`
--

CREATE TABLE IF NOT EXISTS `eb_store_product_virtual` (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'khóa chínhid',
  `product_id` int(11) NOT NULL DEFAULT '0' COMMENT 'hàng hóaid',
  `attr_unique` varchar(20) NOT NULL DEFAULT '' COMMENT 'Thông số kỹ thuật sản phẩm tương ứng',
  `card_no` varchar(255) NOT NULL DEFAULT '' COMMENT 'Số thẻ',
  `card_pwd` varchar(255) NOT NULL DEFAULT '' COMMENT 'Mật khẩu thẻ',
  `card_unique` varchar(32) NOT NULL DEFAULT '' COMMENT 'Mật khẩu thẻ ảo có giá trị duy nhất',
  `order_id` varchar(255) NOT NULL DEFAULT '' COMMENT 'đơn đặt hàngid',
  `uid` int(11) NOT NULL DEFAULT '0' COMMENT 'người muaid',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='Mẫu mã hóa thẻ hàng ảo';

-- --------------------------------------------------------

--
-- cấu trúc bảng `eb_store_seckill`
--

CREATE TABLE IF NOT EXISTS `eb_store_seckill` (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'Danh sách sản phẩm flash saleid',
  `activity_id` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Hoạt độngid',
  `product_id` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'hàng hóaid',
  `image` varchar(255) NOT NULL DEFAULT '' COMMENT 'Hình ảnh được đề xuất',
  `images` varchar(2000) NOT NULL DEFAULT '' COMMENT 'băng chuyền',
  `title` varchar(255) NOT NULL DEFAULT '' COMMENT 'Tiêu đề sự kiện',
  `info` varchar(255) NOT NULL DEFAULT '' COMMENT 'Giới thiệu',
  `price` decimal(12,2) UNSIGNED NOT NULL DEFAULT '0.00' COMMENT 'giá',
  `cost` decimal(12,2) UNSIGNED NOT NULL DEFAULT '0.00' COMMENT 'trị giá',
  `ot_price` decimal(12,2) UNSIGNED NOT NULL DEFAULT '0.00' COMMENT 'giá gốc',
  `give_integral` decimal(12,2) UNSIGNED NOT NULL DEFAULT '0.00' COMMENT 'Sẽ được trả lại bao nhiêu điểm',
  `sort` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'loại',
  `stock` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'trong kho',
  `sales` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Doanh số bán hàng',
  `unit_name` varchar(16) NOT NULL DEFAULT '' COMMENT 'Tên đơn vị',
  `postage` decimal(12,2) UNSIGNED NOT NULL DEFAULT '0.00' COMMENT 'Bưu phí',
  `start_time` varchar(128) NOT NULL DEFAULT '' COMMENT 'thời gian bắt đầu',
  `stop_time` varchar(128) NOT NULL DEFAULT '' COMMENT 'thời gian kết thúc',
  `add_time` varchar(128) NOT NULL DEFAULT '' COMMENT 'Thêm thời gian',
  `status` tinyint(1) UNSIGNED NOT NULL DEFAULT '1' COMMENT 'Tình trạng sản phẩm',
  `is_postage` tinyint(1) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Có miễn phí vận chuyển không?',
  `is_hot` tinyint(1) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Khuyến nghị phổ biến',
  `is_del` tinyint(1) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Xóa 0 Chưa xóa 1 Đã xóa',
  `num` int(11) UNSIGNED NOT NULL DEFAULT '1' COMMENT 'Giết nhiều nhất vài giây',
  `is_show` tinyint(1) UNSIGNED NOT NULL DEFAULT '1' COMMENT 'trình diễn',
  `time_id` varchar(255) NOT NULL DEFAULT '' COMMENT 'khoảng thời gianID',
  `temp_id` int(11) NOT NULL DEFAULT '0' COMMENT 'Mẫu vận chuyển hàng hóaID',
  `weight` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT 'Trọng lượng sản phẩm',
  `volume` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT 'khối lượng sản phẩm',
  `quota` int(10) NOT NULL DEFAULT '0' COMMENT 'Tổng giới hạn mua hàng',
  `quota_show` int(10) NOT NULL DEFAULT '0' COMMENT 'Hiển thị tổng giới hạn mua',
  `once_num` int(11) NOT NULL DEFAULT '0' COMMENT 'Số lượng mua một lần',
  `logistics` varchar(10) NOT NULL DEFAULT '1,2' COMMENT 'Loại hình hậu cần',
  `freight` tinyint(1) NOT NULL DEFAULT '2' COMMENT 'Cài đặt phí vận chuyển',
  `custom_form` varchar(2000) NOT NULL DEFAULT '' COMMENT 'Biểu mẫu tùy chỉnh',
  `virtual_type` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Loại sản phẩm',
  `is_commission` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Có nên giảm giá hoa hồng hay không',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `product_id` (`product_id`) USING BTREE,
  KEY `start_time` (`start_time`,`stop_time`) USING BTREE,
  KEY `is_del` (`is_del`) USING BTREE,
  KEY `is_hot` (`is_hot`) USING BTREE,
  KEY `is_show` (`status`) USING BTREE,
  KEY `add_time` (`add_time`) USING BTREE,
  KEY `sort` (`sort`) USING BTREE,
  KEY `is_postage` (`is_postage`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='Danh sách sản phẩm flash sale';

-- --------------------------------------------------------

--
-- cấu trúc bảng `eb_store_seckill_time`
--

CREATE TABLE IF NOT EXISTS `eb_store_seckill_time` (
  `seckill_id` int(10) NOT NULL DEFAULT '0' COMMENT 'hoạt động flash saleID',
  `time_id` int(10) NOT NULL DEFAULT '0' COMMENT 'khoảng thời gian flash saleID'
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='Lịch trình khuyến mãi chớp nhoáng';

