--
-- cấu trúc bảng `eb_store_service`
--

CREATE TABLE IF NOT EXISTS `eb_store_service` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT 'dịch vụ khách hàngid',
  `mer_id` int(11) NOT NULL DEFAULT '0' COMMENT 'Thương giaid',
  `uid` int(11) NOT NULL DEFAULT '0' COMMENT 'dịch vụ khách hànguid',
  `online` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Đang trực tuyến',
  `account` varchar(255) NOT NULL DEFAULT '' COMMENT 'tài khoản',
  `password` varchar(255) NOT NULL DEFAULT '' COMMENT 'mật khẩu',
  `avatar` varchar(250) NOT NULL DEFAULT '' COMMENT 'Hình đại diện dịch vụ khách hàng',
  `nickname` varchar(50) NOT NULL DEFAULT '' COMMENT 'Tên đại lý',
  `phone` varchar(20) NOT NULL DEFAULT '' COMMENT 'Số điện thoại dịch vụ khách hàng',
  `add_time` int(11) NOT NULL DEFAULT '0' COMMENT 'Thêm thời gian',
  `status` tinyint(1) UNSIGNED NOT NULL DEFAULT '1' COMMENT '0ẩn1show',
  `notify` int(2) NOT NULL DEFAULT '0' COMMENT 'Thông báo đặt hàng 1 đang bật và 0 là tắt',
  `customer` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Có hiển thị quản lý thống kê hay không',
  `uniqid` varchar(35) NOT NULL DEFAULT '',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8 COMMENT='Mẫu dịch vụ khách hàng';

