--
-- cấu trúc bảng `eb_store_service_feedback`
--

CREATE TABLE IF NOT EXISTS `eb_store_service_feedback` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT 'tự tăngID',
  `uid` int(10) NOT NULL DEFAULT '0' COMMENT 'người dùngUID',
  `rela_name` varchar(255) COLLATE utf8_unicode_ci NOT NULL DEFAULT '' COMMENT 'Tên',
  `phone` varchar(30) COLLATE utf8_unicode_ci NOT NULL DEFAULT '' COMMENT 'Điện thoại',
  `content` varchar(500) COLLATE utf8_unicode_ci NOT NULL DEFAULT '' COMMENT 'Nội dung phản hồi',
  `make` varchar(255) COLLATE utf8_unicode_ci NOT NULL DEFAULT '' COMMENT 'Nhận xét',
  `status` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'tình trạng0=Chưa xem，1=Đã xem',
  `add_time` int(10) NOT NULL DEFAULT '0' COMMENT 'Thêm thời gian',
  PRIMARY KEY (`id`),
  KEY `uid` (`uid`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci COMMENT='nhận xét';

