--
-- cấu trúc bảng `eb_store_service_log`
--

CREATE TABLE IF NOT EXISTS `eb_store_service_log` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT 'Biểu mẫu bản ghi cuộc trò chuyện của người dùng dịch vụ khách hàngID',
  `mer_id` int(11) NOT NULL DEFAULT '0' COMMENT 'Thương giaid',
  `msn` text COMMENT 'Nội dung tin nhắn',
  `uid` int(11) NOT NULL DEFAULT '1' COMMENT 'người gửiuid',
  `to_uid` int(11) NOT NULL DEFAULT '1' COMMENT 'người nhậnuid',
  `is_tourist` tinyint(1) NOT NULL DEFAULT '0' COMMENT '1=chế độ khách，0=không phải khách du lịch',
  `time_node` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Nút thời gian',
  `add_time` int(11) NOT NULL DEFAULT '0' COMMENT 'Gửi thời gian',
  `type` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Đã đọc chưa (0: không; 1: có；）',
  `remind` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Bạn đã được nhắc nhở chưa?',
  `msn_type` tinyint(1) UNSIGNED NOT NULL DEFAULT '1' COMMENT 'Loại tin nhắn 1=Từ 2=sự biểu lộ 3=hình ảnh 4=tiếng nói',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='Biểu mẫu bản ghi cuộc trò chuyện của người dùng dịch vụ khách hàng';

-- --------------------------------------------------------

--
-- cấu trúc bảng `eb_store_service_record`
--

CREATE TABLE IF NOT EXISTS `eb_store_service_record` (
  `id` int(10) NOT NULL AUTO_INCREMENT COMMENT 'tự tăngID',
  `user_id` int(10) NOT NULL DEFAULT '0' COMMENT 'của người gửiuid',
  `to_uid` int(10) NOT NULL DEFAULT '0' COMMENT 'để giao hànguid',
  `nickname` varchar(50) COLLATE utf8_unicode_ci NOT NULL DEFAULT '' COMMENT 'Biệt hiệu của người dùng',
  `avatar` varchar(255) COLLATE utf8_unicode_ci NOT NULL DEFAULT '' COMMENT 'Hình đại diện của người dùng',
  `is_tourist` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Bạn có phải là khách du lịch?',
  `online` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Đang trực tuyến',
  `type` tinyint(1) NOT NULL DEFAULT '0' COMMENT '0 = pc,1=WeChat，2=Chương trình nhỏ，3=H5',
  `add_time` int(10) NOT NULL DEFAULT '0' COMMENT 'Thêm thời gian',
  `update_time` int(10) NOT NULL DEFAULT '0' COMMENT 'Thời gian cập nhật',
  `mssage_num` int(10) NOT NULL DEFAULT '0' COMMENT 'Số lượng tin nhắn',
  `message` text COLLATE utf8_unicode_ci COMMENT 'nội dung',
  `message_type` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Loại tin nhắn',
  PRIMARY KEY (`id`),
  KEY `to_uid` (`to_uid`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci COMMENT='Mẫu hồ sơ người dùng trò chuyện dịch vụ khách hàng';

-- --------------------------------------------------------

--
-- cấu trúc bảng `eb_store_service_speechcraft`
--

CREATE TABLE IF NOT EXISTS `eb_store_service_speechcraft` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT 'tự tăngID',
  `kefu_id` int(10) NOT NULL DEFAULT '0' COMMENT '0cho diễn ngôn toàn cầu',
  `cate_id` int(10) NOT NULL DEFAULT '0' COMMENT '0Diễn ngôn toàn cầu không phân loại',
  `title` varchar(100) COLLATE utf8_unicode_ci NOT NULL DEFAULT '' COMMENT 'tiêu đề tu từ',
  `message` varchar(255) COLLATE utf8_unicode_ci NOT NULL DEFAULT '' COMMENT 'nội dung diễn ngôn',
  `sort` int(10) NOT NULL DEFAULT '0' COMMENT 'loại',
  `add_time` int(10) NOT NULL DEFAULT '0' COMMENT 'Thêm thời gian',
  PRIMARY KEY (`id`),
  KEY `kefu_id` (`kefu_id`),
  KEY `cate_id` (`cate_id`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci COMMENT='Kỹ năng phục vụ khách hàng';

