  `id` int(10) NOT NULL AUTO_INCREMENT COMMENT 'tự tăngID',
  `product_id` int(11) NOT NULL DEFAULT '0' COMMENT 'hàng hóaID',
  `product_type` varchar(32) NOT NULL DEFAULT '' COMMENT 'Loại sản phẩm',
  `cate_id` int(11) NOT NULL DEFAULT '0' COMMENT 'Phân loại sản phẩmID',
  `type` char(50) NOT NULL DEFAULT '' COMMENT 'Loại sản phẩm',
