--
-- cấu trúc bảng `eb_system_admin`
--

CREATE TABLE IF NOT EXISTS `eb_system_admin` (
  `id` smallint(5) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'Bảng quản trị phụ trợID',
  `account` varchar(32) NOT NULL DEFAULT '' COMMENT 'Tài khoản quản trị viên phụ trợ',
  `head_pic` varchar(255) NOT NULL DEFAULT '' COMMENT 'Hình đại diện của quản trị viên',
  `pwd` varchar(100) NOT NULL DEFAULT '' COMMENT 'Mật khẩu quản trị viên phụ trợ',
  `real_name` varchar(16) NOT NULL DEFAULT '' COMMENT 'Tên quản trị viên phụ trợ',
  `roles` varchar(128) NOT NULL DEFAULT '' COMMENT 'Quyền quản trị viên phụ trợ(menus_id)',
  `last_ip` varchar(16) NOT NULL DEFAULT '' COMMENT 'Lần đăng nhập cuối cùng của quản trị viên phụ trợip',
  `last_time` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Lần đăng nhập cuối cùng của quản trị viên phụ trợ',
  `add_time` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Quản trị viên hậu trường thêm thời gian',
  `login_count` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Số lần đăng nhập',
  `level` tinyint(3) UNSIGNED NOT NULL DEFAULT '1' COMMENT 'Cấp quản trị viên phụ trợ',
  `status` tinyint(1) UNSIGNED NOT NULL DEFAULT '1' COMMENT 'Trạng thái quản trị viên nền 1 hợp lệ 0 không hợp lệ',
  `division_id` int(11) NOT NULL DEFAULT '0' COMMENT 'Đơn vị kinh doanhid',
  `is_del` tinyint(1) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Có nên xóa không',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `account` (`account`) USING BTREE,
  KEY `status` (`status`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8 COMMENT='Bảng quản trị phụ trợ';

