CREATE TABLE IF NOT EXISTS `eb_system_attachment` (
  `att_id` int(10) NOT NULL AUTO_INCREMENT COMMENT 'tự tăngID',
  `name` varchar(100) NOT NULL DEFAULT '' COMMENT 'Tên tệp đính kèm',
  `att_dir` varchar(200) NOT NULL DEFAULT '' COMMENT 'Đường dẫn đính kèm',
  `satt_dir` varchar(200) NOT NULL DEFAULT '' COMMENT 'Nén đường dẫn hình ảnh',
  `att_size` char(30) NOT NULL DEFAULT '' COMMENT 'Kích thước tệp đính kèm',
  `att_type` char(30) NOT NULL DEFAULT '' COMMENT 'Loại tệp đính kèm',
  `pid` int(10) NOT NULL DEFAULT '0' COMMENT 'Trình chỉnh sửa ID0 danh mục,1Hình ảnh sản phẩm,2Hình ảnh tập thể,3Hình ảnh mặc cả,4hình ảnh bán flash,5bài viết hình ảnh,6Sơ đồ dữ liệu kết hợp',
  `time` int(11) NOT NULL DEFAULT '0' COMMENT 'Thời gian tải lên',
  `image_type` tinyint(1) UNSIGNED NOT NULL DEFAULT '1' COMMENT 'Loại tải lên hình ảnh 1 Local 2 Qiniu Cloud 3OSS 4COS ',
  `module_type` tinyint(1) UNSIGNED NOT NULL DEFAULT '1' COMMENT 'Mô-đun tải lên hình ảnh loại 1 tải lên nền 2 do người dùng tạo',
  `real_name` varchar(255) NOT NULL DEFAULT '' COMMENT 'tên tập tin gốc',
  `scan_token` varchar(32) NOT NULL DEFAULT '' COMMENT 'Quét mã QR để tải lêntoken',
  `type` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Loại, 0 ảnh, 1 video',
  PRIMARY KEY (`att_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=92 DEFAULT CHARSET=utf8 COMMENT='Bảng quản lý tệp đính kèm';

