  `type` varchar(255) NOT NULL DEFAULT '' COMMENT 'kiểu(hộp văn bản,nút radio...)',
  `input_type` varchar(20) NOT NULL DEFAULT 'input' COMMENT 'loại hình thức',
  `config_tab_id` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Phân loại cấu hìnhid',
