  `high` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Chiều cao của hộp văn bản nhiều dòng',
  `value` varchar(5000) NOT NULL DEFAULT '' COMMENT 'giá trị mặc định',
  `info` varchar(255) NOT NULL DEFAULT '' COMMENT 'Tên cấu hình',
  `desc` varchar(255) NOT NULL DEFAULT '' COMMENT 'Giới thiệu cấu hình',
  `sort` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'loại',
  `status` tinyint(1) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Có nên giấu không',
  `level` int(11) NOT NULL DEFAULT '0' COMMENT 'Cấp cấu hình 0 cấp cao nhất 1 cấp thứ cấp',
  `link_id` int(11) NOT NULL DEFAULT '0' COMMENT 'Liên kết với cấu hình vượt trộiid',
  `link_value` int(11) NOT NULL DEFAULT '0' COMMENT 'Giá trị gắn liền với cấu hình vượt trội',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=435 DEFAULT CHARSET=utf8 COMMENT='bảng cấu hình';

