  `admin_id` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'quản trị viênid',
  `admin_name` varchar(64) NOT NULL DEFAULT '' COMMENT 'Tên quản trị viên',
  `path` varchar(128) NOT NULL DEFAULT '' COMMENT 'liên kết',
  `page` varchar(64) NOT NULL DEFAULT '' COMMENT 'Hành vi',
  `method` varchar(12) NOT NULL DEFAULT '' COMMENT 'kiểu truy cập',
  `ip` varchar(16) NOT NULL DEFAULT '' COMMENT 'Đăng nhậpIP',
  `type` varchar(32) NOT NULL DEFAULT '' COMMENT 'kiểu',
  `add_time` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Thời gian hoạt động',
  `merchant_id` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Thương giaid',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `admin_id` (`admin_id`) USING BTREE,
  KEY `add_time` (`add_time`) USING BTREE,
  KEY `type` (`type`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='Mẫu hồ sơ hoạt động của quản trị viên';

