--
-- cấu trúc bảng `eb_system_menus`
--

CREATE TABLE IF NOT EXISTS `eb_system_menus` (
  `id` smallint(5) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'thực đơnID',
  `pid` smallint(5) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'cha mẹid',
  `icon` varchar(16) NOT NULL DEFAULT '' COMMENT 'biểu tượng',
  `menu_name` varchar(32) NOT NULL DEFAULT '' COMMENT 'Tên nút',
  `module` varchar(32) CHARACTER SET utf8 COLLATE utf8_bin NOT NULL DEFAULT '' COMMENT 'tên mô-đun',
  `controller` varchar(64) CHARACTER SET utf8 COLLATE utf8_bin NOT NULL DEFAULT '' COMMENT 'bộ điều khiển',
  `action` varchar(32) CHARACTER SET utf8 COLLATE utf8_bin NOT NULL DEFAULT '' COMMENT 'tên phương thức',
  `api_url` varchar(100) NOT NULL DEFAULT '' COMMENT 'apiđịa chỉ giao diện',
  `methods` varchar(10) NOT NULL DEFAULT '' COMMENT 'Phương thức gửiPOST GET PUT DELETE',
  `params` varchar(128) CHARACTER SET utf8 COLLATE utf8_bin NOT NULL DEFAULT '[]' COMMENT 'tham số',
  `sort` tinyint(3) NOT NULL DEFAULT '1' COMMENT 'loại',
  `is_show` tinyint(1) UNSIGNED NOT NULL DEFAULT '1' COMMENT 'Cho dù đó là một menu ẩn0=Ẩn thực đơn,1=Hiển thị thực đơn',
  `is_show_path` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Có ẩn menu để sử dụng ở giao diện người dùng hay không',
  `access` tinyint(1) UNSIGNED NOT NULL DEFAULT '1' COMMENT 'Quản trị viên phụ có sẵn không?',
  `menu_path` varchar(128) NOT NULL DEFAULT '' COMMENT 'Tên tuyến đường được sử dụng bởi giao diện người dùng',
  `path` varchar(255) NOT NULL DEFAULT '' COMMENT 'con đường',
  `auth_type` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Cho dù đó là menu 1 menu 2 chức năng',
  `header` varchar(50) NOT NULL DEFAULT '' COMMENT 'Nhãn menu trên cùng',
  `is_header` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Cho dù menu trên cùng 1 có 0 không',
  `unique_auth` varchar(150) NOT NULL DEFAULT '' COMMENT 'ID duy nhất tại quầy lễ tân',
  `is_del` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Có nên xóa không',
  `mark` varchar(500) NOT NULL DEFAULT '' COMMENT 'Nhận xét',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `pid` (`pid`) USING BTREE,
  KEY `is_show` (`is_show`) USING BTREE,
  KEY `access` (`access`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=2473 DEFAULT CHARSET=utf8 COMMENT='bảng thực đơn';

