  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'mẫu thông báoid',
  `title` varchar(64) NOT NULL DEFAULT '' COMMENT 'Tiêu đề thông báo',
  `type` varchar(64) NOT NULL DEFAULT '' COMMENT 'loại thông báo',
  `icon` varchar(16) NOT NULL DEFAULT '' COMMENT 'biểu tượng',
  `url` varchar(64) NOT NULL DEFAULT '' COMMENT 'liên kết',
  `table_title` varchar(256) NOT NULL DEFAULT '' COMMENT 'dữ liệu thông báo',
  `template` varchar(64) NOT NULL DEFAULT '' COMMENT 'mẫu thông báo',
  `push_admin` varchar(128) NOT NULL DEFAULT '' COMMENT 'Thông báo cho quản trị viênid',
  `status` tinyint(1) UNSIGNED NOT NULL DEFAULT '1' COMMENT 'tình trạng',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `type` (`type`) USING BTREE,
  KEY `status` (`status`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='bảng mẫu thông báo';

-- --------------------------------------------------------

--
-- cấu trúc bảng `eb_system_notice_admin`
--

CREATE TABLE IF NOT EXISTS `eb_system_notice_admin` (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'Bản ghi thông báoID',
  `notice_type` varchar(64) NOT NULL DEFAULT '' COMMENT 'loại thông báo',
  `admin_id` smallint(5) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Quản trị viên đã thông báo',
  `link_id` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'sự kết hợpID',
  `table_data` text COMMENT 'dữ liệu thông báo',
  `is_click` tinyint(3) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Số nhấp chuột',
  `is_visit` tinyint(3) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'lượt truy cập',
  `visit_time` int(11) NOT NULL DEFAULT '0' COMMENT 'thời gian truy cập',
  `add_time` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Thời gian thông báo',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `admin_id` (`admin_id`,`notice_type`) USING BTREE,
  KEY `add_time` (`add_time`) USING BTREE,
  KEY `is_visit` (`is_visit`) USING BTREE,
  KEY `is_click` (`is_click`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='Mẫu biên bản thông báo';

-- --------------------------------------------------------

--
-- cấu trúc bảng `eb_system_notification`
--

CREATE TABLE IF NOT EXISTS `eb_system_notification` (
  `id` int(10) NOT NULL AUTO_INCREMENT COMMENT 'tự tăngID',
  `mark` varchar(50) NOT NULL DEFAULT '' COMMENT 'biểu tượng',
  `name` varchar(50) NOT NULL DEFAULT '' COMMENT 'loại thông báo',
  `title` varchar(100) NOT NULL DEFAULT '' COMMENT 'Mô tả kịch bản thông báo',
  `is_system` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Thông báo trang web (0: không tồn tại, 1: mở, 2: đóng）',
  `system_title` varchar(256) NOT NULL DEFAULT '' COMMENT 'Tiêu đề thư của trang web',
  `system_text` varchar(512) NOT NULL DEFAULT '' COMMENT 'Thông báo hệ thốngid',
  `is_wechat` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Thông báo mẫu tài khoản chính thức (0: không tồn tại, 1: mở, 2: đóng）',
  `wechat_tempkey` varchar(255) NOT NULL DEFAULT '' COMMENT 'tin nhắn mẫutempkey',
  `wechat_content` varchar(255) NOT NULL DEFAULT '' COMMENT 'Nội dung tin nhắn mẫu',
  `wechat_kid` varchar(255) NOT NULL DEFAULT '' COMMENT 'tin nhắn mẫukid',
  `wechat_tempid` varchar(255) NOT NULL DEFAULT '' COMMENT 'tin nhắn mẫutempid',
  `wechat_data` varchar(255) NOT NULL DEFAULT '' COMMENT 'Thông số tin nhắn mẫu',
  `wechat_link` varchar(255) NOT NULL DEFAULT '' COMMENT 'Liên kết tin nhắn mẫu',
  `wechat_to_routine` int(1) NOT NULL DEFAULT '0' COMMENT 'Applet chuyển tin nhắn mẫu',
  `is_routine` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Tin nhắn đăng ký chương trình mini (0: không tồn tại, 1: bật, 2: tắt）',
  `routine_tempkey` varchar(255) NOT NULL DEFAULT '' COMMENT 'Đăng ký nhận tin tứcid',
  `routine_content` varchar(255) NOT NULL DEFAULT '' COMMENT 'Đăng ký nội dung tin nhắn',
  `routine_kid` varchar(255) NOT NULL DEFAULT '' COMMENT 'Đăng ký nhận tin tứckid',
  `routine_tempid` varchar(255) NOT NULL DEFAULT '' COMMENT 'Đăng ký nhận tin tứctempid',
  `routine_data` varchar(255) NOT NULL DEFAULT '' COMMENT 'Thông số tin nhắn đăng ký',
  `routine_link` varchar(255) NOT NULL DEFAULT '' COMMENT 'Đăng ký liên kết tin nhắn',
  `is_sms` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Gửi SMS (0: không tồn tại, 1: bật, 2: tắt）',
  `sms_id` varchar(32) NOT NULL DEFAULT '' COMMENT 'Tin nhắn ngắnid',
  `sms_text` varchar(255) NOT NULL DEFAULT '' COMMENT 'Nội dung mẫu SMS',
  `is_ent_wechat` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Thông báo nhóm WeChat doanh nghiệp (0: không tồn tại, 1: mở, 2: đóng）',
  `ent_wechat_text` varchar(512) NOT NULL DEFAULT '' COMMENT 'Tin nhắn WeChat doanh nghiệp',
  `url` varchar(512) NOT NULL DEFAULT '' COMMENT 'Liên kết robot nhóm',
  `is_app` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'APPĐẩy (0: không tồn tại, 1: bật, 2: tắt）',
  `app_id` int(11) NOT NULL DEFAULT '0' COMMENT 'appxôid',
  `variable` varchar(256) NOT NULL DEFAULT '' COMMENT 'biến',
  `type` tinyint(1) NOT NULL DEFAULT '1' COMMENT 'Loại (1: Người dùng, 2: Quản trị viên）',
  `add_time` int(11) NOT NULL DEFAULT '0' COMMENT 'Thêm thời gian',
  `custom_trigger` varchar(255) NOT NULL DEFAULT '' COMMENT 'Vị trí kích hoạt tin nhắn tùy chỉnh',
  `custom_variable` varchar(1000) NOT NULL DEFAULT '' COMMENT 'Biến tin nhắn tùy chỉnh',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=27 DEFAULT CHARSET=utf8 COMMENT='Cài đặt thông báo';

