CREATE TABLE IF NOT EXISTS `eb_system_pem` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `type` varchar(255) NOT NULL DEFAULT '' COMMENT 'Loại chứng chỉ',
  `name` varchar(255) NOT NULL DEFAULT '' COMMENT 'Tên chứng chỉ',
  `path` varchar(255) NOT NULL DEFAULT '' COMMENT 'Tên tệp chứng chỉ',
  `content` text COMMENT 'Nội dung chứng chỉ',
  `add_time` int(11) NOT NULL DEFAULT '0' COMMENT 'Thêm thời gian',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='Mẫu giấy chứng nhận';

