CREATE TABLE IF NOT EXISTS `eb_system_role` (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'Quản lý danh tínhid',
  `role_name` varchar(32) NOT NULL DEFAULT '' COMMENT 'Tên quản lý danh tính',
  `rules` text COMMENT 'Quyền quản lý danh tính(menus_id)',
  `level` tinyint(3) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Cấp quản trị viên',
  `status` tinyint(1) UNSIGNED NOT NULL DEFAULT '1' COMMENT 'tình trạng',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `status` (`status`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='hình thức quản lý danh tính';

