--
-- cấu trúc bảng `eb_system_route`
--

CREATE TABLE IF NOT EXISTS `eb_system_route` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `cate_id` int(11) NOT NULL DEFAULT '0' COMMENT 'Phân loại',
  `app_name` varchar(20) NOT NULL DEFAULT 'api' COMMENT 'Tên ứng dụng',
  `name` varchar(50) NOT NULL DEFAULT '' COMMENT 'Tên tuyến đường',
  `describe` text NOT NULL COMMENT 'Mô tả chức năng',
  `path` varchar(100) NOT NULL DEFAULT '' COMMENT 'đường dẫn định tuyến',
  `method` enum('POST','GET','DELETE','PUT','*') NOT NULL DEFAULT 'GET' COMMENT 'Phương thức yêu cầu định tuyến',
  `file_path` varchar(255) NOT NULL DEFAULT '' COMMENT 'đường dẫn tập tin',
  `action` varchar(255) NOT NULL DEFAULT '' COMMENT 'tên phương thức',
  `query` longtext NOT NULL COMMENT 'getThông số yêu cầu',
  `header` longtext NOT NULL COMMENT 'header',
  `request` longtext NOT NULL COMMENT 'Yêu cầu dữ liệu',
  `request_type` varchar(100) NOT NULL DEFAULT '' COMMENT 'Loại yêu cầu',
  `response` longtext NOT NULL COMMENT 'Trả về dữ liệu',
  `request_example` longtext NOT NULL COMMENT 'Yêu cầu ví dụ',
  `response_example` longtext NOT NULL COMMENT 'Trả về ví dụ',
  `type` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'kiểu',
  `add_time` timestamp NOT NULL DEFAULT '0000-00-00 00:00:00' COMMENT 'Thêm thời gian',
  `delete_time` timestamp NULL DEFAULT NULL COMMENT 'Xóa trường',
  `error_code` longtext NOT NULL COMMENT 'mã lỗi',
  PRIMARY KEY (`id`),
  KEY `path` (`path`)
) ENGINE=InnoDB AUTO_INCREMENT=1695 DEFAULT CHARSET=utf8 COMMENT='bảng quy tắc định tuyến';

