  `pid` int(11) NOT NULL DEFAULT '0' COMMENT 'Thượng đẳngid',
  `app_name` varchar(20) NOT NULL DEFAULT '' COMMENT 'Tên ứng dụng',
  `name` varchar(50) NOT NULL DEFAULT '' COMMENT 'tên',
  `mark` varchar(32) NOT NULL DEFAULT '' COMMENT 'Mã nhóm',
  `path` varchar(255) NOT NULL DEFAULT '' COMMENT 'con đường',
  `sort` int(11) NOT NULL DEFAULT '0',
  `add_time` int(11) NOT NULL DEFAULT '0' COMMENT 'Thêm thời gian',
  PRIMARY KEY (`id`),
  KEY `app_name` (`app_name`)
) ENGINE=InnoDB AUTO_INCREMENT=184 DEFAULT CHARSET=utf8 COMMENT='Bảng phân loại kế hoạch định tuyến';

