-- cấu trúc bảng `eb_system_sign_reward`
--

CREATE TABLE IF NOT EXISTS `eb_system_sign_reward` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT 'số seri',
  `type` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Loại, 0 phần thưởng đăng nhập liên tiếp, 1 phần thưởng đăng nhập tích lũy',
  `days` int(11) NOT NULL DEFAULT '0' COMMENT 'ngày',
  `point` int(11) NOT NULL DEFAULT '0' COMMENT 'Tặng điểm',
  `exp` int(11) NOT NULL DEFAULT '0' COMMENT 'Trải nghiệm quà tặng',
  PRIMARY KEY (`id`)
