--
-- cấu trúc bảng `eb_system_storage`
--

CREATE TABLE IF NOT EXISTS `eb_system_storage` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT 'tự tăngID',
  `access_key` varchar(100) NOT NULL DEFAULT '' COMMENT 'access_key',
  `type` tinyint(1) NOT NULL DEFAULT '1' COMMENT '1=lưu trữ cục bộ,2=Qiniu,3=oss,4=cos',
  `name` varchar(100) NOT NULL DEFAULT '' COMMENT 'Tên không gian',
  `region` varchar(100) NOT NULL DEFAULT '' COMMENT 'khu vực',
  `acl` enum('private','public-read','public-read-write') NOT NULL DEFAULT 'public-read' COMMENT 'Quyền',
  `domain` varchar(100) NOT NULL DEFAULT '' COMMENT 'Tên miền không gian',
  `cdn` varchar(255) NOT NULL DEFAULT '' COMMENT 'CDNTăng tốc tên miền',
  `cname` varchar(255) NOT NULL DEFAULT '' COMMENT 'CNAMEgiá trị',
  `is_ssl` tinyint(1) NOT NULL DEFAULT '0' COMMENT '0=http,1=https',
  `status` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'tình trạng',
  `is_delete` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Có nên xóa không',
  `add_time` int(10) NOT NULL COMMENT 'Thêm sự kiện',
  `update_time` int(10) NOT NULL COMMENT 'Cập nhật sự kiện',
  PRIMARY KEY (`id`),
  KEY `is_delete` (`is_delete`),
  KEY `status` (`status`),
  KEY `access_key` (`access_key`,`type`,`is_delete`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='lưu trữ đám mây';

-- --------------------------------------------------------

--
-- cấu trúc bảng `eb_system_store`
--

CREATE TABLE IF NOT EXISTS `eb_system_store` (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'tự tăngID',
  `name` varchar(100) NOT NULL DEFAULT '' COMMENT 'Tên cửa hàng',
  `introduction` varchar(1000) NOT NULL DEFAULT '' COMMENT 'Giới thiệu',
  `phone` char(25) NOT NULL DEFAULT '' COMMENT 'số điện thoại',
  `address` varchar(255) NOT NULL DEFAULT '' COMMENT 'Các tỉnh, thành phố',
  `detailed_address` varchar(255) NOT NULL DEFAULT '' COMMENT 'Địa chỉ chi tiết',
  `image` varchar(255) NOT NULL DEFAULT '' COMMENT 'cửa hànglogo',
  `oblong_image` varchar(255) NOT NULL DEFAULT '' COMMENT 'Bản đồ đề xuất cửa hàng',
  `latitude` char(25) NOT NULL DEFAULT '' COMMENT 'vĩ độ',
  `longitude` char(25) NOT NULL DEFAULT '' COMMENT 'kinh độ',
  `valid_time` varchar(100) NOT NULL DEFAULT '' COMMENT 'Ngày hiệu lực xóa sổ',
  `day_time` varchar(100) NOT NULL DEFAULT '' COMMENT 'Thời gian mở và đóng cửa hàng ngày',
  `add_time` int(11) NOT NULL DEFAULT '0' COMMENT 'Thêm thời gian',
  `is_show` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Có hiển thị hay không',
  `is_del` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Có nên xóa không',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `phone` (`phone`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='Nhận tại cửa hàng';

-- --------------------------------------------------------

--
-- cấu trúc bảng `eb_system_store_staff`
--

CREATE TABLE IF NOT EXISTS `eb_system_store_staff` (
  `id` int(11) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'tự tăngID',
  `uid` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Người dùng WeChatid',
  `avatar` varchar(255) NOT NULL DEFAULT '' COMMENT 'Hình đại diện nhân viên cửa hàng',
  `store_id` int(11) NOT NULL DEFAULT '0' COMMENT 'cửa hàngid',
  `staff_name` varchar(64) NOT NULL DEFAULT '' COMMENT 'Tên nhân viên cửa hàng',
  `phone` char(15) NOT NULL DEFAULT '' COMMENT 'số điện thoại',
  `verify_status` tinyint(2) NOT NULL DEFAULT '0' COMMENT 'công tắc xóa',
  `status` tinyint(2) NOT NULL DEFAULT '1' COMMENT 'tình trạng',
  `add_time` int(10) NOT NULL DEFAULT '0' COMMENT 'Thêm thời gian',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='Danh sách nhân viên cửa hàng';

-- --------------------------------------------------------

--
-- cấu trúc bảng `eb_system_timer`
--

CREATE TABLE IF NOT EXISTS `eb_system_timer` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `name` varchar(255) NOT NULL DEFAULT '' COMMENT 'tên hẹn giờ',
  `mark` varchar(255) NOT NULL DEFAULT '' COMMENT 'Nhãn',
  `content` varchar(255) NOT NULL DEFAULT '' COMMENT 'minh họa',
  `type` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'trạng thái chu kỳ 1=cứ sau bao nhiêu giây 2=cứ sau bao nhiêu phút 3=cứ sau bao nhiêu giờ 4=cứ bao nhiêu ngày một lần 5=Nó thực hiện vào thời gian nào mỗi ngày? 6=Thực hiện vào thời gian nào mỗi tuần 7=Ngày và giờ thực hiện mỗi tháng',
  `month` int(11) NOT NULL DEFAULT '0' COMMENT 'mặt trăng',
  `week` int(11) NOT NULL DEFAULT '0' COMMENT 'tuần',
  `day` int(11) NOT NULL DEFAULT '0' COMMENT 'ngày',
  `hour` int(11) NOT NULL DEFAULT '0' COMMENT 'giờ',
  `minute` int(11) NOT NULL DEFAULT '0' COMMENT 'điểm',
  `second` int(11) NOT NULL DEFAULT '0' COMMENT 'Thứ hai',
  `last_execution_time` int(11) NOT NULL DEFAULT '0' COMMENT 'Thời gian thực hiện lần cuối',
  `next_execution_time` int(11) NOT NULL DEFAULT '0' COMMENT 'Lần thực hiện tiếp theo',
  `add_time` int(11) NOT NULL DEFAULT '0' COMMENT 'Thêm thời gian',
  `update_time` int(11) NOT NULL DEFAULT '0' COMMENT 'thời gian sửa đổi',
  `is_del` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Có nên xóa không',
  `is_open` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Có nên bật không',
  `customCode` text NOT NULL COMMENT 'Thực thi mã',
  `timeStr` varchar(255) NOT NULL DEFAULT '' COMMENT 'mã thời gian',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=10 DEFAULT CHARSET=utf8 COMMENT='hẹn giờ';

--
-- Truyền dữ liệu trong bảng `eb_system_timer`
--


-- --------------------------------------------------------

--
-- cấu trúc bảng `eb_system_user_level`
--

CREATE TABLE IF NOT EXISTS `eb_system_user_level` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT 'tự tăngID',
  `mer_id` int(11) NOT NULL DEFAULT '0' COMMENT 'Thương giaid',
  `name` varchar(255) NOT NULL DEFAULT '' COMMENT 'Tên thành viên',
  `money` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT 'số tiền mua',
  `valid_date` int(11) NOT NULL DEFAULT '0' COMMENT 'Thời gian hợp lệ',
  `is_forever` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Có phải là thành viên thường trực không?',
  `is_pay` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Có nên mua không,1=Mua,0=Đừng mua',
  `is_show` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Có hiển thị hay không 1=trình diễn,0=trốn',
  `grade` int(11) NOT NULL DEFAULT '0' COMMENT 'Cấp độ thành viên',
  `discount` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT 'tận hưởng giảm giá',
  `image` varchar(255) NOT NULL DEFAULT '' COMMENT 'nền thẻ thành viên',
  `icon` varchar(255) NOT NULL DEFAULT '' COMMENT 'Biểu tượng thành viên',
  `explain` text COMMENT 'minh họa',
  `add_time` int(11) NOT NULL DEFAULT '0' COMMENT 'Thêm thời gian',
  `is_del` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Có nên xóa không.1=xóa bỏ,0=không bị xóa',
  `exp_num` int(10) NOT NULL DEFAULT '0' COMMENT 'Nâng cấp trải nghiệm',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8 COMMENT='Thiết lập bảng cấp độ người dùng';

