--
-- cấu trúc bảng `eb_theme`
--

CREATE TABLE IF NOT EXISTS `eb_theme` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT 'tự tăngID',
  `version` varchar(255) NOT NULL DEFAULT '' COMMENT 'số phiên bản',
  `title` varchar(255) NOT NULL DEFAULT '' COMMENT 'Tên chủ đề',
  `info` varchar(255) NOT NULL DEFAULT '' COMMENT 'Giới thiệu chủ đề',
