  `home_data` longtext COMMENT 'Dữ liệu trang chủ',
  `home_image` varchar(255) NOT NULL DEFAULT '' COMMENT 'Hình ảnh trang chủ',
  `home_data_id` int(11) NOT NULL DEFAULT '0' COMMENT 'Nguồn dữ liệu trang chủid',
  `home_data_update_time` int(11) NOT NULL DEFAULT '0' COMMENT 'Thời gian cập nhật dữ liệu trang chủ',
  `category_data` longtext COMMENT 'Dữ liệu trang danh mục',
  `category_image` varchar(255) NOT NULL DEFAULT '' COMMENT 'Hình ảnh trang chuyên mục',
  `category_data_id` int(11) NOT NULL DEFAULT '0' COMMENT 'Nguồn dữ liệu trang danh mụcid',
  `category_data_update_time` int(11) NOT NULL DEFAULT '0' COMMENT 'Thời gian cập nhật dữ liệu trang chuyên mục',
  `detail_data` longtext COMMENT 'Dữ liệu trang chi tiết sản phẩm',
  `detail_image` varchar(255) NOT NULL DEFAULT '' COMMENT 'Hình ảnh trang chi tiết trung tâm mua sắm',
  `detail_data_id` int(11) NOT NULL DEFAULT '0' COMMENT 'Nguồn dữ liệu trang chi tiết sản phẩmid',
  `detail_data_update_time` int(11) NOT NULL DEFAULT '0' COMMENT 'Thời gian cập nhật dữ liệu trang chi tiết sản phẩm',
  `user_data` longtext COMMENT 'Dữ liệu trung tâm cá nhân',
  `user_image` varchar(255) NOT NULL DEFAULT '' COMMENT 'Hình ảnh trung tâm cá nhân',
  `user_data_id` int(11) NOT NULL DEFAULT '0' COMMENT 'Nguồn dữ liệu trung tâm cá nhânid',
  `user_data_update_time` int(11) NOT NULL DEFAULT '0' COMMENT 'Thời gian cập nhật dữ liệu trung tâm cá nhân',
  `theme_data` longtext COMMENT 'dữ liệu phong cách chủ đề',
  `theme_data_id` int(11) NOT NULL DEFAULT '0' COMMENT 'Nguồn dữ liệu kiểu chủ đềid',
  `theme_data_update_time` int(11) NOT NULL DEFAULT '0' COMMENT 'Thời gian cập nhật dữ liệu kiểu chủ đề',
  `home_default_data` longtext COMMENT 'Dữ liệu mặc định của trang chủ',
  `home_default_image` varchar(255) NOT NULL DEFAULT '' COMMENT 'Hình ảnh mặc định của trang chủ',
  `category_default_data` longtext COMMENT 'Dữ liệu mặc định của trang danh mục',
  `category_default_image` varchar(255) NOT NULL DEFAULT '' COMMENT 'Hình ảnh mặc định của trang chuyên mục',
  `detail_default_data` longtext COMMENT 'Dữ liệu mặc định của trang chi tiết sản phẩm',
  `detail_default_image` varchar(255) NOT NULL DEFAULT '' COMMENT 'Hình ảnh mặc định trên trang chi tiết trung tâm mua sắm',
  `user_default_data` longtext COMMENT 'Dữ liệu mặc định của trung tâm cá nhân',
  `user_default_image` varchar(255) NOT NULL DEFAULT '' COMMENT 'Hình ảnh mặc định của trung tâm cá nhân',
  `theme_default_data` longtext COMMENT 'Dữ liệu mặc định của kiểu chủ đề',
  `page_type` varchar(255) NOT NULL DEFAULT 'theme' COMMENT 'Loại trang: chủ đề chủ đề, trang vi mô',
  `is_use` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Có nên sử dụng không',
  `is_del` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Có nên xóa không',
  `add_time` int(11) NOT NULL DEFAULT '0' COMMENT 'Thêm thời gian',
  `up_time` int(11) NOT NULL DEFAULT '0' COMMENT 'Thời gian cập nhật',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8 COMMENT='Bảng chủ đề';

--
-- Truyền dữ liệu trong bảng `eb_theme`
--


-- --------------------------------------------------------

--
-- cấu trúc bảng `eb_theme_download`
--

CREATE TABLE IF NOT EXISTS `eb_theme_download` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT 'tự tăngID',
  `title` varchar(255) NOT NULL DEFAULT '' COMMENT 'Tên mẫu',
  `tid` int(11) NOT NULL DEFAULT '0' COMMENT 'giấy nếnID',
  `download_time` int(11) NOT NULL DEFAULT '0' COMMENT 'Thời gian tải xuống',
  `download_url` varchar(500) NOT NULL DEFAULT '' COMMENT 'Địa chỉ tải xuống',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Bảng ghi tải xuống chủ đề';

-- --------------------------------------------------------

--
-- cấu trúc bảng `eb_upgrade_log`
--

CREATE TABLE IF NOT EXISTS `eb_upgrade_log` (
  `id` int(10) NOT NULL AUTO_INCREMENT COMMENT 'tự tăngID',
  `title` varchar(120) NOT NULL DEFAULT '' COMMENT 'Tiêu đề Mô tả',
  `content` text NOT NULL COMMENT 'Cập nhật nội dung',
  `first_version` char(3) NOT NULL DEFAULT '' COMMENT 'Số phiên bản đầu tiên',
  `second_version` char(3) NOT NULL DEFAULT '' COMMENT 'Chữ số thứ hai của số phiên bản',
  `third_version` char(3) NOT NULL DEFAULT '' COMMENT 'Chữ số thứ ba của số phiên bản',
  `fourth_version` char(3) NOT NULL DEFAULT '' COMMENT 'Chữ số thứ tư của số phiên bản',
  `error_data` text NOT NULL COMMENT 'Nội dung lỗi',
  `upgrade_time` int(10) NOT NULL DEFAULT '0' COMMENT 'Thời gian nâng cấp',
  `package_link` varchar(255) NOT NULL DEFAULT '' COMMENT 'Địa chỉ sao lưu tập tin',
  `data_link` varchar(255) NOT NULL DEFAULT '' COMMENT 'Địa chỉ sao lưu dữ liệu',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Bản ghi nâng cấp';

-- --------------------------------------------------------

--
-- cấu trúc bảng `eb_user`
--

CREATE TABLE IF NOT EXISTS `eb_user` (
  `uid` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'người dùngid',
  `account` varchar(32) NOT NULL DEFAULT '' COMMENT 'Tài khoản người dùng',
  `pwd` varchar(32) NOT NULL DEFAULT '' COMMENT 'Mật khẩu người dùng',
  `real_name` varchar(25) NOT NULL DEFAULT '' COMMENT 'tên thật',
  `birthday` int(11) NOT NULL DEFAULT '0' COMMENT 'Sinh nhật',
  `card_id` varchar(20) NOT NULL DEFAULT '' COMMENT 'số CMND',
  `mark` varchar(255) NOT NULL DEFAULT '' COMMENT 'Nhận xét của người dùng',
  `partner_id` int(11) NOT NULL DEFAULT '0' COMMENT 'Cộng sựid',
  `group_id` int(11) NOT NULL DEFAULT '0' COMMENT 'Nhóm người dùngid',
  `nickname` varchar(60) NOT NULL DEFAULT '' COMMENT 'Biệt hiệu của người dùng',
  `avatar` varchar(256) NOT NULL DEFAULT '' COMMENT 'Hình đại diện của người dùng',
  `phone` char(15) NOT NULL DEFAULT '' COMMENT 'số điện thoại',
  `add_time` int(11) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Thêm thời gian',
  `add_ip` varchar(16) NOT NULL DEFAULT '' COMMENT 'Thêm vàoip',
  `last_time` int(11) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Lần đăng nhập cuối cùng',
  `last_ip` varchar(16) NOT NULL DEFAULT '' COMMENT 'lần đăng nhập cuối cùngip',
  `now_money` decimal(12,2) UNSIGNED NOT NULL DEFAULT '0.00' COMMENT 'Số dư người dùng',
  `brokerage_price` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT 'số tiền hoa hồng',
  `integral` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Điểm còn lại của người dùng',
  `exp` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT 'Trải nghiệm thành viên',
  `sign_num` int(11) NOT NULL DEFAULT '0' COMMENT 'Số ngày nhận phòng liên tiếp',
  `sign_remind` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Trạng thái nhắc nhở đăng ký',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '1là bình thường, 0 bị cấm',
  `level` tinyint(2) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'cấp',
  `agent_level` int(10) NOT NULL DEFAULT '0' COMMENT 'Cấp độ phân phối',
  `spread_open` tinyint(1) NOT NULL DEFAULT '1' COMMENT 'Bạn có đủ điều kiện để được thăng chức không?',
  `spread_uid` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'khuyến mãi nhân dân tệid',
  `spread_time` int(11) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Thời gian liên kết quảng bá',
  `user_type` varchar(32) NOT NULL DEFAULT '' COMMENT 'Loại người dùng',
  `is_promoter` tinyint(1) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Bạn có phải là người quảng bá?',
  `pay_count` int(11) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Số lần mua hàng được thực hiện bởi người dùng',
  `spread_count` int(11) NOT NULL DEFAULT '0' COMMENT 'Số lượng cấp dưới',
  `clean_time` int(11) NOT NULL DEFAULT '0' COMMENT 'Xóa thời gian thành viên',
  `addres` varchar(255) NOT NULL DEFAULT '' COMMENT 'Địa chỉ chi tiết',
  `adminid` int(11) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Số quản trị viên ',
  `login_type` varchar(36) NOT NULL DEFAULT '' COMMENT 'Kiểu đăng nhập của người dùng，h5,wechat,routine',
  `record_phone` varchar(11) NOT NULL DEFAULT '0' COMMENT 'Ghi lại các cuộc gọi điện thoại tạm thời',
  `is_money_level` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Nguồn thành viên  0: Mua sản phẩm nâng cấp 1: Thành viên bỏ tiền mua hàng2: Bộ sưu tập thẻ thành viên',
  `is_ever_level` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Có phải là thành viên thường trực không?  0: Thành viên không thường trực 1: Thành viên thường trực',
  `overdue_time` bigint(20) NOT NULL DEFAULT '0' COMMENT 'Thời gian hết hạn thành viên',
  `uniqid` varchar(32) NOT NULL DEFAULT '' COMMENT 'Giá trị duy nhất của người dùng',
  `division_name` varchar(255) NOT NULL DEFAULT '' COMMENT 'Tên đơn vị kinh doanh/đại lý',
  `division_type` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Loại đại lý: 0 thông thường, 1 bộ phận, 2 đại lý, 3 nhân viên',
  `division_status` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'trạng thái đại lý',
  `is_division` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Tình trạng phân chia',
  `is_agent` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'trạng thái đại lý',
  `is_staff` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Tình trạng nhân viên',
  `division_id` int(11) NOT NULL DEFAULT '0' COMMENT 'Đơn vị kinh doanhid',
  `agent_id` int(11) NOT NULL DEFAULT '0' COMMENT 'đại lýid',
  `staff_id` int(11) NOT NULL DEFAULT '0' COMMENT 'nhân viênid',
  `division_percent` int(11) NOT NULL DEFAULT '0' COMMENT 'tỷ lệ hoa hồng',
  `division_change_time` int(11) NOT NULL DEFAULT '0' COMMENT 'Thời gian điều chỉnh đơn vị kinh doanh/đại lý/nhân viên',
  `division_end_time` int(11) NOT NULL DEFAULT '0' COMMENT 'Thời gian kết thúc của bộ phận/đại lý/nhân viên',
  `division_invite` int(11) NOT NULL DEFAULT '0' COMMENT 'Mã mời đại lý',
  `is_del` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Có nên đăng xuất không',
  PRIMARY KEY (`uid`) USING BTREE,
  KEY `account` (`account`) USING BTREE,
  KEY `spreaduid` (`spread_uid`) USING BTREE,
  KEY `level` (`level`) USING BTREE,
  KEY `status` (`status`) USING BTREE,
  KEY `is_promoter` (`is_promoter`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8 COMMENT='Bảng người dùng';

--
-- Truyền dữ liệu trong bảng `eb_user`
--


-- --------------------------------------------------------

--
-- cấu trúc bảng `eb_user_address`
--

CREATE TABLE IF NOT EXISTS `eb_user_address` (
  `id` mediumint(8) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'Địa chỉ người dùngid',
  `uid` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'người dùngid',
  `real_name` varchar(32) NOT NULL DEFAULT '' COMMENT 'Tên người nhận hàng',
  `phone` varchar(16) NOT NULL DEFAULT '' COMMENT 'Số điện thoại của người nhận hàng',
  `province` varchar(64) NOT NULL DEFAULT '' COMMENT 'Tỉnh của người nhận hàng',
  `city` varchar(64) NOT NULL DEFAULT '' COMMENT 'Thành phố của người nhận hàng',
  `city_id` int(11) NOT NULL DEFAULT '0' COMMENT 'Thành phốid',
  `district` varchar(64) NOT NULL DEFAULT '' COMMENT 'Khu vực người nhận hàng',
  `detail` varchar(256) NOT NULL DEFAULT '' COMMENT 'Địa chỉ chi tiết của người nhận hàng',
  `post_code` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'mã bưu điện',
  `longitude` varchar(16) NOT NULL DEFAULT '0' COMMENT 'kinh độ',
  `latitude` varchar(16) NOT NULL DEFAULT '0' COMMENT 'vĩ độ',
  `is_default` tinyint(1) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Đây có phải là mặc định không',
  `is_del` tinyint(1) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Có nên xóa không',
  `add_time` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Thêm thời gian',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `uid` (`uid`) USING BTREE,
  KEY `is_default` (`is_default`) USING BTREE,
  KEY `is_del` (`is_del`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='Bảng địa chỉ người dùng';

-- --------------------------------------------------------

--
-- cấu trúc bảng `eb_user_bill`
--

CREATE TABLE IF NOT EXISTS `eb_user_bill` (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'Hóa đơn người dùngid',
  `uid` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'người dùnguid',
  `link_id` varchar(32) NOT NULL DEFAULT '0' COMMENT 'sự kết hợpid',
  `pm` tinyint(1) UNSIGNED NOT NULL DEFAULT '0' COMMENT '0 = chi tiêu 1 = lấy',
  `title` varchar(64) NOT NULL DEFAULT '' COMMENT 'Tiêu đề hóa đơn',
  `category` varchar(64) NOT NULL DEFAULT '' COMMENT 'Loại chi tiết',
  `type` varchar(64) NOT NULL DEFAULT '' COMMENT 'Loại chi tiết',
  `number` decimal(12,2) UNSIGNED NOT NULL DEFAULT '0.00' COMMENT 'Số liệu chi tiết',
  `balance` decimal(12,2) UNSIGNED NOT NULL DEFAULT '0.00' COMMENT 'Còn lại',
  `mark` varchar(512) NOT NULL DEFAULT '' COMMENT 'Nhận xét',
  `add_time` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Thêm thời gian',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '0 = Với đồng ý 1 = có hiệu quả -1 = không hợp lệ',
  `take` tinyint(1) NOT NULL DEFAULT '0' COMMENT '0 = Không nhận được 1 = Hàng đã nhận',
  `frozen_time` int(11) NOT NULL DEFAULT '0' COMMENT 'Thời gian đóng băng điểm',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `openid` (`uid`) USING BTREE,
  KEY `status` (`status`) USING BTREE,
  KEY `add_time` (`add_time`) USING BTREE,
  KEY `pm` (`pm`) USING BTREE,
  KEY `type` (`category`,`type`,`link_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='Mẫu hóa đơn người dùng';

-- --------------------------------------------------------

--
-- cấu trúc bảng `eb_user_brokerage`
--

CREATE TABLE IF NOT EXISTS `eb_user_brokerage` (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'Hoa hồng người dùngid',
  `uid` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'người dùnguid',
  `link_id` varchar(32) NOT NULL DEFAULT '0' COMMENT 'sự kết hợpid',
  `type` varchar(64) NOT NULL DEFAULT '' COMMENT 'Loại chi tiết',
  `title` varchar(64) NOT NULL DEFAULT '' COMMENT 'Tiêu đề hóa đơn',
  `number` decimal(12,2) UNSIGNED NOT NULL DEFAULT '0.00' COMMENT 'Số liệu chi tiết',
  `balance` decimal(12,2) UNSIGNED NOT NULL DEFAULT '0.00' COMMENT 'Còn lại',
  `pm` tinyint(1) UNSIGNED NOT NULL DEFAULT '0' COMMENT '0 = chi tiêu 1 = lấy',
  `mark` varchar(512) NOT NULL DEFAULT '' COMMENT 'Nhận xét',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '0 = Với đồng ý 1 = có hiệu quả -1 = không hợp lệ',
  `take` tinyint(1) NOT NULL DEFAULT '0' COMMENT '0 = Không nhận được 1 = Hàng đã nhận',
  `frozen_time` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Đóng băng thời gian hết hạn',
  `add_time` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Thêm thời gian',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `uid` (`uid`) USING BTREE,
  KEY `status` (`status`) USING BTREE,
  KEY `add_time` (`add_time`) USING BTREE,
  KEY `pm` (`pm`) USING BTREE,
  KEY `type` (`type`,`link_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='Bảng hóa đơn hoa hồng người dùng';

-- --------------------------------------------------------

--
-- cấu trúc bảng `eb_user_brokerage_frozen`
--

CREATE TABLE IF NOT EXISTS `eb_user_brokerage_frozen` (
  `id` int(10) NOT NULL AUTO_INCREMENT COMMENT 'tự tăngID',
  `uid` int(10) NOT NULL DEFAULT '0' COMMENT 'người dùnguid',
  `price` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT 'Số lượng',
  `uill_id` int(10) NOT NULL DEFAULT '0' COMMENT 'sự kết hợpid',
  `frozen_time` int(10) NOT NULL DEFAULT '0' COMMENT 'Đóng băng thời gian hết hạn',
  `status` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Nó có hợp lệ không?',
  `add_time` int(10) NOT NULL DEFAULT '0' COMMENT 'Thêm thời gian',
  `order_id` varchar(50) COLLATE utf8_unicode_ci NOT NULL DEFAULT '' COMMENT 'Đặt hàngid',
  PRIMARY KEY (`id`),
  KEY `uid` (`uid`,`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci COMMENT='Biểu mẫu đóng băng hoa hồng của người dùng';

-- --------------------------------------------------------

--
-- cấu trúc bảng `eb_user_cancel`
--

CREATE TABLE IF NOT EXISTS `eb_user_cancel` (
  `id` int(10) NOT NULL AUTO_INCREMENT COMMENT 'khóa chínhid',
  `uid` int(10) NOT NULL DEFAULT '0' COMMENT 'người dùnguid',
  `name` varchar(255) NOT NULL DEFAULT '' COMMENT 'Biệt hiệu của người dùng',
  `phone` varchar(20) NOT NULL DEFAULT '' COMMENT 'Số điện thoại',
  `add_time` int(11) NOT NULL DEFAULT '0' COMMENT 'Thời gian gửi của người dùng',
  `status` tinyint(1) NOT NULL DEFAULT '0' COMMENT '1Đạt, 2 bị từ chối',
  `up_time` int(11) NOT NULL DEFAULT '0' COMMENT 'Thời gian hoạt động',
  `remark` varchar(255) NOT NULL DEFAULT '' COMMENT 'Nhận xét',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='Biểu mẫu đăng xuất của người dùng';

-- --------------------------------------------------------

--
-- cấu trúc bảng `eb_user_enter`
--

CREATE TABLE IF NOT EXISTS `eb_user_enter` (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'Ứng dụng thương giaID',
  `uid` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'người dùngID',
  `province` varchar(32) NOT NULL DEFAULT '' COMMENT 'Tỉnh nơi người bán tọa lạc',
  `city` varchar(32) NOT NULL DEFAULT '' COMMENT 'Thành phố nơi người bán tọa lạc',
  `district` varchar(32) NOT NULL DEFAULT '' COMMENT 'Khu vực kinh doanh',
  `address` varchar(256) NOT NULL DEFAULT '' COMMENT 'Địa chỉ chi tiết của người bán',
  `merchant_name` varchar(256) NOT NULL DEFAULT '' COMMENT 'Tên người bán',
  `link_user` varchar(32) NOT NULL DEFAULT '' COMMENT 'Người dùng được liên kết',
  `link_tel` varchar(16) NOT NULL DEFAULT '' COMMENT 'Số điện thoại người bán',
  `charter` varchar(512) NOT NULL DEFAULT '' COMMENT 'Giấy chứng nhận thương gia',
  `add_time` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Thêm thời gian',
  `apply_time` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'thời gian xem xét',
  `success_time` int(11) NOT NULL DEFAULT '0' COMMENT 'thời gian trôi qua',
  `fail_message` varchar(256) NOT NULL DEFAULT '' COMMENT 'Lý do thất bại',
  `fail_time` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'thời gian thất bại',
  `status` tinyint(1) NOT NULL DEFAULT '0' COMMENT '-1 Không vượt qua được đánh giá 0 Không được đánh giá 1 Đã vượt qua đánh giá',
  `is_lock` tinyint(1) UNSIGNED NOT NULL DEFAULT '0' COMMENT '0 = bật lên 1= đóng cửa',
  `is_del` tinyint(1) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Có nên xóa không',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uid` (`uid`) USING BTREE,
  KEY `province` (`province`,`city`,`district`) USING BTREE,
  KEY `is_lock` (`is_lock`) USING BTREE,
  KEY `is_del` (`is_del`) USING BTREE,
  KEY `status` (`status`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='Mẫu đơn đăng ký thương gia';

-- --------------------------------------------------------

--
-- cấu trúc bảng `eb_user_extract`
--

CREATE TABLE IF NOT EXISTS `eb_user_extract` (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'tự tăngID',
  `wechat_order_id` varchar(32) NOT NULL DEFAULT '' COMMENT 'Đặt hàng WeChatID',
  `uid` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'người dùngid',
  `real_name` varchar(64) NOT NULL DEFAULT '' COMMENT 'tên',
  `user_name` varchar(64) NOT NULL DEFAULT '' COMMENT 'Tên người dùng',
  `extract_type` varchar(32) NOT NULL DEFAULT 'bank' COMMENT 'bank = thẻ ngân hàng alipay = Alipaywx=WeChat',
  `bank_code` varchar(32) NOT NULL DEFAULT '0' COMMENT 'thẻ ngân hàng',
  `bank_address` varchar(256) NOT NULL DEFAULT '' COMMENT 'Địa chỉ mở tài khoản',
  `alipay_code` varchar(64) NOT NULL DEFAULT '' COMMENT 'tài khoản Alipay',
  `extract_price` decimal(12,2) UNSIGNED NOT NULL DEFAULT '0.00' COMMENT 'Số tiền rút',
  `extract_fee` decimal(12,2) UNSIGNED NOT NULL DEFAULT '0.00' COMMENT 'Phí rút tiền',
  `mark` varchar(512) NOT NULL DEFAULT '' COMMENT 'Nhận xét',
  `balance` decimal(12,2) UNSIGNED NOT NULL DEFAULT '0.00' COMMENT 'Hoa hồng trước khi rút tiền',
  `fail_msg` varchar(128) NOT NULL DEFAULT '' COMMENT 'Lý do không hợp lệ',
  `fail_time` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'thời gian không hợp lệ',
  `add_time` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Thêm thời gian',
  `status` tinyint(2) NOT NULL DEFAULT '0' COMMENT '-1 Không đạt 0 Đang xem xét 1 Đã rút tiền',
  `wechat` varchar(50) NOT NULL DEFAULT '' COMMENT 'ID WeChat',
  `qrcode_url` varchar(255) NOT NULL DEFAULT '' COMMENT 'địa chỉ mã QR',
  `channel_type` VARCHAR(32) NOT NULL DEFAULT '' COMMENT 'Nguồn rút',
  `out_bill_no` varchar(255) NOT NULL DEFAULT '' COMMENT 'Số đơn đặt hàng của người bán',
  `transfer_bill_no` varchar(255) NOT NULL DEFAULT '' COMMENT 'tài khoản chuyển WeChat',
  `state` varchar(32) NOT NULL DEFAULT '' COMMENT 'Trạng thái tài liệu',
  `package_info` varchar(2000) NOT NULL DEFAULT '' COMMENT 'Chuyển đến thông tin gói của trang bộ sưu tập',
  `fail_reason` varchar(255) NOT NULL DEFAULT '' COMMENT 'Lý do thất bại',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `extract_type` (`extract_type`) USING BTREE,
  KEY `status` (`status`) USING BTREE,
  KEY `add_time` (`add_time`) USING BTREE,
  KEY `openid` (`uid`) USING BTREE,
  KEY `fail_time` (`fail_time`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='Hình thức rút tiền của người dùng';

-- --------------------------------------------------------

