CREATE TABLE IF NOT EXISTS `eb_user_friends` (
  `id` int(10) NOT NULL AUTO_INCREMENT COMMENT 'tự tăngID',
  `uid` int(10) NOT NULL DEFAULT '0' COMMENT 'người dùnguid',
  `friends_uid` int(10) NOT NULL DEFAULT '0' COMMENT 'bạnuid',
  `add_time` int(10) NOT NULL DEFAULT '0' COMMENT 'Thêm thời gian',
  PRIMARY KEY (`id`),
  KEY `uid` (`uid`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci COMMENT='Mối quan hệ bạn bè người dùng';

