--
-- cấu trúc bảng `eb_user_group`
--

CREATE TABLE IF NOT EXISTS `eb_user_group` (
  `id` smallint(5) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'tự tăngID',
  `group_name` varchar(64) NOT NULL DEFAULT '' COMMENT 'Tên nhóm người dùng',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8 COMMENT='Bảng nhóm người dùng';

