--
-- cấu trúc bảng `eb_user_invoice`
--

CREATE TABLE IF NOT EXISTS `eb_user_invoice` (
  `id` int(10) NOT NULL AUTO_INCREMENT COMMENT 'tự tăngID',
  `uid` int(10) NOT NULL DEFAULT '0' COMMENT 'người dùngid',
  `header_type` tinyint(1) NOT NULL DEFAULT '1' COMMENT 'loại tiêu đề1:Cá nhân 2: Kinh doanh',
  `type` tinyint(1) NOT NULL DEFAULT '1' COMMENT 'Loại hóa đơn 1: Thông thường 2: Đặc biệt',
  `name` varchar(100) NOT NULL DEFAULT '' COMMENT 'Tên (tiêu đề hóa đơn）',
  `duty_number` varchar(50) NOT NULL DEFAULT '' COMMENT 'Mã số thuế',
  `drawer_phone` varchar(30) NOT NULL DEFAULT '' COMMENT 'Số điện thoại di động của Biller',
  `email` varchar(100) NOT NULL DEFAULT '' COMMENT 'Địa chỉ email của người lập hoá đơn',
  `tell` varchar(30) NOT NULL DEFAULT '' COMMENT 'Đăng ký số điện thoại',
  `address` varchar(255) NOT NULL DEFAULT '' COMMENT 'Địa chỉ đã đăng ký',
  `bank` varchar(50) NOT NULL DEFAULT '' COMMENT 'Đăng ký tài khoản ngân hàng',
  `card_number` varchar(50) NOT NULL DEFAULT '' COMMENT 'Số thẻ ngân hàng',
  `is_default` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Đây có phải là mặc định không',
  `is_del` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Có nên xóa không',
  `add_time` int(10) NOT NULL DEFAULT '0' COMMENT 'Thêm thời gian',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='Form quản lý hóa đơn người dùng' ROW_FORMAT=DYNAMIC;

