--
-- cấu trúc bảng `eb_user_label`
--

CREATE TABLE IF NOT EXISTS `eb_user_label` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT 'tự tăngID',
  `label_cate` int(10) NOT NULL DEFAULT '0' COMMENT 'Phân loại thẻ',
  `label_name` varchar(255) NOT NULL DEFAULT '' COMMENT 'Tên thẻ',
  PRIMARY KEY (`id`),
  KEY `label_cate` (`label_cate`)
) ENGINE=InnoDB AUTO_INCREMENT=29 DEFAULT CHARSET=utf8 COMMENT='Bảng thẻ người dùng';

