-- cấu trúc bảng `eb_user_label_relation`
--

CREATE TABLE IF NOT EXISTS `eb_user_label_relation` (
  `uid` int(11) NOT NULL DEFAULT '0' COMMENT 'người dùngID',
  `label_id` int(11) NOT NULL DEFAULT '0' COMMENT 'NhãnID'
