--
-- cấu trúc bảng `eb_user_level`
--

CREATE TABLE IF NOT EXISTS `eb_user_level` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT 'tự tăngID',
  `uid` int(11) NOT NULL DEFAULT '0' COMMENT 'người dùnguid',
  `level_id` int(11) NOT NULL DEFAULT '0' COMMENT 'cấpvip',
  `grade` int(11) NOT NULL DEFAULT '0' COMMENT 'Cấp độ thành viên',
  `valid_time` int(11) NOT NULL DEFAULT '0' COMMENT 'Thời gian hết hạn',
  `is_forever` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Nó có vĩnh viễn không?',
  `mer_id` int(11) NOT NULL DEFAULT '0' COMMENT 'Thương giaid',
  `status` tinyint(1) NOT NULL DEFAULT '0' COMMENT '0:cấm,1:Bình thường',
  `mark` varchar(255) NOT NULL DEFAULT '' COMMENT 'Nhận xét',
  `remind` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Nó đã được thông báo chưa?',
  `is_del` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Có nên xóa không,0=không bị xóa,1=xóa bỏ',
  `add_time` int(11) NOT NULL DEFAULT '0' COMMENT 'Thêm thời gian',
  `discount` int(11) NOT NULL DEFAULT '0' COMMENT 'tận hưởng giảm giá',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `id` (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8 COMMENT='Bảng ghi cấp độ người dùng';

