--
-- cấu trúc bảng `eb_user_money`
--

CREATE TABLE IF NOT EXISTS `eb_user_money` (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'Số dư người dùngid',
  `uid` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'người dùnguid',
  `link_id` varchar(32) NOT NULL DEFAULT '0' COMMENT 'sự kết hợpid',
  `type` varchar(64) NOT NULL DEFAULT '' COMMENT 'Loại chi tiết',
  `title` varchar(64) NOT NULL DEFAULT '' COMMENT 'Tiêu đề hóa đơn',
  `number` decimal(12,2) UNSIGNED NOT NULL DEFAULT '0.00' COMMENT 'Số liệu chi tiết',
  `balance` decimal(12,2) UNSIGNED NOT NULL DEFAULT '0.00' COMMENT 'Còn lại',
  `pm` tinyint(1) UNSIGNED NOT NULL DEFAULT '0' COMMENT '0 = chi tiêu 1 = lấy',
  `mark` varchar(512) NOT NULL DEFAULT '' COMMENT 'Nhận xét',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '0 = Với đồng ý 1 = có hiệu quả -1 = không hợp lệ',
  `add_time` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Thêm thời gian',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `uid` (`uid`) USING BTREE,
  KEY `status` (`status`) USING BTREE,
  KEY `add_time` (`add_time`) USING BTREE,
  KEY `pm` (`pm`) USING BTREE,
  KEY `type` (`type`,`link_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='Bảng hóa đơn số dư người dùng';

-- --------------------------------------------------------

--
-- cấu trúc bảng `eb_user_notice`
--

CREATE TABLE IF NOT EXISTS `eb_user_notice` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT 'tự tăngID',
  `uid` text COMMENT 'ID người dùng đã nhận được tin nhắn (loại: dữ liệu json）',
  `type` tinyint(1) NOT NULL DEFAULT '1' COMMENT 'Loại thông báo tin nhắn (1: tin nhắn hệ thống; 2: thông báo người dùng）',
  `user` varchar(20) NOT NULL DEFAULT '' COMMENT 'người gửi',
  `title` varchar(20) NOT NULL DEFAULT '' COMMENT 'Thông tin tiêu đề của tin nhắn thông báo',
  `content` varchar(500) NOT NULL DEFAULT '' COMMENT 'Nội dung tin nhắn thông báo',
  `add_time` int(11) NOT NULL DEFAULT '0' COMMENT 'Thời điểm tin nhắn thông báo được gửi',
  `is_send` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Có gửi hay không (0: chưa gửi; 1: đã gửi）',
  `send_time` int(11) NOT NULL DEFAULT '0' COMMENT 'Gửi thời gian',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='Mẫu thông báo người dùng';

-- --------------------------------------------------------

--
-- cấu trúc bảng `eb_user_notice_see`
--

CREATE TABLE IF NOT EXISTS `eb_user_notice_see` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT 'tự tăngID',
  `nid` int(11) NOT NULL DEFAULT '0' COMMENT 'Đã xem thông báoid',
  `uid` int(11) NOT NULL DEFAULT '0' COMMENT 'Người dùng xem thông báoid',
  `add_time` int(11) NOT NULL DEFAULT '0' COMMENT 'Thời gian xem thông báo',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='Thông báo người dùng gửi bảng ghi';

-- --------------------------------------------------------

--
-- cấu trúc bảng `eb_user_recharge`
--

CREATE TABLE IF NOT EXISTS `eb_user_recharge` (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'tự tăngID',
  `uid` int(10) NOT NULL DEFAULT '0' COMMENT 'Nạp tiền cho người dùngUID',
  `order_id` varchar(32) NOT NULL DEFAULT '' COMMENT 'Số đơn hàng',
  `trade_no` varchar(100) NOT NULL DEFAULT '' COMMENT 'Số đơn đặt hàng WeChat',
  `price` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT 'Số tiền nạp',
  `give_price` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT 'Tín dụng mua hàng',
  `recharge_type` varchar(32) NOT NULL DEFAULT '' COMMENT 'Loại nạp tiền',
  `paid` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Có nên nạp tiền không',
  `pay_time` int(10) NOT NULL DEFAULT '0' COMMENT 'Thời gian thanh toán nạp tiền',
  `add_time` int(12) NOT NULL DEFAULT '0' COMMENT 'thời gian nạp tiền',
  `refund_price` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT 'Số tiền hoàn lại',
  `channel_type` varchar(255) NOT NULL DEFAULT '' COMMENT 'ID thiết bị đầu cuối truy cập của người dùng',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `order_id` (`order_id`) USING BTREE,
  KEY `uid` (`uid`) USING BTREE,
  KEY `recharge_type` (`recharge_type`) USING BTREE,
  KEY `paid` (`paid`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='Bảng nạp tiền của người dùng';

-- --------------------------------------------------------

--
-- cấu trúc bảng `eb_user_search`
--

CREATE TABLE IF NOT EXISTS `eb_user_search` (
  `id` int(10) NOT NULL AUTO_INCREMENT COMMENT 'tự tăngID',
  `uid` int(10) NOT NULL DEFAULT '0' COMMENT 'người dùnguid',
  `keyword` varchar(255) NOT NULL DEFAULT '' COMMENT 'Tìm kiếm từ khóa',
  `vicword` varchar(1000) NOT NULL DEFAULT '' COMMENT 'Phân đoạn từ khóa',
  `num` int(8) NOT NULL DEFAULT '1' COMMENT 'Tìm kiếm',
  `result` text COMMENT 'Kết quả tìm kiếm',
  `is_del` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'xóa bỏ',
  `add_time` int(10) NOT NULL DEFAULT '0' COMMENT 'thời gian',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='Bảng ghi tìm kiếm người dùng';

-- --------------------------------------------------------

--
-- cấu trúc bảng `eb_user_sign`
--

CREATE TABLE IF NOT EXISTS `eb_user_sign` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT 'tự tăngID',
  `uid` int(11) NOT NULL DEFAULT '0' COMMENT 'người dùnguid',
  `title` varchar(255) NOT NULL DEFAULT '' COMMENT 'Hướng dẫn đăng nhập',
  `number` int(11) NOT NULL DEFAULT '0' COMMENT 'nhận được điểm',
  `balance` int(11) NOT NULL DEFAULT '0' COMMENT 'điểm còn lại',
  `add_time` int(11) NOT NULL DEFAULT '0' COMMENT 'Thêm thời gian',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `uid` (`uid`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='Bảng ghi đăng nhập';

-- --------------------------------------------------------

--
-- cấu trúc bảng `eb_user_spread`
--

CREATE TABLE IF NOT EXISTS `eb_user_spread` (
  `id` int(10) NOT NULL AUTO_INCREMENT COMMENT 'tự tăngID',
  `uid` int(10) NOT NULL DEFAULT '0' COMMENT 'người dùnguid',
  `spread_uid` int(10) NOT NULL DEFAULT '0' COMMENT 'người quảng báuid',
  `spread_time` int(10) NOT NULL DEFAULT '0' COMMENT 'Thời gian khuyến mãi',
  PRIMARY KEY (`id`),
  KEY `uid` (`uid`) USING BTREE,
  KEY `spread_uid` (`spread_uid`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='Bảng quan hệ thăng hạng người dùng';

-- --------------------------------------------------------

--
-- cấu trúc bảng `eb_user_visit`
--

CREATE TABLE IF NOT EXISTS `eb_user_visit` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT 'tự tăngID',
  `uid` int(11) NOT NULL DEFAULT '0' COMMENT 'người dùnguid',
  `url` varchar(255) NOT NULL DEFAULT '' COMMENT 'đường dẫn truy cập',
  `ip` varchar(255) NOT NULL DEFAULT '' COMMENT 'người dùngip',
  `stay_time` int(11) NOT NULL DEFAULT '0' COMMENT 'Thời gian trên trang(Thứ hai)',
  `add_time` int(11) NOT NULL DEFAULT '0' COMMENT 'thời gian truy cập',
  `channel_type` varchar(255) NOT NULL DEFAULT '' COMMENT 'ID thiết bị đầu cuối truy cập của người dùng',
  `province` varchar(255) NOT NULL DEFAULT '' COMMENT 'Tỉnh người dùng',
  PRIMARY KEY (`id`),
  KEY `time` (`channel_type`,`add_time`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='bảng truy cập của người dùng';

-- --------------------------------------------------------

--
-- cấu trúc bảng `eb_wechat_key`
--

CREATE TABLE IF NOT EXISTS `eb_wechat_key` (
  `id` mediumint(8) NOT NULL AUTO_INCREMENT COMMENT 'tự tăngID',
  `reply_id` mediumint(8) NOT NULL DEFAULT '0' COMMENT 'Trả lời nội dungid',
  `keys` varchar(64) NOT NULL DEFAULT '' COMMENT 'từ khóa',
  `key_type` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Loại trả lời, 0 trả lời tự động tài khoản chính thức, 1 trả lời tự động dịch vụ khách hàng',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=MyISAM DEFAULT CHARSET=utf8 COMMENT='Bảng phụ trợ từ khóa trả lời WeChat' ROW_FORMAT=DYNAMIC;

-- --------------------------------------------------------

--
-- cấu trúc bảng `eb_wechat_media`
--

CREATE TABLE IF NOT EXISTS `eb_wechat_media` (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'Âm thanh video WeChatid',
  `type` varchar(16) NOT NULL DEFAULT '' COMMENT 'Kiểu trả lời',
  `path` varchar(128) NOT NULL DEFAULT '' COMMENT 'đường dẫn tập tin',
  `media_id` varchar(64) NOT NULL DEFAULT '' COMMENT 'Được trả về bởi máy chủ WeChatid',
  `url` varchar(256) NOT NULL DEFAULT '' COMMENT 'Địa chỉ',
  `temporary` tinyint(1) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Dù là vĩnh viễn hay tạm thời 0 vĩnh viễn 1 tạm thời',
  `add_time` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Thêm thời gian',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `type` (`type`,`media_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='Mẫu trả lời WeChat';

-- --------------------------------------------------------

--
-- cấu trúc bảng `eb_wechat_message`
--

CREATE TABLE IF NOT EXISTS `eb_wechat_message` (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'Hồ sơ hành vi người dùngid',
  `openid` varchar(32) NOT NULL DEFAULT '' COMMENT 'người dùngopenid',
  `type` varchar(32) NOT NULL DEFAULT '' COMMENT 'Loại hoạt động',
  `result` varchar(512) NOT NULL DEFAULT '' COMMENT 'Hồ sơ chi tiết về hoạt động',
  `add_time` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Thời gian hoạt động',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `openid` (`openid`) USING BTREE,
  KEY `type` (`type`) USING BTREE,
  KEY `add_time` (`add_time`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='Mẫu hồ sơ hành vi người dùng';

-- --------------------------------------------------------

--
-- cấu trúc bảng `eb_wechat_news_category`
--

CREATE TABLE IF NOT EXISTS `eb_wechat_news_category` (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'Quản lý tin nhắn đồ họa và văn bảnID',
  `cate_name` varchar(255) NOT NULL DEFAULT '' COMMENT 'Tên hình ảnh và văn bản',
  `sort` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'loại',
  `status` tinyint(1) UNSIGNED NOT NULL DEFAULT '1' COMMENT 'tình trạng',
  `new_id` varchar(255) NOT NULL DEFAULT '' COMMENT 'bài báoid',
  `add_time` varchar(255) NOT NULL DEFAULT '' COMMENT 'Thêm thời gian',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='Bảng quản lý tin nhắn đồ họa';

-- --------------------------------------------------------

--
-- cấu trúc bảng `eb_wechat_qrcode`
--

CREATE TABLE IF NOT EXISTS `eb_wechat_qrcode` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT 'số seri',
  `uid` int(11) NOT NULL DEFAULT '0' COMMENT 'người dùngid',
  `name` varchar(255) NOT NULL DEFAULT '' COMMENT 'Tên mã QR',
  `image` varchar(500) NOT NULL DEFAULT '' COMMENT 'hình ảnh mã QR',
  `cate_id` int(11) NOT NULL DEFAULT '0' COMMENT 'Phân loạiid',
  `label_id` varchar(32) NOT NULL DEFAULT '' COMMENT 'Nhãnid',
  `type` varchar(32) NOT NULL DEFAULT '' COMMENT 'Kiểu trả lời',
  `content` text COMMENT 'Trả lời nội dung',
  `data` text COMMENT 'Gửi dữ liệu',
  `follow` int(11) NOT NULL DEFAULT '0' COMMENT 'Số lượng người theo dõi',
  `scan` int(11) NOT NULL DEFAULT '0' COMMENT 'Số người quét mã QR',
  `add_time` int(11) NOT NULL DEFAULT '0' COMMENT 'Thêm thời gian',
  `continue_time` int(11) NOT NULL DEFAULT '0' COMMENT 'Thời hạn hiệu lực',
  `end_time` int(11) NOT NULL DEFAULT '0' COMMENT 'Thời gian hết hạn',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT 'tình trạng',
  `is_del` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Có nên xóa không',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='bảng mã QR';

-- --------------------------------------------------------

--
-- cấu trúc bảng `eb_wechat_qrcode_cate`
--

CREATE TABLE IF NOT EXISTS `eb_wechat_qrcode_cate` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT 'khóa chínhid',
  `cate_name` varchar(255) NOT NULL DEFAULT '' COMMENT 'Tên danh mục mã kênh',
  `add_time` int(11) NOT NULL DEFAULT '0' COMMENT 'Thêm thời gian',
  `is_del` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Có nên xóa không',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8 COMMENT='Bảng loại mã QR';

--
-- Truyền dữ liệu trong bảng `eb_wechat_qrcode_cate`
--


-- --------------------------------------------------------

--
-- cấu trúc bảng `eb_wechat_qrcode_record`
--

CREATE TABLE IF NOT EXISTS `eb_wechat_qrcode_record` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT 'tự tăngID',
  `qid` int(11) NOT NULL DEFAULT '0' COMMENT 'Mã kênhid',
  `uid` int(11) NOT NULL DEFAULT '0' COMMENT 'người dùngid',
  `is_follow` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Bạn có chú ý không?',
  `add_time` int(11) NOT NULL DEFAULT '0' COMMENT 'Thời gian quét',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='Mẫu bản ghi quét mã kênh';

-- --------------------------------------------------------

--
-- cấu trúc bảng `eb_wechat_reply`
--

CREATE TABLE IF NOT EXISTS `eb_wechat_reply` (
  `id` mediumint(8) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'Trả lời từ khóa WeChatid',
  `type` varchar(32) NOT NULL DEFAULT '' COMMENT 'Kiểu trả lời',
  `data` text COMMENT 'Trả lời dữ liệu',
  `status` tinyint(1) UNSIGNED NOT NULL DEFAULT '1' COMMENT '0=Không có sẵn  1 =Có sẵn',
  `hide` tinyint(1) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Có nên giấu không',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `type` (`type`) USING BTREE,
  KEY `status` (`status`) USING BTREE,
  KEY `hide` (`hide`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='Mẫu trả lời từ khóa WeChat';

-- --------------------------------------------------------

--
-- cấu trúc bảng `eb_wechat_user`
--

CREATE TABLE IF NOT EXISTS `eb_wechat_user` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT 'tự tăngID',
  `uid` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Người dùng WeChatid',
  `unionid` varchar(30) NOT NULL DEFAULT '' COMMENT 'Trường này sẽ chỉ xuất hiện sau khi người dùng liên kết tài khoản chính thức với tài khoản Nền tảng mở WeChat',
  `openid` varchar(255) NOT NULL DEFAULT '' COMMENT 'Mã định danh của người dùng, duy nhất cho tài khoản chính thức hiện tại',
  `nickname` varchar(64) NOT NULL DEFAULT '' COMMENT 'Biệt hiệu của người dùng',
  `headimgurl` varchar(256) NOT NULL DEFAULT '' COMMENT 'Hình đại diện của người dùng',
  `sex` tinyint(1) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Giới tính của người dùng. Khi giá trị là 1 thì là nam, khi giá trị là 2 thì là nữ và khi giá trị là 0 thì không xác định.',
  `city` varchar(64) NOT NULL DEFAULT '' COMMENT 'Thành phố của người dùng',
  `language` varchar(64) NOT NULL DEFAULT '' COMMENT 'Ngôn ngữ của người dùng, tiếng Trung giản thể làzh_CN',
  `province` varchar(64) NOT NULL DEFAULT '' COMMENT 'Tỉnh nơi người dùng cư trú',
  `country` varchar(64) NOT NULL DEFAULT '' COMMENT 'Quốc gia của người dùng',
  `remark` varchar(256) NOT NULL DEFAULT '' COMMENT 'Ghi chú cho người hâm mộ bởi các nhà khai thác tài khoản công cộng. Người điều hành tài khoản chính thức có thể thêm ghi chú cho người hâm mộ trên giao diện quản lý người dùng nền tảng công cộng WeChat.',
  `groupid` smallint(5) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'ID nhóm của người dùng (tương thích với giao diện nhóm người dùng cũ）',
  `tagid_list` varchar(256) NOT NULL DEFAULT '' COMMENT 'Danh sách ID thẻ được người dùng gắn thẻ',
  `subscribe` tinyint(3) UNSIGNED NOT NULL DEFAULT '1' COMMENT 'Người dùng có đăng ký logo tài khoản công khai hay không',
  `subscribe_time` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Theo dõi thời gian tài khoản chính thức',
  `add_time` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Thêm thời gian',
  `second` int(11) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Người giới thiệu phụ',
  `user_type` varchar(32) NOT NULL DEFAULT 'wechat' COMMENT 'Loại người dùng',
  `is_complete` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Thông tin có đầy đủ không?',
  `is_del` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Có nên đăng xuất không',
  PRIMARY KEY (`id`),
  UNIQUE KEY `openid` (`openid`,`uid`) USING BTREE,
  KEY `groupid` (`groupid`) USING BTREE,
  KEY `subscribe_time` (`subscribe_time`) USING BTREE,
  KEY `add_time` (`add_time`) USING BTREE,
  KEY `subscribe` (`subscribe`) USING BTREE,
  KEY `unionid` (`unionid`) USING BTREE,
  KEY `uid` (`uid`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='Bảng người dùng WeChat';

-- --------------------------------------------------------

--
-- cấu trúc bảng `eb_routine_scheme`
--

CREATE TABLE IF NOT EXISTS `eb_routine_scheme` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT 'số seri',
  `title` varchar(255) NOT NULL DEFAULT '' COMMENT 'tên',
  `path` varchar(255) NOT NULL DEFAULT '' COMMENT 'Địa chỉ trang chương trình nhỏ',
  `url` varchar(255) NOT NULL DEFAULT '' COMMENT 'Tạo địa chỉ liên kết',
  `add_time` int(11) NOT NULL DEFAULT '0' COMMENT 'Thêm thời gian',
  `expire_type` int(11) NOT NULL DEFAULT '-1' COMMENT 'Loại hết hạn',
  `expire_interval` int(11) NOT NULL DEFAULT '0' COMMENT 'Số ngày hết hạn',
  `expire_time` int(11) NOT NULL DEFAULT '0' COMMENT 'Thời gian hết hạn',
  `is_del` int(11) NOT NULL DEFAULT '0' COMMENT 'Có nên xóa không',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=15 DEFAULT CHARSET=utf8 COMMENT='Liên kết ngoài chương trình nhỏ';

-- --------------------------------------------------------

--
-- cấu trúc bảng `eb_system_ticket`
--

CREATE TABLE IF NOT EXISTS `eb_system_ticket` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT 'tự tăngid',
  `type` tinyint(1) NOT NULL DEFAULT '1' COMMENT 'Lựa chọn nền tảng, 1 Đám mây Yilian, 2 Đám mây Fei’e',
  `print_name` varchar(255) NOT NULL DEFAULT '' COMMENT 'Tên máy in',
  `yly_user_id` varchar(255) NOT NULL DEFAULT '' COMMENT 'Người dùng đám mây Yilianid',
  `yly_app_id` varchar(255) NOT NULL DEFAULT '' COMMENT 'Ứng dụng đám mây YilianID',
  `yly_app_secret` varchar(255) NOT NULL DEFAULT '' COMMENT 'Khóa ứng dụng đám mây Yilian',
  `yly_sn` varchar(255) NOT NULL DEFAULT '' COMMENT 'Số thiết bị đầu cuối đám mây Yilian',
  `fey_user` varchar(255) NOT NULL DEFAULT '' COMMENT 'Đám mây ngỗng bayuser',
  `fey_ukey` varchar(255) NOT NULL DEFAULT '' COMMENT 'Đám mây ngỗng bayukey',
  `fey_sn` varchar(255) NOT NULL DEFAULT '' COMMENT 'Đám mây ngỗng baySN',
  `times` int(11) NOT NULL DEFAULT '0' COMMENT 'In số lượng câu đối',
  `print_type` tinyint(1) NOT NULL DEFAULT '1' COMMENT 'Thời gian in, 1 sau khi thanh toán, 2 sau khi đặt hàng',
  `print_content` LONGTEXT NULL DEFAULT NULL COMMENT 'In nội dung',
  `add_time` int(11) NOT NULL DEFAULT '0' COMMENT 'Thêm thời gian',
  `status` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Trạng thái ứng dụng, 0 đã đóng, 1 đang mở',
  `is_del` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Có nên xóa không',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='Danh sách máy in hóa đơn';

-- --------------------------------------------------------

--
-- cấu trúc bảng `eb_spread_apply`
--

CREATE TABLE IF NOT EXISTS `eb_spread_apply` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT 'tự tăngid',
  `uid` int(11) NOT NULL DEFAULT '0' COMMENT 'người dùnguid',
  `nickname` varchar(255) NOT NULL DEFAULT '' COMMENT 'Biệt hiệu của người dùng',
  `real_name` varchar(255) NOT NULL DEFAULT '' COMMENT 'Tên người dùng',
  `phone` varchar(32) NOT NULL DEFAULT '0' COMMENT 'Số điện thoại của người dùng',
  `status` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Trạng thái đơn đăng ký: 0 đơn đăng ký, 1 đơn được chấp thuận, 2 bị từ chối',
  `add_time` int(11) NOT NULL DEFAULT '0' COMMENT 'Thời gian nộp đơn',
  `status_time` int(11) NOT NULL DEFAULT '0' COMMENT 'thời gian xem xét',
  `content` varchar(1000) NOT NULL DEFAULT '' COMMENT 'Nội dung tự đề xuất',
  `refusal_reason` varchar(1000) NOT NULL DEFAULT '' COMMENT 'Lý do từ chối',
  `is_del` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Có nên xóa không',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='Ứng dụng phân phối';

-- --------------------------------------------------------
