INSERT INTO `eb_system_config` (`id`, `menu_name`, `type`, `input_type`, `config_tab_id`, `parameter`, `upload_type`, `required`, `width`, `high`, `value`, `info`, `desc`, `sort`, `status`, `level`, `link_id`, `link_value`) VALUES
(1, 'site_name', 'text', 'input', 1, '', 1, 'required:true', 100, 0, '\"\"', 'Tên trang web', 'Được sử dụng trong nền, PC, H5, chia sẻ trang, tên trang web trên áp phích, v.v.', 97, 1, 0, 0, 0),
(2, 'site_url', 'text', 'input', 1, '', 1, 'required:true,url:true', 100, 0, '\"\"', 'địa chỉ trang web', 'Hệ thống sẽ được cấu hình tự động trong quá trình cài đặt; khuyên bạn không nên sửa đổi nó một cách dễ dàng! Việc thay thế sẽ ảnh hưởng đến quyền truy cập trang web, yêu cầu giao diện, lưu trữ tệp cục bộ, gọi lại thanh toán, ủy quyền WeChat, thanh toán, truy cập hình ảnh chương trình nhỏ, một số mã QR, ủy quyền chính thức, v.v.', 95, 1, 0, 0, 0),
(3, 'site_logo', 'upload', 'input', 122, '', 1, '', 0, 0, '\"\\/statics\\/system_images\\/admin_logo_big.png\"', 'Hậu trường lớnLOGO', 'Menu mở rộng góc trên bên tráilogo,Kích thước đề xuất[170*50]', 89, 1, 0, 0, 0),
(4, 'site_phone', 'text', 'input', 1, '', 0, '', 100, 0, '\"\"', 'Số liên lạc', 'Số liên lạc', 0, 0, 0, 0, 0),
(13, 'wechat_appid', 'text', 'input', 130, '', 1, '', 0, 0, '\"\"', 'AppID', 'Tài khoản công khai WeChatAppID', 99, 1, 0, 0, 0),
(14, 'wechat_appsecret', 'text', 'input', 130, '', 1, '', 0, 0, '\"\"', 'AppSecret', 'Tài khoản công khai WeChatAppSecret', 95, 1, 0, 0, 0),
(15, 'wechat_token', 'text', 'input', 131, '', 1, '', 0, 0, '\"\"', 'Xác minh WeChatTOKEN', 'Xác minh WeChatTOKEN', 88, 1, 0, 0, 0),
(16, 'wechat_encode', 'radio', 'input', 131, '0=>chế độ văn bản thuần túy\n1=>Chế độ tương thích\n2=>chế độ an toàn', 1, '', 0, 0, '0', 'Phương pháp mã hóa và giải mã tin nhắn', 'Nếu bạn cần sử dụng chế độ an toàn, vui lòng sửa đổi nó trong trung tâm quản lý. Điều này chỉ có sẵn cho các tài khoản dịch vụ và tài khoản đăng ký được chứng nhận.', 84, 1, 0, 0, 0),
(17, 'wechat_encodingaeskey', 'text', 'input', 131, '', 1, '', 0, 0, '\"\"', 'EncodingAESKey', 'Mã hóa và giải mã tin nhắn tài khoản công cộngKey,Để điền giá trị này khi sử dụng chế độ an toàn, trước tiên hãy sửa đổi nó trong trung tâm quản lý, sau đó điền giá trị. Chỉ hỗ trợ số dịch vụ xác thực.', 80, 1, 0, 0, 0),
(18, 'wechat_share_img', 'upload', 'input', 70, '', 1, '', 0, 0, '\"\"', 'Chia sẻ hình ảnh trên WeChat', 'Nếu bạn điền địa chỉ hình ảnh thì hình ảnh đó sẽ được chia sẻ khi bạn chia sẻ trang. Nó có thể ngăn chặn hiệu quả sự biến dạng và tỷ lệ của hình ảnh được chia sẻ.5:4，Nên nhỏ hơn50KB', 0, 1, 0, 0, 0),
(19, 'wechat_qrcode', 'upload', 'input', 130, '', 1, '', 0, 0, '\"\"', 'Theo dõi mã QR', 'Hướng dẫn tài khoản công khai hiển thị bằng cách theo dõi tài khoản công khai theo mã QR', 76, 1, 0, 0, 0),
(21, 'wechat_share_title', 'text', 'input', 70, '', 0, 'required:true', 100, 0, '\"\"', 'Tiêu đề chia sẻ WeChat', 'Tiêu đề chia sẻ WeChat', 0, 1, 0, 0, 0),
(22, 'wechat_share_synopsis', 'textarea', '', 70, '', 0, '', 100, 5, '\"\"', 'Giới thiệu chia sẻ WeChat', 'Giới thiệu chia sẻ WeChat', 0, 1, 0, 0, 0),
(25, 'pay_weixin_mchid', 'text', 'input', 4, '', 0, '', 100, 0, '\"\"', 'Mchid', 'Tài khoản người bán WeChat, tài khoản người bán WeChat', 0, 1, 0, 0, 0),
(26, 'pay_weixin_client_cert', 'upload', 'input', 4, '', 3, '', 0, 0, '\"\"', 'Chứng chỉ thanh toán WeChat', 'Có thể tải xuống chứng chỉ thanh toán WeChat trong nền tảng người bán WeChat! Tên tập tin thường làapiclient_cert.pem', 0, 1, 0, 0, 0),
(27, 'pay_weixin_client_key', 'upload', 'input', 4, '', 3, '', 0, 0, '\"\"', 'Khóa chứng chỉ thanh toán WeChat', 'Khóa chứng chỉ thanh toán WeChat có thể được tải xuống trong nền tảng người bán WeChat! Tên tập tin thường làapiclient_key.pem', 0, 1, 0, 0, 0),
(28, 'pay_weixin_key', 'text', 'input', 4, '', 0, '', 100, 0, '\"\"', 'Key', 'Khóa thanh toán của người bán. Sau khi vượt qua bài đánh giá, hãy kiểm tra nó trong email do WeChat gửi。', 0, 1, 0, 0, 0),
(29, 'pay_weixin_open', 'radio', 'input', 109, '0=>đóng cửa\nweixin=>WeChat\nallinpay=>giao tiếp', 1, '', 0, 0, '\"weixin\"', 'WeChat trả tiền', 'Vui lòng chọn kênh thanh toán WeChat và đóng ứng dụng khách để tránh hiển thị.', 100, 1, 0, 0, 0),
(32, 'store_free_postage', 'text', 'number', 114, '', 1, 'number:true,min:-1', 100, 0, '\"1000000\"', 'Miễn phí vận chuyển cho đơn hàng đã đặt', 'Miễn phí vận chuyển có sẵn cho các sản phẩm của trung tâm mua sắm trên một số tiền nhất định. Mặt hàng này được ưu tiên hơn các cài đặt vận chuyển khác.', 100, 1, 0, 0, 0),
(33, 'offline_postage', 'radio', 'input', 114, '1=>miễn phí vận chuyển\n0=>Không miễn phí vận chuyển', 1, '', 0, 0, '0', 'Bưu phí có miễn phí khi thanh toán ngoại tuyến không?', 'Người dùng chọn có bao gồm giao hàng miễn phí khi thanh toán ngoại tuyến hay không', 97, 1, 0, 0, 0),
(34, 'integral_ratio', 'text', 'input', 11, '', 0, 'number:true', 100, 0, '\"0.1\"', 'Điểm để đổi thưởng', 'Tỷ lệ quy đổi điểm(1Có thể sử dụng bao nhiêu điểm để đổi điểm?)Đơn vị: Nhân dân tệ', 10, 1, 0, 0, 0),
(44, 'store_user_min_recharge', 'text', 'number', 28, '', 1, 'required:true,number:true,min:0', 100, 0, '0.01', 'Số tiền nạp tối thiểu', 'Số tiền nạp tối thiểu cho người dùng', 3, 1, 0, 0, 0),
(46, 'system_express_app_code', 'text', 'input', 92, '', 1, '', 0, 0, '\"\"', 'Phím truy vấn nhanh', 'Giao diện truy vấn nhanh của Alibaba Cloud Market Express Địa chỉ mua hàng chính：https://market.aliyun.com/products/57126001/cmapi021863.html?spm=5176.2020520132.101.4.42a672183nvgfH#sku=yuncode1586300000', 0, 1, 0, 0, 0),
(49, 'store_brokerage_ratio', 'text', 'input', 73, '', 0, 'required:true,min:0,max:100,number:true', 100, 0, '\"0\"', 'Tỷ lệ chiết khấu cấp 1', 'Tỷ lệ chiết khấu hoa hồng được trao cho cấp trên sau khi lệnh được giao dịch thành công.0 - 100,ví dụ:5 = Hoàn lại số tiền đặt hàng5%', 5, 1, 0, 0, 0),
(53, 'user_extract_min_price', 'text', 'input', 74, '', 0, 'required:true,number:true,min:0', 100, 0, '\"1\"', 'Số tiền tối thiểu để rút', 'Giới hạn số tiền tối thiểu cho người dùng rút tiền', 10, 1, 0, 0, 0),
(59, 'routine_appId', 'text', 'input', 132, '', 0, '', 100, 0, '\"\"', 'appId', 'Chương trình nhỏappID', 100, 1, 0, 0, 0),
(60, 'routine_appsecret', 'text', 'input', 132, '', 0, '', 100, 0, '\"\"', 'AppSecret', 'Chương trình nhỏAppSecret', 99, 1, 0, 0, 0),
(61, 'api', 'text', 'input', 131, '', 1, '', 0, 0, '\"\\/api\\/wechat\\/serve\"', 'địa chỉ giao diện', 'Định cấu hình địa chỉ giao diện được sử dụng bởi tên miền máy chủ và sao chép trực tiếp nội dung của hộp nhập liệu (điều này do hệ thống tạo ra và không thể sửa đổi)）', 92, 1, 0, 0, 0),
(74, 'routine_name', 'text', 'input', 132, '', 0, '', 100, 0, '\"\"', 'Tên chương trình nhỏ', 'Tên chương trình nhỏ', 98, 1, 0, 0, 0),
(77, 'store_stock', 'text', 'number', 120, '', 1, '', 0, 0, '\"10\"', 'cổ phiếu cảnh báo', 'Khi số lượng sản phẩm tồn kho thấp hơn số lượng nhất định sẽ báo rằng lượng hàng tồn kho không đủ.', 0, 1, 0, 0, 0),
(85, 'stor_reason', 'textarea', 'input', 71, '', 1, '', 100, 8, '\"\\u6536\\u8d27\\u5730\\u5740\\u586b\\u9519\\u4e86\\n\\u4e0e\\u63cf\\u8ff0\\u4e0d\\u7b26\\n\\u4fe1\\u606f\\u586b\\u9519\\u4e86\\uff0c\\u91cd\\u65b0\\u62cd\\n\\u6536\\u5230\\u5546\\u54c1\\u635f\\u574f\\u4e86\\n\\u672a\\u6309\\u9884\\u5b9a\\u65f6\\u95f4\\u53d1\\u8d27\\n\\u5176\\u5b83\\u539f\\u56e0\"', 'Lý do trả lại', 'Định cấu hình lý do trả lại, một lý do trên mỗi dòng', 0, 1, 0, 0, 0),
(87, 'store_brokerage_two', 'text', 'input', 73, '', 0, 'required:true,min:0,max:100,number:true', 100, 0, '\"0\"', 'Tỷ lệ chiết khấu cấp 2', 'Tỷ lệ chiết khấu hoa hồng được trao cho cấp trên sau khi lệnh được giao dịch thành công.0 - 100,ví dụ:5 = Hoàn lại số tiền đặt hàng5%', 4, 1, 0, 0, 0),
(88, 'store_brokerage_statu', 'radio', '', 72, '1=>phân phối được chỉ định\n2=>Phân phối Renren\n3=>Phân phối đầy đủ', 0, '', 0, 0, '1', 'Mô hình phân phối', 'Phân phối Renren”Theo mặc định mọi người đều có thể phân phối，“phân phối được chỉ định”Người quảng bá chỉ có thể được đặt thủ công ở chế độ nền，“Phân phối đầy đủ”Đề cập đến việc bắt đầu phân phối tự động sau khi người dùng mua hàng và đáp ứng đủ số lượng tiêu thụ.', 95, 1, 0, 0, 0),
(99, 'user_extract_bank', 'textarea', '', 74, '', 0, '', 100, 5, '\"\\u4e2d\\u56fd\\u94f6\\u884c\"', 'Thẻ ngân hàng rút tiền mặt', 'Cấu hình loại thẻ ngân hàng để rút tiền mặt và thay đổi loại thẻ ngân hàng cho từng ngân hàng', 9, 1, 0, 0, 0),
(108, 'upload_type', 'radio', '', 31, '1=>lưu trữ cục bộ\n2=>Lưu trữ đám mây Qiniu\n3=>Đám mây của AlibabaOSS\n4=>TencentCOS', 1, '', 0, 0, '\"1\"', 'Loại tải lên', 'Cấu hình lưu trữ tệp, lưu ý: sau khi đã định cấu hình, đừng dễ dàng sửa đổi nó, vì nó sẽ khiến tệp không thể sử dụng được.', 100, 1, 0, 0, 0),
(110, 'accessKey', 'text', 'input', 32, '', 0, '', 100, 0, '\"\"', 'Lưu trữ đám mây trên nền tảng đám mây của AlibabaaccessKey', 'accessKey', 0, 1, 0, 0, 0),
(111, 'secretKey', 'text', 'input', 32, '', 0, '', 100, 0, '\"\"', 'Lưu trữ đám mây trên nền tảng đám mây của AlibabasecretKey', 'secretKey', 0, 1, 0, 0, 0),
(113, 'order_cancel_time', 'text', 'number', 115, '', 1, '', 0, 0, '\"1\"', 'Hủy các đơn hàng chưa thanh toán thông thường', 'Thời gian tự động hủy đối với các đơn hàng chưa thanh toán đối với mặt hàng thông thường, đơn vị tính (giờ)）', 0, 1, 0, 0, 0),
(114, 'order_activity_time', 'text', 'number', 115, '', 1, '', 0, 0, '\"1\"', 'Sự kiện hủy đơn hàng chưa thanh toán', 'Thời gian tự động hủy đối với các đơn hàng chưa thanh toán của sản phẩm đang hoạt động, đơn vị (giờ)）', 0, 1, 0, 0, 0),
(115, 'order_bargain_time', 'text', 'number', 115, '', 1, '', 0, 0, '\"1\"', 'Thương lượng giá, hủy đơn hàng chưa thanh toán', 'Thời gian hủy tự động đối với các đơn hàng chưa thanh toán sau khi thương lượng, đơn vị (giờ), nếu bằng 0 thì thời gian hủy sự kiện mặc định sẽ được sử dụng và cấu hình sự kiện riêng lẻ sẽ được sử dụng trước tiên.', 0, 1, 0, 0, 0),
(116, 'order_seckill_time', 'text', 'number', 115, '', 1, '', 0, 0, '\"1\"', 'Hủy đơn hàng flash sale chưa thanh toán', 'Thời gian hủy tự động đối với các đơn hàng chưa thanh toán trong flash sale, đơn vị (giờ), nếu bằng 0, thời gian hủy sự kiện mặc định sẽ được sử dụng và cấu hình sự kiện riêng lẻ sẽ được sử dụng trước tiên.', 0, 1, 0, 0, 0),
