(453, 'sign_remind_type', 'checkbox', 'input', 126, '1=>Tin nhắn ngắn\n2=>Thông báo trang web', 1, '', 0, 0, '[\"1\",\"2\"]', 'Phương pháp nhắc nhở', 'Phương pháp nhắc nhở để nhắc nhở đăng nhập hàng ngày, hỗ trợ tin nhắn văn bản và tin nhắn trong trang web', 80, 1, 0, 0, 0),
(454, 'sign_give_point', 'text', 'number', 126, '', 1, '', 0, 0, '0', 'Đăng nhập và nhận điểm thưởng', 'Điểm sẽ được cộng khi đăng nhập và điểm sẽ được cộng khi đăng nhập mỗi ngày.', 75, 1, 0, 0, 0),
