(464, 'routine_encodingaeskey', 'text', 'input', 133, '', 1, '', 0, 0, '\"\"', 'EncodingAESKey', 'Khóa mã hóa tin nhắn bao gồm 43 ký tự và phạm vi ký tự làA-Z,a-z,0-9', 0, 1, 0, 0, 0),
(465, 'model_checkbox', 'checkbox', 'input', 134, 'seckill=>bán chớp nhoáng\nbargain=>Mặc cả\ncombination=>Chia sẻ nhóm', 1, '', 0, 0, '[\"seckill\",\"bargain\",\"combination\"]', 'Cấu hình mô-đun', 'Cấu hình mô-đun, chọn hiển thị mô-đun tương ứng, bỏ chọn nó và mặt trước và mặt sau sẽ không hiển thị nội dung liên quan đến mô-đun.', 0, 1, 0, 0, 0),
(466, 'sp_appid', 'text', 'input', 4, '', 1, '', 100, 0, '\"\"', 'thương gia chínhAPPID', 'Để kích hoạt thanh toán cho nhà cung cấp dịch vụ, bạn cần định cấu hình tài khoản dịch vụ chính thức được mở khi người bán chính đăng ký.APPID', 0, 1, 0, 0, 0),
(467, 'brokerage_window_switch', 'radio', 'input', 72, '1=>bật lên\n0=>đóng cửa', 1, '', 0, 0, '1', 'Công tắc cửa sổ nổi hoa hồng', 'Ủy ban chuyển đổi cửa sổ nổi. Sau khi tắt, chi tiết sản phẩm sẽ không hiển thị cửa sổ nổi hoa hồng.', 0, 1, 0, 0, 0),
(468, 'elec_invoice', 'radio', 'input', 18, '1=>bật lên\n0=>đóng cửa', 1, '', 0, 0, '\"0\"', 'Tình trạng hóa đơn điện tử', 'Có bật hóa đơn điện tử hay không', 0, 0, 0, 0, 0),
(469, 'auto_invoice', 'radio', 'input', 18, '1=>bật lên\n0=>đóng cửa', 1, '', 0, 0, '\"0\"', 'Có tự động lập hóa đơn hay không', 'Có nên bật chức năng lập hóa đơn tự động hay không', 0, 0, 0, 0, 0),
(470, 'elec_invoice_cate', 'text', 'input', 18, '', 1, '', 100, 0, '\"0\"', 'Phân loại hóa đơn điện tử', 'Phân loại sản phẩm hóa đơn điện tử', 0, 0, 0, 0, 0),
(471, 'elec_invoice_tax_rate', 'text', 'input', 18, '', 1, '', 100, 0, '\"0\"', 'Thuế suất hóa đơn điện tử', 'Vui lòng điền thuế suất của hóa đơn điện tử, điền số nguyên trực tiếp từ 0 đến 100, ví dụ: điền thuế suất 13%13', 0, 0, 0, 0, 0),
(472, 'elec_invoice_cate_name', 'text', 'input', 18, '', 1, '', 100, 0, '\"\"', 'Tên loại hóa đơn', 'Tên tương ứng với loại hóa đơn điện tử, dùng để phản biện', 0, 0, 0, 0, 0),
(473, 'get_remote_login_url', 'text', 'input', 135, '', 1, '', 100, 0, '\"\"', 'Địa chỉ đăng nhập từ xa', 'Trung tâm nhúng nhảy trang h5 mang liên kết（remote_token=Token) do người dùng từ xa tạo ra, bạn có thể tự động đăng nhập vào trung tâm mua sắm. Nếu remote_token trống, hệ thống xác định rằng bạn chưa đăng nhập vào hệ thống bên ngoài và sẽ chuyển đến địa chỉ này để đăng nhập.', 0, 1, 0, 0, 0),
(474, 'param_filter_data', 'textarea', 'input', 137, '', 1, '', 100, 20, '\"L1wuXC4vCi9cPFw\\/LwovXGJvclxiLio9LiovaQovKHNlbGVjdFtcc1xTXSo\\/KShmcm9tfGxpbWl0KS9pCi8odW5pb25bXHNcU10qP3NlbGVjdCkvaQovKGhhdmluZ3x1cGRhdGV4bWx8ZXh0cmFjdHZhbHVlKS9pCi9zbGVlcFwoKFxzKikoXGQqKShccyopXCkvaQovYmVuY2htYXJrXCgoLiopXCwoLiopXCkvaQovYmFzZTY0X2RlY29kZVwoL2kKLyg\\\\/KD86bHN8cHdkfHdob2FtaXxsbHxpZmNvbmZpZ3xpcGNvbmZpZ3wmJnxjaG1vZHxjZHxta2RpcnxybWRpcnxjcHxtdikvaQovXHNhbmRccysuKj0uKi9p\"', 'WAFCấu hình', 'WAFĐịnh cấu hình các tham số xác minh, lọc ra các tham số không cần thiết hoặc chặn các yêu cầu. Nhiều tham số được phân tách bằng cách xuống dòng và nạp dòng.', 0, 1, 0, 0, 0),
(475, 'product_reply_examine', 'radio', 'input', 136, '1=>Cần xem xét\n0=>Không cần xem xét', 1, '', 0, 0, '1', 'kiểm duyệt bình luận', 'Việc người dùng gửi đánh giá sản phẩm có cần xem xét lý lịch hay không. Nếu có, nó sẽ được hiển thị sau khi quá trình xem xét hoàn tất. Nếu không cần đánh giá, nó sẽ được hiển thị sau khi người dùng gửi đánh giá.', 0, 1, 0, 0, 0),
(476, 'reward_coupon', 'text', 'input', 105, '', 1, '', 100, 0, '', 'Tặng phiếu giảm giá', 'Tặng phiếu giảm giá', 0, 0, 0, 0, 0),
(477, 'param_filter_type', 'radio', 'input', 137, '0=>đóng cửa\n1=>chặn\n2=>lọc', 1, '', 0, 0, '2', 'WAFkiểu', 'WAFLoại: Đóng (tất cả các tham số có thể được yêu cầu bình thường), chặn (các tham số khớp với yêu cầu giao diện khối cấu hình WAF), lọc (các tham số khớp với các tham số bộ lọc cấu hình WAF và giao diện có thể được yêu cầu bình thường)）', 10, 1, 0, 0, 0),
(478, 'product_type_config', 'checkbox', 'input', 136, '0=>Hàng thông thường\n1=>Thẻ bí mật/đĩa mạng\n2=>Phiếu giảm giá\n3=>hàng ảo', 1, '', 0, 0, '[\"0\",\"1\",\"2\",\"3\"]', 'Cấu hình loại sản phẩm', 'Cấu hình loại sản phẩm, bạn có thể định cấu hình các loại sản phẩm có thể được chọn khi thêm sản phẩm', 1, 1, 0, 0, 0),
(479, 'weixin_extract_type', 'radio', 'input', 74, '0=>Chuyển ngoại tuyến thủ công\n1=>Tự động chuyển để thay đổi', 1, '', 0, 0, '0', 'Rút tiền mặt WeChat', 'Phương thức rút tiền mặt WeChat: chuyển ngoại tuyến thủ công, chuyển tự động để thay đổi(Cần mở cửa hàng để chuyển tiền đổi)', 7, 1, 0, 0, 0),
(480, 'alipay_extract_type', 'radio', 'input', 74, '0=>Chuyển ngoại tuyến thủ công\n1=>Tự động chuyển về số dư', 1, '', 0, 0, '0', 'Rút tiền mặt Alipay', 'Phương thức rút tiền mặt Alipay: chuyển ngoại tuyến thủ công, chuyển tự động về số dư(Cần kích hoạt chuyển khoản Alipay)', 6, 1, 0, 0, 0),
(481, 'v3_pay_public_key', 'text', 'input', 4, '', 1, '', 100, 0, '\"\"', 'v3Trả khóa công khai', 'v3Thanh toán public key, vui lòng điền public key cho phiên bản mới', 0, 1, 0, 0, 0),
(482, 'v3_pay_public_pem', 'upload', 'input', 4, '', 3, '', 0, 0, '\"\"', 'v3Trả chứng chỉ khóa công khai', 'v3Chứng chỉ khóa công khai thanh toán, sử dụng phiên bản khóa chung thanh toán mới để tải chứng chỉ này lên', 0, 1, 0, 0, 0),
(483, 'v3_transfer_scene_id', 'text', 'input', '4', '', '1', '', '0', '0', '\"1000\"', 'WeChat tự động đề cập đến giá trị cảnh', 'WeChat tự động đề cập đến giá trị cảnh', 0, 1, 0, 0, 0),
(484, 'custom_admin_js', 'textarea', 'input', 123, '', 1, '', 100, 10, '\"\"', 'Tùy chỉnh bên quản lýJS', 'Các tùy chỉnh được tải ở phía quản lýJS', 0, 1, 0, 0, 0),
(485, 'custom_pc_js', 'textarea', 'input', 123, '', 1, '', 100, 10, '\"\"', 'PCKết thúc tùy chỉnhJS', 'Các tùy chỉnh được tải trên PCJS', 0, 1, 0, 0, 0),
(486, 'merchant_cert_path', 'upload', 'input', 63, '', 3, '', 0, 0, '\"\"', 'Áp dụng chứng chỉ khóa công khai', 'Chứng chỉ khóa công khai của ứng dụng được tải xuống sau khi giao diện Alipay được ký.', 0, 1, 1, 489, 1),
(487, 'alipay_cert_path', 'upload', 'input', 63, '', 3, '', 0, 0, '\"\"', 'Chứng chỉ khóa công khai của Alipay', 'Giao diện Alipay đã ký chứng chỉ khóa công khai Alipay đã tải xuống', 0, 1, 1, 489, 1),
(488, 'alipay_root_cert_path', 'upload', 'input', 63, '', 3, '', 0, 0, '\"\"', 'Chứng chỉ gốc Alipay', 'Giao diện Alipay đã ký chứng chỉ gốc Alipay đã tải xuống', 0, 1, 1, 489, 1),
(489, 'alipay_sign_type', 'radio', 'input', 63, '0=>chìa khóa\n1=>Giấy chứng nhận', 1, '', 0, 0, '0', 'Kiểu ký giao diện', 'Loại ký giao diện: khóa hoặc chứng chỉ', 80, 1, 0, 0, 0),
(490, 'image_thumb_status', 'radio', 'input', 31, '1=>bật lên\n0=>đóng cửa', 1, '', 0, 0, '0', 'Công tắc hình thu nhỏ', 'Có bật hình thu nhỏ hay không', 0, 1, 0, 0, 0);
