INSERT INTO `eb_system_notification` (`id`, `mark`, `name`, `title`, `is_system`, `system_title`, `system_text`, `is_wechat`, `wechat_tempkey`, `wechat_content`, `wechat_kid`, `wechat_tempid`, `is_routine`, `routine_tempkey`, `routine_content`, `routine_kid`, `routine_tempid`, `is_sms`, `sms_id`, `sms_text`, `is_ent_wechat`, `ent_wechat_text`, `url`, `is_app`, `app_id`, `variable`, `type`, `add_time`) VALUES
(1, 'verify_code', 'Mã xác minh SMS', 'Mã xác minh SMS', 0, 'Mã xác minh SMS', 'Mã xác minh của bạn là：{code}，Hợp lệ cho{time}phút. Nếu nó không phải do mình thực hiện, xin vui lòng bỏ qua nó.。', 0, '', '', '', '', 0, '', '', '', '', 1, '538393', 'Mã xác minh của bạn là：{$code}，Hợp lệ cho{$time}phút. Nếu nó không phải do mình thực hiện, xin vui lòng bỏ qua nó.。', 0, '', '', 0, 0, '', 1, 0),
(2, 'bind_spread_uid', 'Ràng buộc thông điệp mối quan hệ quảng cáo', 'Ràng buộc thông điệp mối quan hệ quảng cáo', 1, 'Ràng buộc thông báo cấp dưới', 'Xin chúc mừng, một thành viên mạnh mẽ khác sẽ gắn bó vĩnh viễn với nhóm của bạn, người dùng{nickname}Tham gia nhóm của bạn！', 0, '', '', '', '', 0, '', '', '', '', 0, '', '', 0, '', '', 0, 0, '{nikename}tên người dùng', 1, 0),
